  private setRoomOwner = async (socket: Socket, raw: unknown) => {
    const data = raw as {
      undo: boolean;
    };
    if (!data) {
      return;
    }
    if (!postgres) {
      socket.emit("errorMessage", "Database is not available");
      return;
    }
    const { uid } = socket;
    if (data.undo) {
      const expiresAt = new Date(Date.now() + 3 * 60 * 60 * 1000);
      this.expiresAt = expiresAt;
      this.status = 'active';
      this.isPermanent = false;
      await updateObject(
        postgres,
        "rooms",
        {
          passcode: null,

          isChatDisabled: false,
          isSubRoom: null,
          roomTitle: "Watch Party Room",
          roomDescription: null,
          mediaPath: null,
          expiresAt: expiresAt,
          status: 'active',
          isPermanent: false,
        },
        { roomId: this.roomId },
      );
      socket.emit("REC:getRoomState", {});
    } else {
      // validate room count
      const roomCount = (
        await postgres.query(
          'SELECT count(1) from room where owner_id = $1 AND "roomId" != $2',
          [uid, this.roomId],
        )
      ).rows[0].count;
      const limit = config.SUBSCRIBER_ROOM_LIMIT;
      if (roomCount >= limit) {
        socket.emit(
          "errorMessage",
          `You've exceeded the permanent room limit. Subscribe for additional permanent rooms.`,
        );
        return;
      }
      const roomObj = {
        roomId: this.roomId,
        owner_id: uid,
        isSubRoom: true,
        expiresAt: null,
        status: 'active',
        isPermanent: true,
      };
      this.expiresAt = undefined;
      this.status = 'active';
      this.owner_id = uid;
      this.isPermanent = true;
      let result: QueryResult | null = null;
      result = await upsertObject(postgres, "rooms", roomObj, {
        roomId: true,
      });
      const row = result?.rows?.[0];
      // console.log(result, row);
      socket.emit("REC:getRoomState", {
        passcode: row?.passcode,

        owner: row?.owner_id,
      });
    }
  };

  private getRoomState = async (socket: Socket) => {
    if (!postgres) {
      return;
    }
    const result = await postgres.query(
      `SELECT passcode, owner_id, "isChatDisabled", "roomTitle", "roomDescription", "mediaPath" FROM rooms where "roomId" = $1`,
      [this.roomId],
    );
    const first = result.rows[0];
    if (this.isChatDisabled === undefined) {
      this.isChatDisabled = Boolean(first?.isChatDisabled);
    }
    socket.emit("REC:getRoomState", {
      owner: first?.owner_id,
      isChatDisabled: first?.isChatDisabled,
      roomTitle: first?.roomTitle,
      roomDescription: first?.roomDescription,
      mediaPath: first?.mediaPath,
      isWaitingLoungeEnabled: this.isWaitingLoungeEnabled,
      isVBrowserEnabled: isVBrowserEnabled(),
      // Lifecycle fields - authoritative from server
      status: this.status,
      startedAt: this.startedAt ? this.startedAt.toISOString() : null,
      expiresAt: this.expiresAt ? this.expiresAt.toISOString() : null,
      isPermanent: this.isPermanent,
      durationMinutes: this.durationMinutes,
      serverNow: Date.now(),
    });
  };

  private setRoomState = async (socket: Socket, raw: unknown) => {
    const data = raw as {
      passcode: string;

      isChatDisabled: boolean;
      roomTitle: string;
      roomDescription: string;
      mediaPath: string;
    };
    if (!postgres) {
      socket.emit("errorMessage", "Database is not available");
      return;
    }
    if (!data) {
      return;
    }
    const {
      passcode,

      isChatDisabled,
      roomTitle,
      roomDescription,
      mediaPath,
    } = data;
    if (passcode) {
      if (passcode.length > 100) {
        socket.emit("errorMessage", "Password too long");
        return;
      }
    }

    let normalizedTitle: string | undefined = undefined;
    if (typeof roomTitle !== "undefined") {
      normalizedTitle = typeof roomTitle === "string" ? roomTitle.trim() : "";
      if (normalizedTitle.length === 0) {
        socket.emit("errorMessage", "Room title is required");
        return;
      }
      if (normalizedTitle.length > 50) {
        socket.emit("errorMessage", "Room title too long");
        return;
      }
    }
    if (roomDescription && roomDescription.length > 120) {
      socket.emit("errorMessage", "Room description too long");
      return;
    }

    if (mediaPath && mediaPath.length > 1000) {
      socket.emit("errorMessage", "Media source too long");
      return;
    }

    const roomObj: any = {
      roomId: this.roomId,
      passcode: await hashRoomPasscode(passcode),
      isChatDisabled: isChatDisabled,
      mediaPath: mediaPath,
    };
    const { uid } = socket;
    if (uid) {
      if (normalizedTitle !== undefined) roomObj.roomTitle = normalizedTitle;
      if (roomDescription !== undefined) roomObj.roomDescription = roomDescription;
    }

    // Remove undefined fields so they aren't part of the Postgres UPDATE query
    Object.keys(roomObj).forEach(key => roomObj[key] === undefined && delete roomObj[key]);
    try {
      const query = `UPDATE rooms
        SET ${Object.keys(roomObj).map((k, i) => `"${k}" = $${i + 1}`)}
        WHERE "roomId" = $${Object.keys(roomObj).length + 1}
        AND owner_id = $${Object.keys(roomObj).length + 2}
        RETURNING *`;
      const result = await postgres.query(query, [
        ...Object.values(roomObj),
        this.roomId,
        uid,
      ]);
      const row = result.rows[0];
      this.isChatDisabled = Boolean(row?.isChatDisabled);
      this.emitToRoom("REC:getRoomState", {
        owner: row?.owner_id,
        isChatDisabled: row?.isChatDisabled,
        roomTitle: row?.roomTitle,
        roomDescription: row?.roomDescription,
        mediaPath: row?.mediaPath,
        isWaitingLoungeEnabled: this.isWaitingLoungeEnabled,
      });
      socket.emit("successMessage", "Saved admin settings");
    } catch (e) {
      console.warn(e);
    }
  };

  private sendSignal = (
    socket: Socket,
    raw: unknown,
    eventName: "signal" | "signalSS",
  ) => {
    const data = raw as { to: string; msg: string; sharer?: boolean };
    if (!data) {
      return;
    }
    const fromClientId = socket.clientId;
    const toId = this.socketIdMap[data.to];
    if (toId) {
      this.io.of(this.roomId).to(toId).emit(eventName, {
        from: fromClientId,
        msg: data.msg,
        sharer: data.sharer,
      });
    }
  };

  public emitToRoom = (eventName: string, ...args: any[]) => {
    this.io.of(this.roomId).to("admitted").emit(eventName, ...args);
  };

  private isAdmitted = (socket: Socket): boolean => {
    if (!this.isWaitingLoungeEnabled) {
      return true;
    }
    // Host is always admitted
    if (socket.uid && this.owner_id && socket.uid === this.owner_id) {
      return true;
    }
    // Check by clientId unconditionally (session-based admission)
    if (socket.clientId && this.admittedClientIds.has(socket.clientId)) {
      return true;
    }
    // Authenticated guest: check UID
    if (socket.uid && this.admittedUids.has(socket.uid)) {
      return true;
    }
    return false;
  };

  private getHostInfo = async (): Promise<{ name: string; picture: string; online: boolean }> => {
    let online = false;
    let name = "Host";
    let picture = "";

    if (this.owner_id) {
      const sockets = Array.from(this.io.of(this.roomId).sockets.values());
      const hostSocket = sockets.find((s) => s.uid === this.owner_id);
      if (hostSocket) {
        online = true;
        if (this.nameMap[hostSocket.clientId]) {
          name = this.nameMap[hostSocket.clientId];
        }
        if (this.pictureMap[hostSocket.clientId]) {
          picture = this.pictureMap[hostSocket.clientId];
        }
      }

      if (!picture || name === "Host") {
        if (postgres) {
          try {
            const res = await postgres.query(
              "SELECT display_name, username, avatar_url FROM profiles WHERE id = $1 LIMIT 1",
              [this.owner_id]
            );
            if (res.rows && res.rows.length > 0) {
              const row = res.rows[0];
              if (name === "Host" && (row.display_name || row.username)) {
                name = (row.display_name?.trim() || row.username?.trim()) || "Host";
              }
              if (!picture && row.avatar_url) {
                picture = row.avatar_url;
              }
            }
          } catch (e) {
            console.warn("Failed to fetch host profile for waiting lounge", e);
          }
        }
      }
    }

    return { name, picture, online };
  };

  private emitWaitingLoungeState = async (socket: Socket) => {
    const host = await this.getHostInfo();
    const queueKeys = Array.from(this.waitingLounge.keys());
    const positionIndex = queueKeys.indexOf(socket.clientId);
    const position = positionIndex >= 0 ? positionIndex + 1 : 1;

    const payload: WaitingLoungeState = {
      inLounge: true,
      waitingCount: this.waitingLounge.size,
      position,
      host,
    };
    socket.emit("REC:waitingLounge", payload);
  };

  private broadcastWaitingLoungeStateToWaitingGuests = async () => {
    if (this.waitingLounge.size === 0) return;
    const host = await this.getHostInfo();
    const queueKeys = Array.from(this.waitingLounge.keys());

    for (let i = 0; i < queueKeys.length; i++) {
      const clientId = queueKeys[i];
      const socketId = this.socketIdMap[clientId];
      if (socketId) {
        const socket = this.io.of(this.roomId).sockets.get(socketId);
        if (socket) {
          const payload: WaitingLoungeState = {
            inLounge: true,
            waitingCount: this.waitingLounge.size,
            position: i + 1,
            host,
          };
          socket.emit("REC:waitingLounge", payload);
        }
      }
    }
  };

  private getWaitingList = (): WaitingGuest[] => {
    return Array.from(this.waitingLounge.values()).map((guest) => ({
      clientId: guest.clientId,
      socketId: guest.socketId,
      uid: guest.uid,
      name: this.nameMap[guest.clientId] || guest.name || "Guest",
      picture: this.pictureMap[guest.clientId] || guest.picture || "",
      joinedAt: guest.joinedAt,
    }));
  };

  private broadcastWaitingListToHost = () => {
    if (!this.owner_id) return;
    const list = this.getWaitingList();
    const sockets = Array.from(this.io.of(this.roomId).sockets.values());
    const hostSockets = sockets.filter((s) => s.uid === this.owner_id);
    for (const hostSocket of hostSockets) {
      hostSocket.emit("REC:waitingList", list);
    }
  };

  private admitGuest = async (clientId: string) => {
    const guest = this.waitingLounge.get(clientId);
    if (!guest) return;

    this.admittedClientIds.add(clientId);
    if (guest.uid) {
      this.admittedUids.add(guest.uid);
    }

    this.waitingLounge.delete(clientId);

    if (!this.roster.find((u) => u.id === clientId)) {
      this.roster.push({ id: clientId });
    }

    const socketId = this.socketIdMap[clientId];
    const socket = socketId ? this.io.of(this.roomId).sockets.get(socketId) : undefined;
    if (socket) {
      if (socket.uid) {
        this.admittedUids.add(socket.uid);
      }
      void socket.join("admitted");
      socket.emit("REC:waitingLounge", { inLounge: false });

      socket.emit("REC:host", this.getHostState());
      socket.emit("REC:nameMap", this.nameMap);
      socket.emit("REC:pictureMap", this.pictureMap);
      socket.emit("REC:tsMap", this.tsMap);
      socket.emit("REC:lock", this.lock);

      const recentMessages = await loadRoomMessages(this.roomId, 50);
      const formattedMessages = recentMessages.map((row: any) => ({
        id: row.metadata?.clientId || "unknown",
        msg: row.message,
        cmd: row.event_type || undefined,
        timestamp: row.created_at.toISOString(),
        videoTS: row.metadata?.videoTS,
        dbId: row.id,
        name: row.profile_name || row.metadata?.name,
        picture: row.profile_picture || row.metadata?.picture,
        userId: row.user_id || undefined,
        updatedAt: row.updated_at ? row.updated_at.toISOString() : undefined,
      }));
      socket.emit("chatinit", formattedMessages.reverse());
      socket.emit("ROOM_MESSAGES", formattedMessages);
      socket.emit("playlist", this.playlist);
      void this.getRoomState(socket);
    }

    this.emitToRoom("roster", this.getRosterForApp());
    void this.broadcastWaitingLoungeStateToWaitingGuests();
    this.broadcastWaitingListToHost();
  };

  private admitAllGuests = async () => {
    const clientIds = Array.from(this.waitingLounge.keys());
    for (const clientId of clientIds) {
      await this.admitGuest(clientId);
    }
  };

  private declineGuest = (clientId: string) => {
    const guest = this.waitingLounge.get(clientId);
    if (!guest) return;

    this.waitingLounge.delete(clientId);

    const socketId = this.socketIdMap[clientId];
    const socket = socketId ? this.io.of(this.roomId).sockets.get(socketId) : undefined;
    if (socket) {
      socket.emit("REC:waitingLounge", {
        inLounge: true,
        rejected: true,
      });
    }

    void this.broadcastWaitingLoungeStateToWaitingGuests();
    this.broadcastWaitingListToHost();
  };

  private onDisconnect = (socket: Socket) => {
    const { clientId } = socket;

    if (this.waitingLounge.has(clientId)) {
      this.waitingLounge.delete(clientId);
      void this.broadcastWaitingLoungeStateToWaitingGuests();
      this.broadcastWaitingListToHost();
    }

    // Disconnecting socket is the current one
    if (socket.id === this.socketIdMap[clientId]) {
      let index = this.roster.findIndex((user) => user.id === clientId);
      if (index > -1) {
        this.roster.splice(index, 1);
      }
      this.emitToRoom("roster", this.getRosterForApp());
      delete this.tsMap[clientId];
      delete this.socketIdMap[clientId];

      if (socket.uid && this.owner_id && socket.uid === this.owner_id) {
        void this.broadcastWaitingLoungeStateToWaitingGuests();
      }

      if (this.roster.length === 0) {
        if (this.inactivityTimeout) clearTimeout(this.inactivityTimeout);
        this.inactivityTimeout = setTimeout(async () => {
          if (this.roster.length === 0 && this.status === 'active') {
            this.status = 'inactive';
            this.lastUpdateTime = new Date();
            if (postgres) {
              await updateObject(postgres, "rooms", { status: 'inactive', "lastActiveAt": new Date() }, { "roomId": this.roomId });
            }
          }
        }, 120 * 1000);
      }
    }
    // Keep namemap/picturemap so old chat messages still render correctly after disconnect
    // When serializing we only write values with messages in chat
    // This will keep growing in memory until the room is unloaded
  };

  private kickUser = async (raw: unknown) => {
    const data = raw as { userToBeKicked: string };
    if (!data || !data.userToBeKicked) {
      return;
    }
    const userToBeKickedSocket = this.io
      .of(this.roomId)
      .sockets.get(this.socketIdMap[data.userToBeKicked]);
    if (
      this.owner_id &&
      (data.userToBeKicked === this.owner_id ||
        userToBeKickedSocket?.uid === this.owner_id)
    ) {
      return;
    }
    this.admittedClientIds.delete(data.userToBeKicked);
    if (userToBeKickedSocket) {
      if (userToBeKickedSocket.uid) {
        this.admittedUids.delete(userToBeKickedSocket.uid);
      }
      void userToBeKickedSocket.leave("admitted");
      userToBeKickedSocket.emit("kicked");
      userToBeKickedSocket.disconnect();
    }
  };

  public disconnectAllSockets = () => {
    this.io.of(this.roomId).disconnectSockets();
  };

  private deleteChatMessages = async (raw: unknown) => {
    const data = raw as {
      author?: string;
      timestamp?: string;
    };
    if (!data) return;

    if (postgres) {
      if (!data.timestamp && !data.author) {
        // Clear all
        await postgres.query(`DELETE FROM room_messages WHERE room_id = $1`, [this.roomId]);
      } else if (data.timestamp && data.author) {
        // Delete specific message
        await postgres.query(`DELETE FROM room_messages WHERE room_id = $1 AND (user_id = $2 OR metadata->>'clientId' = $2) AND created_at = $3`, [this.roomId, data.author, data.timestamp]);
      } else if (data.author) {
        // Delete by author
        await postgres.query(`DELETE FROM room_messages WHERE room_id = $1 AND (user_id = $2 OR metadata->>'clientId' = $2)`, [this.roomId, data.author]);
      }
    }

    // Refresh for everyone (legacy UI sync)
    const recentMessages = await loadRoomMessages(this.roomId, 50);
    const formattedMessages = recentMessages.map((row: any) => ({
      id: row.metadata?.clientId || row.user_id,
      msg: row.message,
      cmd: row.event_type || undefined,
      timestamp: row.created_at.toISOString(),
      videoTS: row.metadata?.videoTS,
      dbId: row.id,
    }));
    this.emitToRoom("chatinit", formattedMessages.reverse());
    this.emitToRoom("ROOM_MESSAGES", formattedMessages);
  };

  public disconnectInviteSockets(inviteId: string): void {
    const ns = this.io.of(this.roomId);
    for (const socket of ns.sockets.values()) {
      if (socket.data?.inviteId === inviteId) {
        socket.emit("errorMessage", "Your invitation has been revoked.");
        socket.disconnect(true);
      }
    }
  }
}

function isValidUUID(id: string) {
  return /^[0-9A-F]{8}-[0-9A-F]{4}-[4][0-9A-F]{3}-[89AB][0-9A-F]{3}-[0-9A-F]{12}$/i.test(
    id,
  );
}

import { postgres } from "./utils/postgres.ts";
import type { Server } from "socket.io";
import type { Room } from "./room.ts";

let ioInstance: Server | null = null;
let roomsMap: Map<string, Room> | null = null;

export function initRoomLifecycle(io: Server, rooms: Map<string, Room>) {
  ioInstance = io;
  roomsMap = rooms;
}

export const ALLOWED_DURATION_PRESETS = [30, 60, 120, 180, 300, 360, 720, 1440] as const;
export type AllowedDurationPreset = (typeof ALLOWED_DURATION_PRESETS)[number];

export function validateTemporaryDuration(val: unknown): number {
  const num = typeof val === "number" ? val : Number(val);
  if (!Number.isInteger(num) || !ALLOWED_DURATION_PRESETS.includes(num as any)) {
    throw new Error(
      `Invalid session duration (${val}). Allowed presets are: ${ALLOWED_DURATION_PRESETS.join(", ")} minutes.`
    );
  }
  return num;
}

export interface StartRoomResult {
  success: boolean;
  status: string;
  startedAt: string;
  expiresAt: string | null;
  isPermanent: boolean;
  durationMinutes: number | null;
  serverNow: number;
}

/**
 * Authoritative, single server-side state transition for starting a watch party room.
 * Owned responsibilities:
 * - Owner authorization
 * - State validation (cannot start expired/ended rooms)
 * - Idempotency (if already active, returns active state without resetting timestamps)
 * - Concurrency guard (atomic database transition WHERE status = 'waiting')
 * - startedAt and expiresAt computation (client never calculates expiresAt)
 * - Permanent rooms receive expiresAt = null, durationMinutes = null
 * - Database persistence
 * - Lifecycle audit event logging
 * - In-memory room instance update
 * - Real-time socket broadcast to connected participants
 */
export async function startRoomLifecycle(roomId: string, uid: string | "SYSTEM"): Promise<StartRoomResult> {
  if (!postgres) {
    throw new Error("Database is not configured.");
  }

  const cleanRoomId = roomId.trim();
  const normalizedId = cleanRoomId.startsWith("/") ? cleanRoomId.substring(1) : cleanRoomId;
  const slashedId = `/${normalizedId}`;

  // 1. Fetch current room state from database
  const roomRes = await postgres.query(
    `SELECT "roomId", owner_id, status, "startedAt", "expiresAt", "isPermanent", "durationMinutes", "roomTitle"
     FROM rooms
     WHERE "roomId" = $1 OR "roomId" = $2`,
    [normalizedId, slashedId]
  );

  if (!roomRes || roomRes.rowCount === 0) {
    throw new Error("Room not found.");
  }

  const room = roomRes.rows[0];
  const targetRoomId = room.roomId;

  // 2. Authorization check (skip for system worker)
  if (uid !== "SYSTEM" && room.owner_id !== uid) {
    throw new Error("Only the room owner can start the watch party.");
  }

  const now = new Date();
  const serverNow = now.getTime();

  // 3. Idempotency check: If already active, return existing active state without resetting timer
  if (room.status === "active") {
    return {
      success: true,
      status: "active",
      startedAt: room.startedAt ? new Date(room.startedAt).toISOString() : now.toISOString(),
      expiresAt: room.expiresAt ? new Date(room.expiresAt).toISOString() : null,
      isPermanent: Boolean(room.isPermanent),
      durationMinutes: room.durationMinutes ?? null,
      serverNow,
    };
  }

  // 4. State validation: Reject if ended or expired
  if (room.status === "expired" || room.status === "ended") {
    throw new Error(`Cannot start a room that is ${room.status}.`);
  }

  if (room.status !== "waiting" && room.status !== "scheduled") {
    throw new Error(`Cannot start a room with status '${room.status}'.`);
  }

  // 5. Compute timestamps on the server
  const isPermanent = Boolean(room.isPermanent);
  let expiresAt: Date | null = null;
  const validatedDuration = isPermanent ? null : validateTemporaryDuration(room.durationMinutes);

  if (!isPermanent && validatedDuration !== null) {
    expiresAt = new Date(serverNow + validatedDuration * 60 * 1000);
  }

  // 6. Concurrency guard: Atomic database update
  const isSystem = uid === "SYSTEM";
  const updateRes = isSystem
    ? await postgres.query(
        `UPDATE rooms
         SET
           status = 'active',
           "startedAt" = $1,
           "expiresAt" = $2,
           "lastUpdateTime" = $1,
           "lastActiveAt" = $1
         WHERE "roomId" = $3 AND (status = 'waiting' OR status = 'scheduled')
         RETURNING *`,
        [now, expiresAt, targetRoomId]
      )
    : await postgres.query(
        `UPDATE rooms
         SET
           status = 'active',
           "startedAt" = $1,
           "expiresAt" = $2,
           "lastUpdateTime" = $1,
           "lastActiveAt" = $1
         WHERE "roomId" = $3 AND (status = 'waiting' OR status = 'scheduled') AND owner_id = $4
         RETURNING *`,
        [now, expiresAt, targetRoomId, uid]
      );

  if (updateRes.rowCount === 0) {
    // Another request may have transitioned the room concurrently. Check if active.
    const recheckRes = await postgres.query(
      `SELECT status, "startedAt", "expiresAt", "isPermanent", "durationMinutes"
       FROM rooms WHERE "roomId" = $1`,
      [targetRoomId]
    );
    const recheck = recheckRes.rows[0];
    if (recheck && recheck.status === "active") {
      return {
        success: true,
        status: "active",
        startedAt: new Date(recheck.startedAt).toISOString(),
        expiresAt: recheck.expiresAt ? new Date(recheck.expiresAt).toISOString() : null,
        isPermanent: Boolean(recheck.isPermanent),
        durationMinutes: recheck.durationMinutes ?? null,
        serverNow: Date.now(),
      };
    }
    throw new Error("Failed to transition room to active state.");
  }

  // 7. Audit log in room_lifecycle_events
  try {
    await postgres.query(
      `INSERT INTO room_lifecycle_events
       ("roomId", actor, event, "previousStatus", "newStatus", "previousExpiresAt", "newExpiresAt", reason, timestamp)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
      [
        targetRoomId,
        uid,
        "room.started",
        room.status,
        "active",
        null,
        expiresAt,
        uid === "SYSTEM" ? "scheduled start time reached" : "host started watch party",
        now,
      ]
    );
  } catch (auditErr) {
    console.warn("Failed to write room.started audit event:", auditErr);
  }

  // 8. In-memory Room instance update
  const memoryRoom = roomsMap?.get(targetRoomId) || roomsMap?.get(normalizedId) || roomsMap?.get(slashedId);
  if (memoryRoom) {
    memoryRoom.status = "active";
    memoryRoom.startedAt = now;
    memoryRoom.expiresAt = expiresAt ? expiresAt : undefined;
    memoryRoom.isPermanent = isPermanent;
    memoryRoom.durationMinutes = validatedDuration;
    memoryRoom.lastUpdateTime = now;
  }

  // 9. Authoritative broadcast to all connected clients
  const broadcastPayload = {
    status: "active",
    startedAt: now.toISOString(),
    expiresAt: expiresAt ? expiresAt.toISOString() : null,
    isPermanent,
    durationMinutes: validatedDuration,
    serverNow: Date.now(),
  };

  if (ioInstance) {
    const nspPrimary = ioInstance.of(targetRoomId);
    nspPrimary.emit("REC:roomStarted", broadcastPayload);
    nspPrimary.emit("REC:getRoomState", {
      owner: room.owner_id,
      ...broadcastPayload,
    });

    if (normalizedId !== targetRoomId) {
      const nspNorm = ioInstance.of(normalizedId);
      nspNorm.emit("REC:roomStarted", broadcastPayload);
      nspNorm.emit("REC:getRoomState", {
        owner: room.owner_id,
        ...broadcastPayload,
      });
    }
  }

  return {
    success: true,
    status: "active",
    startedAt: now.toISOString(),
    expiresAt: expiresAt ? expiresAt.toISOString() : null,
    isPermanent,
    durationMinutes: validatedDuration,
    serverNow: Date.now(),
  };
}

export async function cancelRoomLifecycle(roomId: string, uid: string) {
  if (!postgres) throw new Error("Database is not configured.");
  const cleanRoomId = roomId.trim();
  const normalizedId = cleanRoomId.startsWith("/") ? cleanRoomId.substring(1) : cleanRoomId;
  const slashedId = `/${normalizedId}`;

  const roomRes = await postgres.query(
    `SELECT "roomId", owner_id, status FROM rooms WHERE "roomId" = $1 OR "roomId" = $2`,
    [normalizedId, slashedId]
  );
  if (!roomRes || roomRes.rowCount === 0) throw new Error("Room not found.");
  const room = roomRes.rows[0];
  const targetRoomId = room.roomId;

  if (room.owner_id !== uid) throw new Error("Only the room owner can cancel the watch party.");
  if (room.status !== "scheduled") throw new Error(`Cannot cancel a room that is ${room.status}. Only scheduled rooms can be cancelled.`);

  const now = new Date();
  const updateRes = await postgres.query(
    `UPDATE rooms SET status = 'cancelled', "cancelledAt" = $1, "lastUpdateTime" = $1 WHERE "roomId" = $2 AND owner_id = $3 AND status = 'scheduled' RETURNING *`,
    [now, targetRoomId, uid]
  );
  if (updateRes.rowCount === 0) throw new Error("Failed to transition room to cancelled state.");

  try {
    await postgres.query(
      `INSERT INTO room_lifecycle_events
       ("roomId", actor, event, "previousStatus", "newStatus", "previousExpiresAt", "newExpiresAt", reason, timestamp)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
      [
        targetRoomId,
        uid,
        "room.cancelled",
        room.status,
        "cancelled",
        null,
        null,
        "host cancelled scheduled watch party",
        now,
      ]
    );
  } catch (auditErr) {
    console.warn("Failed to write room.cancelled audit event:", auditErr);
  }

  const memoryRoom = roomsMap?.get(targetRoomId) || roomsMap?.get(normalizedId) || roomsMap?.get(slashedId);
  if (memoryRoom) {
    memoryRoom.status = "cancelled";
    memoryRoom.lastUpdateTime = now;
  }
  if (ioInstance) {
    const broadcastPayload = { status: "cancelled", cancelledAt: now.toISOString(), serverNow: Date.now() };
    ioInstance.of(targetRoomId).emit("REC:roomCancelled", broadcastPayload);
    if (normalizedId !== targetRoomId) ioInstance.of(normalizedId).emit("REC:roomCancelled", broadcastPayload);
  }
  return { success: true, status: "cancelled", cancelledAt: now.toISOString() };
}

export async function rescheduleRoomLifecycle(roomId: string, uid: string, newTimestamp: string) {
  if (!postgres) throw new Error("Database is not configured.");
  const parsedDate = new Date(newTimestamp);
  if (isNaN(parsedDate.getTime())) throw new Error("Invalid scheduledStartsAt timestamp");
  if (parsedDate.getTime() <= Date.now()) throw new Error("Scheduled start must be in the future");

  const cleanRoomId = roomId.trim();
  const normalizedId = cleanRoomId.startsWith("/") ? cleanRoomId.substring(1) : cleanRoomId;
  const slashedId = `/${normalizedId}`;

  const roomRes = await postgres.query(
    `SELECT "roomId", owner_id, status FROM rooms WHERE "roomId" = $1 OR "roomId" = $2`,
    [normalizedId, slashedId]
  );
  if (!roomRes || roomRes.rowCount === 0) throw new Error("Room not found.");
  const room = roomRes.rows[0];
  const targetRoomId = room.roomId;

  if (room.owner_id !== uid) throw new Error("Only the room owner can reschedule the watch party.");
  if (room.status !== "scheduled") throw new Error(`Cannot reschedule a room that is ${room.status}.`);

  const updateRes = await postgres.query(
    `UPDATE rooms SET "scheduledStartsAt" = $1, "lastUpdateTime" = NOW() WHERE "roomId" = $2 AND owner_id = $3 AND status = 'scheduled' RETURNING *`,
    [parsedDate, targetRoomId, uid]
  );
  if (updateRes.rowCount === 0) throw new Error("Failed to reschedule room.");

  const memoryRoom = roomsMap?.get(targetRoomId) || roomsMap?.get(normalizedId) || roomsMap?.get(slashedId);
  if (memoryRoom) {
    memoryRoom.scheduledStartsAt = parsedDate;
    memoryRoom.lastUpdateTime = new Date();
  }
  if (ioInstance) {
    const broadcastPayload = { scheduledStartsAt: parsedDate.toISOString(), serverNow: Date.now() };
    ioInstance.of(targetRoomId).emit("REC:roomRescheduled", broadcastPayload);
    if (normalizedId !== targetRoomId) ioInstance.of(normalizedId).emit("REC:roomRescheduled", broadcastPayload);
  }
  return { success: true, scheduledStartsAt: parsedDate.toISOString() };
}

export async function activateDueScheduledRooms() {
  if (!postgres) return;
  try {
    const dueRoomsRes = await postgres.query(`
      SELECT "roomId" FROM rooms WHERE status = 'scheduled' AND "scheduledStartsAt" <= NOW()
    `);
    for (const row of dueRoomsRes.rows) {
      try {
        await startRoomLifecycle(row.roomId, "SYSTEM");
        console.log(`[RoomScheduler] Activated scheduled room ${row.roomId}`);
      } catch (err) {
        console.error(`[RoomScheduler] Failed to activate scheduled room ${row.roomId}:`, err);
      }
    }
  } catch (err) {
    console.error("[RoomScheduler] Failed to query due scheduled rooms:", err);
  }
}

