import { Pool, type PoolClient, type QueryResult } from "pg";
import fs from "node:fs";
import config from "../config.ts";

export type PostgresClient = Pool | PoolClient;

export let postgres: Pool | undefined = undefined;
if (config.DATABASE_URL) {
  postgres = createPool(config.DATABASE_URL);
}

export function normalizePostgresConnectionString(connStr: string): string {
  if (!connStr) return connStr;
  const match = connStr.match(
    /^postgres(?:ql)?:\/\/postgres(?::([^@]*))?@db\.([a-z0-9]+)\.supabase\.co(?::\d+)?\/(.*)$/i,
  );
  if (match) {
    const password = match[1] || "";
    const projectRef = match[2];
    const rest = match[3] || "postgres";
    const region =
      process.env.SUPABASE_REGION ||
      (projectRef === "mbnuunibouzwteoeuyfh"
        ? "ap-south-1"
        : projectRef === "ymsgibplkzuxicwfhefw"
          ? "ap-south-1"
          : "");
    if (region) {
      const cleanRest = rest.split("?")[0];
      const auth = password ? `postgres.${projectRef}:${password}` : `postgres.${projectRef}`;
      const poolerUrl = `postgresql://${auth}@aws-0-${region}.pooler.supabase.com:5432/${cleanRest}`;
      console.log(
        `[PostgreSQL] Direct Supabase host detected. Automatically routed through IPv4 pooler: aws-0-${region}.pooler.supabase.com:5432`,
      );
      return poolerUrl;
    }
  }
  return connStr;
}

function createPool(rawConnectionString: string): Pool {
  const connectionString = normalizePostgresConnectionString(rawConnectionString);
  const strict = String(config.DATABASE_SSL_STRICT || "false").toLowerCase() === "true";
  const caPath = String(config.DATABASE_SSL_CA || "").trim();
  let ca: string | undefined;

  if (caPath) {
    try {
      ca = fs.readFileSync(caPath, "utf8");
    } catch (error) {
      throw new Error(`Unable to read DATABASE_SSL_CA: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  if (!strict && !ca) {
    console.log("[PostgreSQL] TLS certificate verification is disabled. Set DATABASE_SSL_STRICT=true for production.");
  }

  const pool = new Pool({
    connectionString,
    ssl: {
      rejectUnauthorized: strict || Boolean(ca),
      ...(ca ? { ca } : {}),
    },
    max: 20,
    idleTimeoutMillis: 30000,
    connectionTimeoutMillis: 10000,
  });

  pool.on("error", (err) => {
    console.error("PostgreSQL pool idle client error:", err.message);
  });

  return pool;
}

export function newPostgres(): Pool {
  if (!config.DATABASE_URL) throw new Error("postgres not configured");
  return postgres || createPool(config.DATABASE_URL);
}

export async function updateObject(
  postgres: PostgresClient,
  table: string,
  object: AnyDict,
  condition: AnyDict,
): Promise<QueryResult<any>> {
  const columns = Object.keys(object);
  const values = Object.values(object);
  let query = `UPDATE ${table} SET ${columns.map((c, i) => `"${c}" = $${i + 1}`).join(",")}
    WHERE "${Object.keys(condition)[0]}" = $${Object.keys(object).length + 1}
    RETURNING *`;
  const result = await postgres.query(query, [...values, condition[Object.keys(condition)[0]]]);
  return result;
}

export async function insertObject(
  postgres: PostgresClient,
  table: string,
  object: AnyDict,
): Promise<QueryResult<any>> {
  const columns = Object.keys(object);
  const values = Object.values(object);
  let query = `INSERT INTO ${table} (${columns.map((c) => `"${c}"`).join(",")})
    VALUES (${values.map((_, i) => "$" + (i + 1)).join(",")})
    RETURNING *`;
  const result = await postgres.query(query, values);
  return result;
}

export async function upsertObject(
  postgres: PostgresClient,
  table: string,
  object: AnyDict,
  conflict: BooleanDict,
): Promise<QueryResult<any>> {
  const columns = Object.keys(object);
  const values = Object.values(object);
  let query = `INSERT INTO ${table} (${columns.map((c) => `"${c}"`).join(",")})
    VALUES (${values.map((_, i) => "$" + (i + 1)).join(",")})
    ON CONFLICT (${Object.keys(conflict).map((k) => `"${k}"`).join(",")})
    DO UPDATE SET ${Object.keys(object).map((c) => `"${c}" = EXCLUDED."${c}"`).join(",")}
    RETURNING *`;
  const result = await postgres.query(query, values);
  return result;
}

import config from "../config.ts";
import { Redis } from "ioredis";
import { getStartOfHour } from "./time.ts";

export let redis: Redis | undefined = undefined;
if (config.REDIS_URL) {
  try {
    redis = new Redis(config.REDIS_URL, {
      maxRetriesPerRequest: 1,
      retryStrategy: () => null,
    });
    redis.on("error", (err) => {
      console.warn("Redis connection error:", err.message);
    });
  } catch (err: any) {
    console.warn("Failed to initialize Redis:", err.message);
  }
}

export async function redisCount(prefix: string) {
  if (!redis) {
    return;
  }
  try {
    const key = `${prefix}:${getStartOfHour()}`;
    await redis.incr(key);
    await redis.expireat(key, getStartOfHour() + 86400 * 1000);
  } catch (e) {
    console.log(e);
  }
}

export async function getRedisCountDay(prefix: string) {
  if (!redis) {
    return;
  }
  // Get counts for last 24 hour keys (including current partial hour)
  const keyArr = [];
  for (let i = 0; i < 24; i += 1) {
    keyArr.push(`${prefix}:${getStartOfHour() - i * 3600 * 1000}`);
  }
  const values = await redis.mget(...keyArr);
  return values.reduce((a, b) => (Number(a) || 0) + (Number(b) || 0), 0);
}

export async function getRedisCountHour(prefix: string) {
  if (!redis) {
    return;
  }
  // Get counts for previous full hour
  const value = await redis.get(`${prefix}:${getStartOfHour() - 3600 * 1000}`);
  return Number(value);
}

export async function redisCountDistinct(prefix: string, item: string) {
  if (!redis) {
    return;
  }
  const key = `${prefix}:${getStartOfHour()}`;
  await redis.pfadd(key, item);
  await redis.expireat(key, getStartOfHour() + 86400 * 1000);
}

export async function getRedisCountDayDistinct(prefix: string) {
  if (!redis) {
    return;
  }
  // Get counts for last 24 hour keys (including current partial hour)
  const keyArr = [];
  for (let i = 0; i < 24; i += 1) {
    keyArr.push(`${prefix}:${getStartOfHour() - i * 3600 * 1000}`);
  }
  return await redis.pfcount(...keyArr);
}

export async function getRedisCountHourDistinct(prefix: string) {
  if (!redis) {
    return;
  }
  // Get counts for previous full hour
  return await redis.pfcount(`${prefix}:${getStartOfHour() - 3600 * 1000}`);
}

/** This regex searches for YouTube Video IDs from a YouTube URL */
/** example: */
/** YOUTUBE_VIDEO_ID_REGEX.exec('https://youtube.com/?v=14634524364) */
/** will return the id 14634524364 in the first exec group [1] */
export const YOUTUBE_VIDEO_ID_REGEX =
  /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/;

/** These regexes allow us to find hours, minutes and seconds from a ISO 8601 time string */
export const PT_HOURS_REGEX = /(\d{1,2})H/;
export const PT_MINUTES_REGEX = /(\d{1,2})M/;
export const PT_SECONDS_REGEX = /(\d{1,2})S/;

import crypto from "crypto";
import { redis } from "./redis.ts";
import { SecurityLogger } from "./SecurityLogger.ts";

export interface AdmissionRecord {
  roomId: string;
  userId: string | null;
  issuedAt: number;
  expiresAt: number;
}

const ADMISSION_TTL = 3600; // 1 hour
const RATE_LIMIT_WINDOW = 900; // 15 minutes
const RATE_LIMIT_MAX_ATTEMPTS = 5;

/**
 * Generates a cryptographically secure random token and stores it in Redis.
 */
export async function createAdmissionToken(roomId: string, userId: string | null): Promise<string | null> {
  if (!redis) {
    console.error("Redis is unavailable. Denying admission token creation (fail-closed).");
    return null;
  }

  const token = crypto.randomBytes(32).toString("hex");
  const key = `admission:${roomId}:${token}`;
  const now = Date.now();

  const record: AdmissionRecord = {
    roomId,
    userId,
    issuedAt: now,
    expiresAt: now + ADMISSION_TTL * 1000,
  };

  await redis.setex(key, ADMISSION_TTL, JSON.stringify(record));
  return token;
}

/**
 * Retrieves and validates an admission token from Redis.
 */
export async function getAdmissionRecord(roomId: string, token: string): Promise<AdmissionRecord | null> {
  if (!redis) {
    console.error("Redis is unavailable. Denying admission verification (fail-closed).");
    return null;
  }

  const key = `admission:${roomId}:${token}`;
  const data = await redis.get(key);
  if (!data) return null;

  try {
    const record = JSON.parse(data) as AdmissionRecord;
    // Strict defense-in-depth binding validation
    if (record.roomId !== roomId) {
      SecurityLogger.warn("admission.token_binding_mismatch", { 
        expectedRoom: roomId, 
        actualRoom: record.roomId 
      }, "roomAdmission");
      console.warn(`[AdmissionSecurity] Token for room ${record.roomId} used against room ${roomId}`);
      return null;
    }
    if (record.expiresAt && Date.now() > record.expiresAt) {
      return null;
    }
    return record;
  } catch (e) {
    return null;
  }
}

/**
 * Revokes an admission token.
 */
export async function revokeAdmissionToken(roomId: string, token: string): Promise<void> {
  if (redis) {
    await redis.del(`admission:${roomId}:${token}`);
  }
}

/**
 * Rate limits passcode attempts using two dimensions: IP and User ID (if available).
 * Returns true if the attempt is allowed, false if rate limited.
 */
export async function checkRateLimit(roomId: string, ip: string, userId: string | null): Promise<boolean> {
  if (!redis) return true;

  const multi = redis.multi();

  const ipKey = `room-admission:ip:${roomId}:${ip}`;
  multi.incr(ipKey);
  // Only set expiration if not exists. Redis >= 6.2 has EXPIRE with NX
  multi.expire(ipKey, RATE_LIMIT_WINDOW, "NX" as any); 

  if (userId) {
    const userKey = `room-admission:user:${roomId}:${userId}`;
    multi.incr(userKey);
    multi.expire(userKey, RATE_LIMIT_WINDOW, "NX" as any);
  }

  const results = await multi.exec();
  if (!results) return true; // Fail open if Redis error

  const ipAttempts = results[0][1] as number;
  if (ipAttempts > RATE_LIMIT_MAX_ATTEMPTS) {
    SecurityLogger.warn("admission.rate_limit_exceeded", { roomId, ip }, "roomAdmission");
    return false;
  }

  if (userId && results.length >= 3) {
    const userAttempts = results[2][1] as number;
    if (userAttempts > RATE_LIMIT_MAX_ATTEMPTS) {
      SecurityLogger.warn("admission.rate_limit_exceeded", { roomId, userId }, "roomAdmission");
      return false;
    }
  }

  return true;
}

import {
  hashRoomPasscode,
  verifyRoomPasscode,
  isBcryptHash,
  encryptPasscodeForOwner,
  decryptPasscodeForOwner,
} from './roomPasscode.ts';

async function runTests() {
  console.log('Running roomPasscode tests...');

  // Test 1: Empty passcodes
  const h1 = await hashRoomPasscode('');
  if (h1 !== null) throw new Error('Expected null for empty string');
  const h2 = await hashRoomPasscode(null);
  if (h2 !== null) throw new Error('Expected null for null');

  // Test 2: Valid hashing and verification
  const pass = 'superSecret123!';
  const hash = await hashRoomPasscode(pass);
  if (!hash) throw new Error('Hash was null');
  
  const isValid = await verifyRoomPasscode(pass, hash);
  if (!isValid) throw new Error('Failed to verify correct passcode');

  const isInvalid = await verifyRoomPasscode('wrongPass', hash);
  if (isInvalid) throw new Error('Incorrectly verified wrong passcode');

  // Test 3: isBcryptHash
  if (!isBcryptHash(hash)) throw new Error('Failed to recognize valid bcrypt hash');
  if (isBcryptHash('plaintext_password')) throw new Error('Incorrectly recognized plaintext as hash');

  // Test 4: Too long passcode (byte length > 72)
  const longPass = 'a'.repeat(73);
  try {
    await hashRoomPasscode(longPass);
    throw new Error('Should have thrown on >72 bytes');
  } catch (e: any) {
    if (e.message !== 'ROOM_PASSCODE_TOO_LONG') {
      throw e;
    }
  }

  // Test 5: Unicode >72 bytes
  const unicodePass = '\u{20AC}'.repeat(25); // Euro sign is 3 bytes, 25 * 3 = 75 bytes
  try {
    await hashRoomPasscode(unicodePass);
    throw new Error('Should have thrown on unicode >72 bytes');
  } catch (e: any) {
    if (e.message !== 'ROOM_PASSCODE_TOO_LONG') {
      throw e;
    }
  }

  // Test 6: Owner encryption and decryption
  const secretPasscode = 'MySecretPasscode@2026';
  const encrypted = encryptPasscodeForOwner(secretPasscode);
  if (!encrypted || encrypted === secretPasscode) throw new Error('Encryption failed');
  const decrypted = decryptPasscodeForOwner(encrypted);
  if (decrypted !== secretPasscode) throw new Error(`Decryption failed: expected ${secretPasscode}, got ${decrypted}`);

  // Test 7: Encryption empty/null cases
  if (encryptPasscodeForOwner('') !== null) throw new Error('Expected null for empty passcode');
  if (encryptPasscodeForOwner(null) !== null) throw new Error('Expected null for null passcode');
  if (decryptPasscodeForOwner('') !== null) throw new Error('Expected null for empty encrypted data');
  if (decryptPasscodeForOwner(null) !== null) throw new Error('Expected null for null encrypted data');
  if (decryptPasscodeForOwner('invalid:token') !== null) throw new Error('Expected null for malformed encrypted data');

  console.log('All tests passed!');
}

runTests().catch(console.error);

import { createClient } from "@supabase/supabase-js";
import config from "../config.ts";

const supabaseUrl = config.SUPABASE_URL || "";
const supabaseSecretKey = config.SUPABASE_SECRET_KEY || "";

if (!supabaseUrl || !supabaseSecretKey) {
  console.warn("Supabase URL or Secret Key is missing from configuration.");
}

// Public client for validating user access tokens
// This intentionally DOES NOT use the secret key, so it cannot bypass RLS
// We just use it to verify the JWT provided by the frontend.
// Wait, we don't have an anon key in the backend. 
// For validating tokens, we just use the secret key to instantiate an admin client,
// but for standard getUser(jwt), it doesn't matter since it sends the JWT directly.
// Actually, to validate a JWT securely, we use supabase.auth.getUser(jwt).

import { SecurityLogger } from "./SecurityLogger.ts";

export const supabaseAdmin = supabaseUrl && supabaseSecretKey 
  ? createClient(supabaseUrl, supabaseSecretKey) 
  : null as any;

export async function validateUserToken(uid: string, token: string, requireConfirmation: boolean = true) {
  if (!supabaseUrl || !supabaseSecretKey || !token) {
    return undefined;
  }
  try {
    // getUser(token) validates the JWT against the Supabase Auth server directly.
    const { data: { user }, error } = await supabaseAdmin.auth.getUser(token);
    if (error || !user) {
      SecurityLogger.warn("auth.token_validation_failed", { uid, error: error?.message }, "supabase");
      return undefined;
    }
    if (uid !== user.id) {
      SecurityLogger.warn("auth.token_uid_mismatch", { expectedUid: uid, actualUid: user.id }, "supabase");
      // Valid but for wrong user
      return undefined;
    }

    if (requireConfirmation && user.email_confirmed_at == null) {
      return "EMAIL_NOT_VERIFIED";
    }

    // Return a mocked decoded token matching the previous Auth interface
    return { uid: user.id, email: user.email, email_verified: user.email_confirmed_at != null };
  } catch (e) {
    console.log(e);
    return undefined;
  }
}

import { postgres } from "./postgres.ts";

// Administrative operations (bypass RLS)
export async function getUserByEmail(email: string) {
  if (!supabaseUrl || !supabaseSecretKey) return null;
  try {
    // Supabase JS doesn't have a direct getUserByEmail, but we can query auth.users directly since we have pg connected as superuser.
    const result = await postgres?.query("SELECT id, email FROM auth.users WHERE email = $1 LIMIT 1", [email]);
    if (result && result.rows.length > 0) {
      return { uid: result.rows[0].id, email: result.rows[0].email };
    }
    return null;
  } catch (e: any) {
    console.log(email, e.message);
  }
  return null;
}

export async function getUser(uid: string) {
  if (!supabaseUrl || !supabaseSecretKey) return null;
  try {
    const { data: { user }, error } = await supabaseAdmin.auth.admin.getUserById(uid);
    if (error) throw error;
    return user;
  } catch(e) {
    return null;
  }
}

export async function getUserEmail(uid: string) {
  if (!supabaseUrl || !supabaseSecretKey) return null;
  const user = await getUser(uid);
  return user?.email;
}

export async function deleteUser(uid: string) {
  if (!supabaseUrl || !supabaseSecretKey) return null;
  return supabaseAdmin.auth.admin.deleteUser(uid);
}

