                let target = await window.cowatch.webtorrent?.get(src);
                if (!target) {
                  target = window.cowatch.webtorrent?.add(src, {
                    announce: [
                      "wss://tracker.btorrent.xyz",
                      "wss://tracker.openwebtorrent.com",
