    } catch (criticalErr) {
      console.error("Critical error in join:", criticalErr);
      if (this.startingTimer) {
        window.clearTimeout(this.startingTimer);
        this.startingTimer = null;
      }
      this.setState({ state: "connected", overlayMsg: "Failed to connect to room." });
    }
  };

