import { default as toWebVTT } from "srt-webvtt";
import { Player } from "./Player";

export class HTML implements Player {
  elId: string;
  constructor(elId: string) {
    this.elId = elId;
  }

  getVideoEl = (): HTMLMediaElement => {
    return document.getElementById(this.elId) as HTMLMediaElement;
  };

  getCurrentTime = () => {
    return this.getVideoEl()?.currentTime ?? 0;
  };

  getDuration = () => {
    return this.getVideoEl()?.duration ?? 0;
  };

  isMuted = () => {
    return this.getVideoEl()?.muted ?? false;
  };

  isSubtitled = () => {
    return this.getSubtitleMode() === "showing";
  };

  getPlaybackRate = (): number => {
    return this.getVideoEl()?.playbackRate ?? 1;
  };

  setPlaybackRate = (rate: number) => {
    if (this.getVideoEl()) {
      this.getVideoEl().playbackRate = rate;
    }
  };

  setSrcAndTime = async (src: string, time: number) => {
    const leftVideo = this.getVideoEl();
    if (leftVideo) {
      leftVideo.currentTime = time;
      leftVideo.src = src;
    }
  };

  playVideo = async () => {
    if (this.getVideoEl()) {
      await this.getVideoEl().play();
    }
  };

  pauseVideo = () => {
    if (this.getVideoEl()) {
      this.getVideoEl().pause();
    }
  };

  seekVideo = (time: number) => {
    if (this.getVideoEl()) {
      this.getVideoEl().currentTime = time;
    }
  };

  shouldPlay = () => {
    const leftVideo = this.getVideoEl();
    return Boolean(leftVideo?.paused || leftVideo?.ended);
  };

  setMute = (muted: boolean) => {
    const leftVideo = this.getVideoEl();
    if (leftVideo) {
      leftVideo.muted = muted;
    }
    const audio = document.getElementById("iPhoneAudio") as HTMLAudioElement;
    if (audio) {
      audio.muted = muted;
    }
  };

  setVolume = (volume: number) => {
    if (this.getVideoEl()) {
      this.getVideoEl().volume = volume;
    }
  };

  getVolume = (): number => {
    return this.getVideoEl()?.volume ?? 1;
  };

  setSubtitleMode = (mode?: TextTrackMode) => {
    if (this.getVideoEl()) {
      for (
        let i = 0;
        i < Math.min(this.getVideoEl().textTracks.length, 1);
        i++
      ) {
        this.getVideoEl().textTracks[i].mode =
          mode ??
          (this.getVideoEl().textTracks[i].mode === "hidden"
            ? "showing"
            : "hidden");
      }
    }
  };

  getSubtitleMode = () => {
    return this.getVideoEl()?.textTracks[0]?.mode ?? "hidden";
  };

  isReady = () => {
    return Boolean(this.getVideoEl());
  };

  clearState = () => {
    const leftVideo = this.getVideoEl();

    // Clear src and srcObject
    leftVideo.src = "";
    leftVideo.srcObject = null;

    // Clear subtitles
    this.setSubtitleMode("hidden");
    leftVideo.innerHTML = "";
  };

  loadSubtitles = async (src: string) => {
    const leftVideo = this.getVideoEl();
    if (!leftVideo) {
      return;
    }
    // Clear subtitles and put new ones in
    leftVideo.innerHTML = "";
    if (Boolean(src)) {
      let subtitleSrc = src;
      if (subtitleSrc) {
        const response = await fetch(subtitleSrc);
        const buffer = await response.arrayBuffer();
        const url = await toWebVTT(new Blob([buffer]));
        const track = document.createElement("track");
        track.kind = "captions";
        track.label = "English";
        track.srclang = "en";
        track.src = url;
        leftVideo.appendChild(track);
        leftVideo.textTracks[0].mode = "showing";
      }
    }
  };

  syncSubtitles = (sharerTime: number) => {
    // When sharing, our timestamp doesn't match the subtitles so adjust them
    // For each cue, subtract the videoTS of the sharer, then add our own
    const leftVideo = this.getVideoEl();
    const track = leftVideo?.textTracks[0];
    let offset = leftVideo.currentTime - sharerTime;
    if (track && track.cues && offset) {
      for (let i = 0; i < track.cues.length; i++) {
        let cue = track?.cues?.[i] as TextTrackCue & {
          origStart: number;
          origEnd: number;
        };
        if (!cue) {
          continue;
        }
        // console.log(cue.text, offset, cue.origStart, cue.origEnd);
        if (!cue.origStart) {
          cue.origStart = cue.startTime;
          cue.origEnd = cue.endTime;
        }
        cue.startTime = cue.origStart + offset;
        cue.endTime = cue.origEnd + offset;
      }
    }
  };

  getTimeRanges = (): { start: number; end: number }[] => {
    const leftVideo = this.getVideoEl();
    const buffers = [];
    const rangeCount = leftVideo?.buffered.length;
    for (let i = 0; i < rangeCount; i++) {
      const start = leftVideo?.buffered.start(i);
      const end = leftVideo?.buffered.end(i);
      buffers.push({ start, end });
    }
    return buffers;
  };

  setLoop = (loop: boolean): void => {
    const leftVideo = this.getVideoEl();
    leftVideo.loop = loop;
  };
}

import React from "react";
import {
  IconBrowser,
  IconCheck,
  IconChevronDown,
  IconChevronUp,
  IconCopy,
  IconDots,
  IconFile,
  IconLink,
  IconList,
  IconLock,
  IconLockOpen,
  IconMaximize,
  IconMinimize,
  IconPlus,
  IconScreenShare,
  IconX,
} from "@tabler/icons-react";
import { Menu } from "@mantine/core";
import ChatVideoCard from "../ChatVideoCard/ChatVideoCard";
import styles from "./MediaDock.module.css";
import { findPlaylistVideoByUrl } from "../../../server/utils/playlist";

interface MediaDockProps {
  isVBrowserEnabled?: boolean;
  haveLock: boolean;
  onOpenScreenShare: () => void;
  onOpenVBrowser: () => void;
  onOpenFileShare: () => void;
  onOpenQuickAdd: () => void;
  playlist: PlaylistVideo[];
  onPlayPlaylistItem: (index: number) => void;
  onDeletePlaylistItem: (index: number) => void;
  onMovePlaylistItem: (from: number, to: number) => void;
  roomMedia?: string;
  onStopMedia?: () => void;
  isScreenSharing?: boolean;
  onStopScreenShare?: () => void;
  isPlayingVBrowser?: boolean;
  onStopVBrowser?: () => void;
  isLocked?: boolean;
  onToggleLock?: () => void;
  isFullScreen?: boolean;
  onToggleFullScreen?: () => void;
  paused?: boolean;
}

export const MediaDock: React.FC<MediaDockProps> = ({
  isVBrowserEnabled,
  haveLock,
  onOpenScreenShare,
  onOpenVBrowser,
  onOpenFileShare,
  onOpenQuickAdd,
  playlist,
  onPlayPlaylistItem,
  onDeletePlaylistItem,
  onMovePlaylistItem,
  roomMedia,
  onStopMedia,
  isScreenSharing,
  onStopScreenShare,
  isPlayingVBrowser,
  onStopVBrowser,
  isLocked,
  onToggleLock,
  isFullScreen,
  onToggleFullScreen,
  paused = false,
}) => {
  const [copied, setCopied] = React.useState(false);
  const [openMenus, setOpenMenus] = React.useState(0);
  const isPlaying = Boolean(roomMedia) && !paused;

  // Collapse while playing if media is loaded
  const [isCollapsed, setIsCollapsed] = React.useState<boolean>(
    Boolean(roomMedia) && !paused
  );

  const autoCollapseTimer = React.useRef<NodeJS.Timeout | null>(null);

  // When roomMedia or playback state changes
  React.useEffect(() => {
    if (!roomMedia) {
      setIsCollapsed(false);
      return;
    }
    if (isPlaying) {
      setIsCollapsed(true);
    }
  }, [isPlaying, Boolean(roomMedia)]);

  const clearTimer = React.useCallback(() => {
    if (autoCollapseTimer.current) {
      clearTimeout(autoCollapseTimer.current);
      autoCollapseTimer.current = null;
    }
  }, []);

  const scheduleAutoCollapse = React.useCallback(() => {
    clearTimer();
    if (isPlaying && openMenus === 0 && !isCollapsed) {
      autoCollapseTimer.current = setTimeout(() => {
        setIsCollapsed(true);
      }, 3500);
    }
  }, [isPlaying, openMenus, isCollapsed, clearTimer]);

  React.useEffect(() => {
    if (!isCollapsed && isPlaying && openMenus === 0) {
      scheduleAutoCollapse();
    } else {
      clearTimer();
    }
    return clearTimer;
  }, [isCollapsed, isPlaying, openMenus, scheduleAutoCollapse, clearTimer]);

  const handleMenuOpen = () => {
    setOpenMenus((c) => c + 1);
    clearTimer();
  };

  const handleMenuClose = () => {
    setOpenMenus((c) => Math.max(0, c - 1));
    scheduleAutoCollapse();
  };

  const handleCopyLink = () => {
    void navigator.clipboard.writeText(window.location.href);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (Boolean(roomMedia) && isCollapsed) {
    return (
      <button
        type="button"
        className={styles.collapsedPill}
        onClick={() => setIsCollapsed(false)}
        title="Show media dock"
      >
        <IconChevronUp size={14} stroke={2.5} />
        <span>Media</span>
      </button>
    );
  }

  return (
    <div
      className={styles.dockContainer}
      onMouseEnter={clearTimer}
      onMouseLeave={scheduleAutoCollapse}
    >
      {/* Prioritized single stop button (VBrowser > ScreenShare > Standard Media) */}
      {isPlayingVBrowser && onStopVBrowser ? (
        <button
          type="button"
          className={styles.stopBtn}
          onClick={onStopVBrowser}
          disabled={!haveLock}
          title="Stop Virtual Browser"
        >
          <IconX size={15} />
          <span>Stop VBrowser</span>
        </button>
      ) : isScreenSharing && onStopScreenShare ? (
        <button
          type="button"
          className={styles.stopBtn}
          onClick={onStopScreenShare}
          title="Stop Screenshare"
        >
          <IconX size={15} />
          <span>Stop Share</span>
        </button>
      ) : Boolean(roomMedia) && onStopMedia ? (
        <button
          type="button"
          className={styles.stopBtn}
          onClick={onStopMedia}
          disabled={!haveLock}
          title={
            haveLock
              ? "Stop playback and remove media"
              : "Controls locked by host"
          }
        >
          <IconX size={15} />
          <span>Stop playback</span>
        </button>
      ) : null}

      {/* Add Media Dropdown Menu */}
      <Menu
        shadow="xl"
        width={260}
        position="top-start"
        offset={10}
        onOpen={handleMenuOpen}
        onClose={handleMenuClose}
      >
        <Menu.Target>
          <button
            type="button"
            className={styles.addMediaBtn}
            disabled={!haveLock}
            title={haveLock ? "Add media to room" : "Controls locked by host"}
          >
            <IconPlus size={16} stroke={2.5} />
            <span>Add media</span>
            <IconChevronDown size={14} stroke={1.5} />
          </button>
        </Menu.Target>
        <Menu.Dropdown>
          <Menu.Label>Add to watch party</Menu.Label>

          <Menu.Item
            leftSection={<IconScreenShare size={18} color="#60A5FA" />}
            onClick={onOpenScreenShare}
          >
            <div className={styles.menuItemWithDesc}>
              <span className={styles.menuItemTitle}>Share screen</span>
              <span className={styles.menuItemDesc}>Stream your screen or tab</span>
            </div>
          </Menu.Item>

          {isVBrowserEnabled && (
            <Menu.Item
              leftSection={<IconBrowser size={18} color="#34D399" />}
              onClick={onOpenVBrowser}
            >
              <div className={styles.menuItemWithDesc}>
                <span className={styles.menuItemTitle}>Browser</span>
                <span className={styles.menuItemDesc}>Browse the web together</span>
              </div>
            </Menu.Item>
          )}

          <Menu.Item
            leftSection={<IconFile size={18} color="#A78BFA" />}
            onClick={onOpenFileShare}
          >
            <div className={styles.menuItemWithDesc}>
              <span className={styles.menuItemTitle}>Upload file</span>
              <span className={styles.menuItemDesc}>Play a local video</span>
            </div>
          </Menu.Item>

          <Menu.Item
            leftSection={<IconLink size={18} color="#F472B6" />}
            onClick={onOpenQuickAdd}
          >
            <div className={styles.menuItemWithDesc}>
              <span className={styles.menuItemTitle}>Video URL / Search</span>
              <span className={styles.menuItemDesc}>Paste link or search media</span>
            </div>
          </Menu.Item>
        </Menu.Dropdown>
      </Menu>

      {/* Playlist Button & Dropdown */}
      <Menu
        shadow="xl"
        width={340}
        position="top"
        offset={10}
        onOpen={handleMenuOpen}
        onClose={handleMenuClose}
      >
        <Menu.Target>
          <button type="button" className={styles.dockBtn} title="View playlist">
            <IconList size={16} />
            <span>Playlist</span>
            <span className={styles.badge}>{playlist.length}</span>
          </button>
        </Menu.Target>
        <Menu.Dropdown
          style={{
            maxHeight: 380,
            overflowY: playlist.length > 0 ? "auto" : "visible",
          }}
        >
          <Menu.Label>Room Playlist ({playlist.length})</Menu.Label>
          {playlist.length === 0 && (
            <Menu.Item disabled>There are no items in the playlist.</Menu.Item>
          )}
          {playlist.map((item: PlaylistVideo, index: number) => {
            const videoItem = { ...item };
            if (Boolean(videoItem.img)) {
              videoItem.type = "youtube";
            }
            const isActive = roomMedia && findPlaylistVideoByUrl([videoItem], roomMedia) !== undefined;
            return (
              <Menu.Item 
                key={index} 
                closeMenuOnClick={false}
                className={isActive ? styles.activePlaylistItem : undefined}
              >
                <ChatVideoCard
                  video={videoItem}
                  index={index}
                  controls
                  onPlay={onPlayPlaylistItem}
                  onPlayNext={(idx) => onMovePlaylistItem(idx, 0)}
                  onRemove={onDeletePlaylistItem}
                  disabled={!haveLock}
                />
              </Menu.Item>
            );
          })}
        </Menu.Dropdown>
      </Menu>

      {/* More Options Menu */}
      <Menu
        shadow="xl"
        width={200}
        position="top-end"
        offset={10}
        onOpen={handleMenuOpen}
        onClose={handleMenuClose}
      >
        <Menu.Target>
          <button type="button" className={styles.iconBtn} title="More actions">
            <IconDots size={16} />
          </button>
        </Menu.Target>
        <Menu.Dropdown>
          {onToggleFullScreen && (
            <Menu.Item
              leftSection={
                isFullScreen ? (
                  <IconMinimize size={16} />
                ) : (
                  <IconMaximize size={16} />
                )
              }
              onClick={onToggleFullScreen}
            >
              {isFullScreen ? "Exit Fullscreen" : "Fullscreen"}
            </Menu.Item>
          )}
          {onToggleLock && (
            <Menu.Item
              disabled={!haveLock}
              leftSection={
                isLocked ? (
                  <IconLock size={16} color="var(--color-warning)" />
                ) : (
                  <IconLockOpen size={16} />
                )
              }
              onClick={onToggleLock}
            >
              {isLocked ? "Unlock controls" : "Lock controls"}
            </Menu.Item>
          )}
          <Menu.Item
            leftSection={
              copied ? (
                <IconCheck size={16} color="var(--color-live)" />
              ) : (
                <IconCopy size={16} />
              )
            }
            onClick={handleCopyLink}
          >
            {copied ? "Link Copied!" : "Copy room link"}
          </Menu.Item>
        </Menu.Dropdown>
      </Menu>

      {/* Collapse button when media is loaded */}
      {Boolean(roomMedia) && (
        <button
          type="button"
          className={styles.collapseBtn}
          onClick={() => setIsCollapsed(true)}
          title="Collapse media dock"
        >
          <IconChevronDown size={16} stroke={2} />
        </button>
      )}
    </div>
  );
};

import { MediaPlayerClass } from "dashjs";
import { Player } from "./Player";

export class YouTube implements Player {
  coWatchYTPlayer: YT.Player | null;
  constructor(coWatchYTPlayer: YT.Player | null) {
    this.coWatchYTPlayer = coWatchYTPlayer;
  }
  clearDashState = () => {};
  setDashState = (player: MediaPlayerClass) => {};

  getCurrentTime = () => {
    return this.coWatchYTPlayer?.getCurrentTime() ?? 0;
  };

  getDuration = () => {
    return this.coWatchYTPlayer?.getDuration() ?? 0;
  };

  isMuted = () => {
    return this.coWatchYTPlayer?.isMuted() ?? false;
  };

  isSubtitled = (): boolean => {
    // This actually isn't accurate after subtitles have been toggled off because track doesn't update
    // try {
    //   const current = this.coWatchYTPlayer?.getOption('captions', 'track');
    //   return Boolean(current && current.languageCode);
    // } catch (e) {
    //   console.warn(e);
    //   return false;
    // }
    return false;
  };

  getPlaybackRate = (): number => {
    return this.coWatchYTPlayer?.getPlaybackRate() ?? 1;
  };

  setPlaybackRate = (rate: number) => {
    this.coWatchYTPlayer?.setPlaybackRate(rate);
  };

  setSrcAndTime = async (src: string, time: number) => {
    let url = new window.URL(src);
    // Standard link https://www.youtube.com/watch?v=ID
    let videoId = new URLSearchParams(url.search).get("v");
    // Link shortener https://youtu.be/ID
    let altVideoId = src.split("/").slice(-1)[0].split("?")[0];
    this.coWatchYTPlayer?.cueVideoById(videoId || altVideoId, time);
    // this.coWatchYTPlayer?.cuePlaylist({listType: 'playlist', list: 'OLAK5uy_mtoaOGQksRdPbwlNtQ9IiK67wir5QqyIc'});
  };

  playVideo = async () => {
    this.coWatchYTPlayer?.playVideo();
  };

  pauseVideo = () => {
    this.coWatchYTPlayer?.pauseVideo();
  };

  seekVideo = (time: number) => {
    this.coWatchYTPlayer?.seekTo(time, true);
  };

  shouldPlay = () => {
    return (
      this.coWatchYTPlayer?.getPlayerState() ===
        window.YT?.PlayerState.PAUSED ||
      this.getCurrentTime() === this.getDuration()
    );
  };

  setMute = (muted: boolean) => {
    if (muted) {
      this.coWatchYTPlayer?.mute();
    } else {
      this.coWatchYTPlayer?.unMute();
    }
  };

  setVolume = (volume: number) => {
    this.coWatchYTPlayer?.setVolume(volume * 100);
  };

  getVolume = (): number => {
    const volume = this.coWatchYTPlayer?.getVolume();
    return (volume ?? 0) / 100;
  };

  setSubtitleMode = (mode?: TextTrackMode, lang?: string) => {
    // Show the available options
    // console.log(this.coWatchYTPlayer?.getOptions('captions'));
    if (mode === "showing") {
      console.log(lang);
      //@ts-expect-error
      this.coWatchYTPlayer?.setOption("captions", "reload", true);
      //@ts-expect-error
      this.coWatchYTPlayer?.setOption("captions", "track", {
        languageCode: lang ?? "en",
      });
    }
    if (mode === "hidden") {
      // BUG this doesn't actually set the value of track
      // so we can't determine if subtitles are on or off
      // need to provide separate menu options
      //@ts-expect-error
      this.coWatchYTPlayer?.setOption("captions", "track", {});
    }
  };

  getSubtitleMode = () => {
    return "hidden" as TextTrackMode;
  };

  isReady = () => {
    return Boolean(this.coWatchYTPlayer);
  };

  stopVideo = () => {
    this.coWatchYTPlayer?.stopVideo();
  };

  clearState = () => {
    return;
  };

  loadSubtitles = async (src: string) => {
    return;
  };

  syncSubtitles = (sharerTime: number) => {
    return;
  };

  getTimeRanges = (): { start: number; end: number }[] => {
    return [
      {
        start: 0,
        end:
          (this.coWatchYTPlayer?.getVideoLoadedFraction() ?? 0) *
          this.getDuration(),
      },
    ];
  };

  setLoop = (loop: boolean): void => {
    this.coWatchYTPlayer?.setLoop(loop);
  };

  getVideoEl = (): HTMLMediaElement => {
    return document.getElementById("leftYt") as HTMLMediaElement;
  };
}

import React, { useState } from "react";
import { Link } from "react-router-dom";
import {
  TextInput,
  Button,
  Container,
