} from "@mantine/core";
import { IconShieldCheck } from "@tabler/icons-react";
import { supabase } from "../../utils/supabaseClient";
import styles from "./AuthShell.module.css";

export const ResetPassword = () => {
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const history = useHistory();

  useEffect(() => {
    // Supabase will automatically parse the hash containing the recovery token
    // and establish a session. We can listen for the hash change or just rely on
    // supabase.auth.onAuthStateChange in App, but here we just need to ensure
    // we have a session to update the password.
    
    // Check if we have an active session (user followed the email link)
    const checkSession = async () => {
      const { data } = await supabase.auth.getSession();
      if (!data.session) {
        setError("Invalid or expired password reset link. Please request a new one.");
      }
    };
    void checkSession();
  }, []);

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    
    if (password !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    try {
      const { error } = await supabase.auth.updateUser({
        password: password,
      });
      if (error) throw error;
      
      // Successfully updated password, show success state
      setSuccess(true);
    } catch (err: any) {
      console.error("Password update error:", err);
      setError(err.message);
    }
  };

  return (
    <div style={{ width: "100%" }}>
      <Center mb={20}>
        <div style={{ 
          background: "var(--surface-hover)", 
          padding: "16px", 
          borderRadius: "50%",
          display: "flex"
        }}>
          <IconShieldCheck size={32} color="var(--color-teal)" />
        </div>
      </Center>
      <Title order={2} ta="center" fw={800}>Choose a new password</Title>
      <Text c="dimmed" size="sm" ta="center" mt={5}>
        Enter your new password below.
      </Text>

      <Paper 
        withBorder
        p={30} 
        mt={30} 
        radius="lg" 
        className={styles.authCard}
      >
        {error && (
          <Alert color="red" mb="md" title="Error">
            {error}
          </Alert>
        )}
        
        {success ? (
          <div>
            <Alert color="green" title="Password updated" mb="md">
              Your password has been changed successfully.
            </Alert>
            <Button onClick={() => history.push("/login")} fullWidth>
              Sign in
            </Button>
          </div>
        ) : (
          <form onSubmit={handleUpdate} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
            <PasswordInput
              label="New Password"
              placeholder="New password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <PasswordInput
              label="Confirm New Password"
              placeholder="Confirm new password"
              required
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
            />
            <Button fullWidth type="submit" mt="md" disabled={!!error && error.includes("Invalid")}>
              Update password
            </Button>
          </form>
        )}
      </Paper>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from "react";
import { useHistory, useLocation, Link } from "react-router-dom";
import {
  TextInput,
  PasswordInput,
  Button,
  Paper,
  Title,
  Text,
  Alert,
  Divider,
} from "@mantine/core";
import { IconBrandGoogleFilled, IconCheck } from "@tabler/icons-react";
import { supabase } from "../../utils/supabaseClient";
import config from "../../config";
import { DEFAULT_AVATARS } from "../../utils/defaultAvatars";
import styles from "./AuthShell.module.css";

export const Signup = () => {
  const [displayName, setDisplayName] = useState("");
  const [selectedAvatar, setSelectedAvatar] = useState<string>(DEFAULT_AVATARS[0].url);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);
  const history = useHistory();
  const location = useLocation();

  const handleGoogleSignIn = async () => {
    setError(null);
    setGoogleLoading(true);
    try {
      const params = new URLSearchParams(location.search);
      const redirect = params.get("redirect") || "/";
      const redirectTarget = redirect.startsWith("/") ? redirect : `/${redirect}`;
      const redirectTo = `${window.location.origin}${redirectTarget}`;

      const { error } = await supabase.auth.signInWithOAuth({
        provider: "google",
        options: {
          redirectTo,
        },
      });
      if (error) throw error;
    } catch (err: any) {
      console.error("Google Auth error:", err);
      setError(err.message);
      setGoogleLoading(false);
    }
  };

  const enabledOptions = (config.VITE_AUTH_SIGNIN_METHODS || "google,email").split(",");

  // Countdown timer for resend cooldown
  useEffect(() => {
    if (resendCooldown <= 0) return;
    const timer = setTimeout(() => setResendCooldown((c) => c - 1), 1000);
    return () => clearTimeout(timer);
  }, [resendCooldown]);

  const handleSignup = async (e: React.FormEvent) => {
    e.preventDefault();
    if (submitting) return;

    // Clear previous states
    setError(null);
    setSuccess(null);

    if (password !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }

    setSubmitting(true);
    try {
      const derivedUsername = email.split("@")[0] || "user";
      const finalDisplayName = displayName.trim() || derivedUsername;
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: {
            display_name: finalDisplayName,
            username: derivedUsername,
            avatar_url: selectedAvatar,
          },
        },
      });
      if (error) throw error;

      // If a session is returned, email confirmation is disabled -- auto-login
      if (data.session) {
        history.push("/");
        return;
      }

      // Otherwise, email confirmation is required
      setError(null);
      setSuccess(
        "We've sent a confirmation link to your email address. Please confirm your email to sign in."
      );
      setResendCooldown(60);
    } catch (err: any) {
      console.error("Signup error:", err);
      setSuccess(null);
      setError(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  const handleResend = useCallback(async () => {
    if (resendCooldown > 0 || !email) return;

    setError(null);
    try {
      const { error } = await supabase.auth.resend({
        type: "signup",
        email,
      });
      if (error) throw error;
      setSuccess("Confirmation email resent. Please check your inbox.");
      setResendCooldown(60);
    } catch (err: any) {
      console.error("Resend error:", err);
      setError(err.message);
    }
  }, [email, resendCooldown]);

  return (
    <div style={{ width: "100%" }}>
      <Title 
        order={2} 
        ta="left" 
        fw={900} 
        style={{
          background: "linear-gradient(45deg, var(--color-violet), var(--color-pink))",
          WebkitBackgroundClip: "text",
          WebkitTextFillColor: "transparent",
        }}
      >
        Create your account
      </Title>
      <Text c="dimmed" size="sm" ta="left" mt={5}>
        Join CoWatch and watch together with friends.
      </Text>

      <Paper 
        withBorder
        p={30} 
        mt={30} 
        radius="lg" 
        className={styles.authCard}
      >
        {error && (
          <Alert color="red" mb="md" title="Error">
            {error}
          </Alert>
        )}

        {success ? (
          <div>
            <Alert color="green" title="Check your email" mb="md">
              {success}
            </Alert>
            <Button
              fullWidth
              variant="default"
              onClick={handleResend}
              disabled={resendCooldown > 0}
            >
              {resendCooldown > 0
                ? `Resend available in ${resendCooldown}s`
                : "Resend confirmation email"}
            </Button>
          </div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {enabledOptions.includes("google") && (
              <Button
                leftSection={<IconBrandGoogleFilled />}
                onClick={handleGoogleSignIn}
                variant="default"
                fullWidth
                loading={googleLoading}
              >
                Continue with Google
              </Button>
            )}

            {enabledOptions.includes("email") && enabledOptions.includes("google") && (
              <Divider label="Or sign up with email" labelPosition="center" my="xs" />
            )}

            {enabledOptions.includes("email") && (
              <form onSubmit={handleSignup} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
                <TextInput
                  label="Display Name"
                  placeholder="Your display name"
                  required
                  value={displayName}
                  onChange={(e) => setDisplayName(e.target.value)}
                />

                <div className={styles.avatarSection}>
                  <div className={styles.avatarSectionHeader}>
                    <span className={styles.avatarSectionLabel}>Choose your avatar</span>
                    <span className={styles.avatarSubtitle}>5 styles available</span>
                  </div>
                  <div className={styles.avatarGrid}>
                    {DEFAULT_AVATARS.map((avatar) => {
                      const isSelected = selectedAvatar === avatar.url;
                      return (
                        <button
                          key={avatar.id}
                          type="button"
                          className={`${styles.avatarOption} ${isSelected ? styles.avatarOptionActive : ""}`}
                          onClick={() => setSelectedAvatar(avatar.url)}
                          title={avatar.name}
                          aria-label={`Select ${avatar.name} avatar`}
                        >
                          <img src={avatar.url} alt={avatar.name} className={styles.avatarImg} />
                          {isSelected && (
                            <div className={styles.avatarCheckBadge}>
                              <IconCheck size={11} stroke={3} />
                            </div>
                          )}
                        </button>
                      );
                    })}
                  </div>
                </div>

                <TextInput
                  label="Email"
                  placeholder="your@email.com"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
                <PasswordInput
                  label="Password"
                  placeholder="Your password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <PasswordInput
                  label="Confirm Password"
                  placeholder="Confirm password"
                  required
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                />
                <Button fullWidth type="submit" mt="md" loading={submitting}>
                  Create account
                </Button>
              </form>
            )}
          </div>
        )}
      </Paper>
      <Text size="sm" ta="center" mt="md" c="dimmed">
        Already have an account?{" "}
        <Link to="/login" style={{ color: "var(--color-violet)", textDecoration: "underline", fontWeight: 600 }}>
          Sign in
        </Link>
      </Text>
    </div>
  );
};

