export const VerifyEmail = () => {
  const { user } = useContext(MetadataContext);
  const history = useHistory();
  const location = useLocation();

  const searchParams = new URLSearchParams(location.search);
  const next = searchParams.get("next");

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [cooldown, setCooldown] = useState(0);

  useEffect(() => {
    if (user === null) {
      history.replace("/login");
    } else if (user && user.email_confirmed_at != null) {
      history.replace(getSafeRedirectUrl(next));
    }
  }, [user, history, next]);

  useEffect(() => {
    let timer: any;
    if (cooldown > 0) {
      timer = setTimeout(() => setCooldown(cooldown - 1), 1000);
    }
    return () => clearTimeout(timer);
  }, [cooldown]);

  const handleResend = async () => {
    if (!user?.email || cooldown > 0) return;

    setLoading(true);
    setError(null);
    setSuccess(null);

    const { error } = await supabase.auth.resend({
      type: 'signup',
      email: user.email,
      options: {
        emailRedirectTo: `${window.location.origin}${getSafeRedirectUrl(next)}`
      }
    });

    setLoading(false);

    if (error) {
      setError(error.message);
    } else {
      setSuccess("Verification email has been resent! Please check your inbox and spam folder.");
      setCooldown(60);
    }
  };

  const handleRefresh = async () => {
    setLoading(true);
    const { error } = await supabase.auth.refreshSession();
    setLoading(false);
    if (error) {
      setError(error.message);
    }
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
  };

  const [timedOut, setTimedOut] = useState(false);
  useEffect(() => {
    if (user === undefined) {
      const timer = setTimeout(() => setTimedOut(true), 1200);
      return () => clearTimeout(timer);
    }
  }, [user]);

  if (user === undefined && !timedOut) {
    return (
      <Center style={{ minHeight: "100vh", width: "100%" }}>
        <Loader color="violet" size="lg" />
      </Center>
    );
  }

  // Double check so we don't flash UI before redirect
  if (!user || user.email_confirmed_at != null) {
    return null;
  }

  return (
    <Container size="sm" mt={80}>
      <Paper radius="md" p="xl" withBorder className={styles.authCard}>
        <Stack align="center" gap="md">
          <IconMail size={50} color="var(--color-violet)" />
          
          <Title order={2} style={{ color: "var(--text-primary)" }}>
            Verify your email
          </Title>
          
          <Text c="dimmed" ta="center">
            You need to confirm your email before you can log in. 
            We've sent a verification link to <strong>{user.email}</strong>. 
            Please click the link to confirm your account and access CoWatch.
          </Text>

          {error && (
            <Alert icon={<IconAlertCircle size={16} />} title="Error" color="red" w="100%">
              {error}
            </Alert>
          )}

          {success && (
            <Alert icon={<IconCheck size={16} />} title="Success" color="green" w="100%">
              {success}
            </Alert>
          )}

          <Stack gap="sm" w="100%" mt="md">
            <Button 
              fullWidth 
              variant="light" 
              color="violet"
              loading={loading}
              disabled={cooldown > 0}
              onClick={handleResend}
            >
              {cooldown > 0 ? `Resend email in ${cooldown}s` : "Resend verification email"}
            </Button>

            <Button 
              fullWidth 
              variant="outline" 
              color="gray"
              loading={loading}
              onClick={handleRefresh}
            >
              I've verified my email (Refresh)
            </Button>
          </Stack>

          <Group justify="center" mt="xl">
            <Button variant="subtle" color="gray" size="sm" onClick={handleSignOut}>
              Sign Out
            </Button>
          </Group>
        </Stack>
      </Paper>
    </Container>
  );
};

import React from "react";
import { ActionIcon } from "@mantine/core";
import { decodeEntities, formatTimestamp } from "../../utils/utils";

import classes from "./ChatVideoCard.module.css";
import {
  IconArrowUp,
  IconBrandYoutubeFilled,
  IconFile,
  IconMagnetFilled,
  IconPlayerPlayFilled,
  IconPlaylistAdd,
  IconTrash,
} from "@tabler/icons-react";

const ChatVideoCard: React.FC<{
  video: PlaylistVideo;
  index: number;
  controls?: boolean;
  onPlay?: (index: number) => void;
  onRemove?: (index: number) => void;
  onPlayNext?: (index: number) => void;
  onSetMedia?: (value: string) => void;
  onPlaylistAdd?: (value: string) => void;
  disabled?: boolean;
}> = (props) => {
  const {
    video,
    index,
    controls,
    onPlay,
    onPlayNext,
    onRemove,
    onSetMedia,
    disabled,
    onPlaylistAdd,
  } = props;

  const [imgError, setImgError] = React.useState(false);

  const handlePlayClick = React.useCallback(
    (e: any) => {
      if (onPlay) {
        onPlay(index);
      }
    },
    [onPlay, index],
  );

  const handlePlayNextClick = React.useCallback(
    (e: any) => {
      e.stopPropagation();
      e.nativeEvent.stopImmediatePropagation();
      if (onPlayNext) {
        onPlayNext(index);
      }
    },
    [onPlayNext, index],
  );

  const handleRemoveClick = React.useCallback(
    (e: any) => {
      e.stopPropagation();
      e.nativeEvent.stopImmediatePropagation();
      if (onRemove) {
        onRemove(index);
      }
    },
    [onRemove, index],
  );

  return (
    <div
      title={video.name}
      className={classes.Card}
      onClick={
        onSetMedia
          ? (e) => {
              onSetMedia(video.url);
            }
          : undefined
      }
    >
      <div className={classes.Wrapper}>
        <div className={classes.ThumbnailWrapper}>
          {!!video.duration && (
            <div className={classes.DurationLabel}>
              {formatTimestamp(video.duration)}
            </div>
          )}
          {Boolean(video.img) && !imgError && (
            <img
              className={classes.Thumbnail}
              src={video.img}
              alt={video.name}
              onError={() => setImgError(true)}
            />
          )}
        </div>
        <div style={{ flexShrink: 0 }}>
          {video.type === "youtube" && <IconBrandYoutubeFilled color="red" />}
          {video.type === "file" && <IconFile />}
          {video.type === "magnet" && <IconMagnetFilled />}
        </div>
        <div className={classes.Content}>
          <div className={classes.Title}>{decodeEntities(video.name)}</div>
          <div className={classes.ChannelName}>{video.channel}</div>
        </div>
        {onPlaylistAdd && (
          <div className={classes.Controls}>
            <ActionIcon
              title="Add to Playlist"
              onClick={(e) => {
                e.stopPropagation();
                e.nativeEvent.stopImmediatePropagation();
                onPlaylistAdd(video.url);
              }}
            >
              <IconPlaylistAdd />
            </ActionIcon>
          </div>
        )}
        {controls && (
          <div className={classes.Controls}>
            <ActionIcon
              color="green"
              title="Play now"
              onClick={handlePlayClick}
              disabled={disabled}
            >
              <IconPlayerPlayFilled size={16} />
            </ActionIcon>
            <ActionIcon
              color="black"
              title="Play next"
              onClick={handlePlayNextClick}
              disabled={disabled}
            >
              <IconArrowUp size={16} />
            </ActionIcon>
            <ActionIcon
              color="red"
              title="Remove"
              onClick={handleRemoveClick}
              disabled={disabled}
            >
              <IconTrash size={16} />
            </ActionIcon>
          </div>
        )}
      </div>
    </div>
  );
};

