import React, { useState, useEffect, useRef, useMemo, useCallback } from "react";
import {
  debounce,
  decodeEntities,
  formatTimestamp,
  getMediaPathResults,
  getYouTubeResults,
  isHttp,
  isMagnet,
  isYouTube,
} from "../../utils/utils";
import { examples } from "../../utils/examples";
import {
  IconBrandYoutubeFilled,
  IconCheck,
  IconCornerDownLeft,
  IconFile,
  IconLayersIntersect,
  IconLink,
  IconMagnetFilled,
  IconPlayerPlayFilled,
  IconPlaylistAdd,
  IconSearch,
  IconTrash,
  IconVideo,
  IconX,
} from "@tabler/icons-react";
import { Badge, Loader, TextInput, Tooltip } from "@mantine/core";
import classes from "./ComboBox.module.css";

export type ComboBoxProps = {
  roomSetMedia: (value: string) => void;
  playlistAdd: (value: string) => void;
  roomMedia: string;
  getMediaDisplayName: (input: string) => string;
  mediaPath: string | undefined;
  disabled?: boolean;
  onClose?: () => void;
};

type FilterCategory = "all" | "youtube" | "file" | "magnet";

export const ComboBox: React.FC<ComboBoxProps> = ({
  roomSetMedia,
  playlistAdd,
  roomMedia,
  getMediaDisplayName,
  mediaPath,
  disabled,
  onClose,
}) => {
  const [inputMedia, setInputMedia] = useState<string>("");
  const [activeFilter, setActiveFilter] = useState<FilterCategory>("all");
  const [items, setItems] = useState<SearchResult[]>(examples);
  const [loading, setLoading] = useState<boolean>(false);
  const [addedUrls, setAddedUrls] = useState<Record<string, boolean>>({});
  const [failedImages, setFailedImages] = useState<Record<string, boolean>>({});
  const inputRef = useRef<HTMLInputElement>(null);

  // Focus input automatically on mount
  useEffect(() => {
    const timer = setTimeout(() => {
      inputRef.current?.focus();
    }, 50);
    return () => clearTimeout(timer);
  }, []);

  const handlePlayNow = useCallback(
    (url: string) => {
      if (!url.trim()) return;
      roomSetMedia(url.trim());
      if (onClose) {
        onClose();
      }
    },
    [roomSetMedia, onClose],
  );

  const handleAddToPlaylist = useCallback(
    (url: string) => {
      if (!url.trim()) return;
      playlistAdd(url.trim());
      setAddedUrls((prev) => ({ ...prev, [url]: true }));
      setTimeout(() => {
        setAddedUrls((prev) => ({ ...prev, [url]: false }));
      }, 2500);
    },
    [playlistAdd],
  );

  const doSearch = useCallback(
    async (query: string) => {
      const trimmed = query.trim();
      if (!trimmed) {
        if (mediaPath) {
          try {
            setLoading(true);
            const pathItems = await getMediaPathResults(mediaPath, "");
            setItems(pathItems.length > 0 ? pathItems : examples);
          } catch {
            setItems(examples);
          } finally {
            setLoading(false);
          }
        } else {
          setItems(examples);
          setLoading(false);
        }
        return;
      }

      // If it's direct HTTP or Magnet, no need to query YouTube
      if (isHttp(trimmed) || isMagnet(trimmed)) {
        setLoading(false);
        return;
      }

      // Perform YouTube search
      setLoading(true);
      try {
        const youtubeResults = await getYouTubeResults(trimmed);
        setItems(youtubeResults);
      } catch (err) {
        console.error("Failed to fetch search results", err);
        setItems([]);
      } finally {
        setLoading(false);
      }
    },
    [mediaPath],
  );

  const debouncedSearch = useMemo(() => debounce(doSearch, 300), [doSearch]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setInputMedia(value);
    debouncedSearch(value);
  };

  const handleClear = () => {
    setInputMedia("");
    setItems(examples);
    inputRef.current?.focus();
  };

  const trimmedInput = inputMedia.trim();
  const isDirect = Boolean(
    trimmedInput && (isHttp(trimmedInput) || isMagnet(trimmedInput)),
  );

  const directType = useMemo(() => {
    if (!isDirect) return null;
    if (isYouTube(trimmedInput)) {
      return {
        label: "YouTube Video",
        color: "red",
        icon: <IconBrandYoutubeFilled size={14} color="#EF4444" />,
      };
    }
    if (isMagnet(trimmedInput)) {
      return {
        label: "WebTorrent Magnet",
        color: "violet",
        icon: <IconMagnetFilled size={14} color="#A78BFA" />,
      };
    }
    if (trimmedInput.toLowerCase().includes(".m3u8")) {
      return {
        label: "HLS Live Stream",
        color: "cyan",
        icon: <IconVideo size={14} color="#22D3EE" />,
      };
    }
    return {
      label: "Direct Video Stream",
      color: "blue",
      icon: <IconVideo size={14} color="#60A5FA" />,
    };
  }, [isDirect, trimmedInput]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      e.preventDefault();
      if (isDirect) {
        handlePlayNow(trimmedInput);
      } else if (filteredItems.length > 0) {
        handlePlayNow(filteredItems[0].url);
      } else if (trimmedInput) {
        handlePlayNow(trimmedInput);
      }
    } else if (e.key === "Escape") {
      if (onClose) {
        onClose();
      }
    }
  };

  const filteredItems = useMemo(() => {
    if (activeFilter === "all") return items;
    return items.filter((item) => item.type === activeFilter);
  }, [items, activeFilter]);

  return (
    <div className={classes.container}>
      {/* Category filter pills */}
      <div className={classes.filterRow}>
        <button
          type="button"
          className={`${classes.filterPill} ${activeFilter === "all" ? classes.filterPillActive : ""}`}
          onClick={() => setActiveFilter("all")}
        >
          <IconLayersIntersect size={14} />
          All Sources
        </button>
        <button
          type="button"
          className={`${classes.filterPill} ${activeFilter === "youtube" ? classes.filterPillActive : ""}`}
          onClick={() => setActiveFilter("youtube")}
        >
          <IconBrandYoutubeFilled size={14} color="#EF4444" />
          YouTube
        </button>
        <button
          type="button"
          className={`${classes.filterPill} ${activeFilter === "file" ? classes.filterPillActive : ""}`}
          onClick={() => setActiveFilter("file")}
        >
          <IconVideo size={14} color="#60A5FA" />
          Direct Video (MP4 / HLS)
        </button>
        <button
          type="button"
          className={`${classes.filterPill} ${activeFilter === "magnet" ? classes.filterPillActive : ""}`}
          onClick={() => setActiveFilter("magnet")}
        >
          <IconMagnetFilled size={14} color="#A78BFA" />
          Torrent Magnet
        </button>
      </div>

      {/* If media is currently playing, provide an option to remove the existing play */}
      {Boolean(roomMedia) && (
        <div className={classes.currentlyPlayingCard}>
          <div className={classes.currentlyPlayingMeta}>
            <div className={classes.currentlyPlayingLabel}>Currently Playing</div>
            <div
              className={classes.currentlyPlayingTitle}
              title={getMediaDisplayName(roomMedia)}
            >
              {getMediaDisplayName(roomMedia)}
            </div>
          </div>
          <button
            type="button"
            className={classes.removePlayBtn}
            onClick={() => {
              roomSetMedia("");
              if (onClose) onClose();
            }}
            disabled={disabled}
            title="Stop playback and remove current media"
          >
            <IconTrash size={14} />
            <span>Remove Play</span>
          </button>
        </div>
      )}

      {/* Main search / URL input */}
      <div className={classes.inputWrapper}>
        <TextInput
          ref={inputRef}
          className={classes.searchInput}
          placeholder="Paste video file URL, magnet link, YouTube link, or search..."
          value={inputMedia}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          disabled={disabled}
          leftSection={
            loading ? (
              <Loader size={16} color="violet" />
            ) : (
              <IconSearch size={16} color="var(--text-muted)" />
            )
          }
          rightSection={
            inputMedia ? (
              <button
                type="button"
                className={classes.clearBtn}
                onClick={handleClear}
                title="Clear input"
              >
                <IconX size={14} />
              </button>
            ) : (
              <span className={classes.shortcutKbd}>↵</span>
            )
          }
        />
      </div>

      {/* Direct stream detected card */}
      {isDirect && directType && (
        <div className={classes.directActionCard}>
          <div className={classes.directMeta}>
            <div className={classes.directTypeRow}>
              {directType.icon}
              <Badge size="xs" variant="light" color={directType.color}>
                {directType.label}
              </Badge>
              {addedUrls[trimmedInput] && (
                <span className={classes.toastPill}>
                  <IconCheck size={12} /> Added to playlist
                </span>
              )}
            </div>
            <div className={classes.directUrlText} title={trimmedInput}>
              {trimmedInput}
            </div>
          </div>
          <div className={classes.directActions}>
            <button
              type="button"
              className={classes.actionBtnPlay}
              onClick={() => handlePlayNow(trimmedInput)}
            >
              <IconPlayerPlayFilled size={14} />
              Play Now
            </button>
            <button
              type="button"
              className={classes.actionBtnPlaylist}
              onClick={() => handleAddToPlaylist(trimmedInput)}
              title="Add to room playlist"
            >
              <IconPlaylistAdd size={15} />
              + Playlist
            </button>
          </div>
        </div>
      )}

      {/* Section title */}
      <div className={classes.sectionHeader}>
        <span>
          {trimmedInput && !isDirect
            ? `Search Results (${filteredItems.length})`
            : "Featured Streams & Test Files"}
        </span>
        {trimmedInput && !isDirect && loading && (
          <span style={{ fontSize: "11px", color: "#A78BFA" }}>
            Searching...
          </span>
        )}
      </div>

      {/* Results / Suggestions List */}
      <div className={classes.resultsList}>
        {filteredItems.length === 0 && !loading && (
          <div className={classes.emptyResults}>
            <IconSearch size={28} opacity={0.4} />
            <span>No streams found for this search.</span>
            <span style={{ fontSize: "11.5px", color: "var(--text-muted)" }}>
              Paste a direct video file link, YouTube link, or WebTorrent magnet
              above.
            </span>
          </div>
        )}

        {filteredItems.map((item, index) => {
          const isAdded = Boolean(addedUrls[item.url]);
          return (
            <div
              key={`${item.url}-${index}`}
              className={classes.resultCard}
              onClick={() => handlePlayNow(item.url)}
              title={`Play ${item.name || item.url}`}
            >
              {/* Thumbnail with duration */}
              <div className={classes.thumbnailWrapper}>
                {Boolean(item.img) && !failedImages[item.url] ? (
                  <img
                    src={item.img}
                    alt={item.name}
                    className={classes.thumbnailImg}
                    loading="lazy"
                    onError={() => {
                      setFailedImages((prev) => ({
                        ...prev,
                        [item.url]: true,
                      }));
                    }}
                  />
                ) : (
                  <div className={classes.thumbnailPlaceholder}>
                    {item.type === "youtube" ? (
                      <IconBrandYoutubeFilled size={22} color="#EF4444" />
                    ) : item.type === "magnet" ? (
                      <IconMagnetFilled size={22} color="#A78BFA" />
                    ) : (
                      <IconVideo size={22} color="#60A5FA" />
                    )}
                  </div>
                )}
                {Boolean(item.duration && item.duration > 0) && (
                  <span className={classes.durationBadge}>
                    {formatTimestamp(item.duration)}
                  </span>
                )}
              </div>

              {/* Meta information */}
              <div className={classes.resultMeta}>
                <div className={classes.resultTitle}>
                  {decodeEntities(item.name || item.url)}
                </div>
                <div className={classes.resultChannel}>
                  {item.type === "youtube" ? (
                    <IconBrandYoutubeFilled size={12} color="#EF4444" />
                  ) : item.type === "magnet" ? (
                    <IconMagnetFilled size={12} color="#A78BFA" />
                  ) : (
                    <IconVideo size={12} color="#60A5FA" />
                  )}
                  <span>{item.channel || item.type.toUpperCase()}</span>
                </div>
              </div>

              {/* Action buttons */}
              <div
                className={classes.resultControls}
                onClick={(e) => e.stopPropagation()}
              >
                {isAdded ? (
                  <span className={classes.toastPill}>
                    <IconCheck size={12} /> Added
                  </span>
                ) : (
                  <Tooltip label="Add to Playlist" position="top">
                    <button
                      type="button"
                      className={classes.miniActionBtn}
                      onClick={() => handleAddToPlaylist(item.url)}
                    >
                      <IconPlaylistAdd size={15} />
                    </button>
                  </Tooltip>
                )}
                <Tooltip label="Play Now" position="top">
                  <button
                    type="button"
                    className={`${classes.miniActionBtn} ${classes.miniActionBtnPlay}`}
                    onClick={() => handlePlayNow(item.url)}
                  >
                    <IconPlayerPlayFilled size={14} />
                  </button>
                </Tooltip>
              </div>
            </div>
          );
        })}
      </div>

      {/* Footer bar with keyboard hints */}
      <div className={classes.footerBar}>
        <div className={classes.shortcutItem}>
          <span className={classes.shortcutKbd}>↵ Enter</span>
          <span>Play selected</span>
        </div>
        <div className={classes.shortcutItem}>
          <span className={classes.shortcutKbd}>Esc</span>
          <span>Close</span>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState } from "react";
import { Badge, Button, Menu, Progress, Slider } from "@mantine/core";
import { formatTimestamp, softWhite } from "../../utils/utils";
import styles from "./Controls.module.css";
import { MetadataContext } from "../../MetadataContext";
import {
  IconPlayerPlayFilled,
  IconPlayerPauseFilled,
  IconRefresh,
  IconCheck,
  IconRepeat,
  IconBadgeCc,
  IconVolumeOff,
  IconVolume,
  IconTheater,
  IconMaximize,
  IconPictureInPicture,
  IconPlayerSkipForwardFilled,
  IconMovie,
} from "@tabler/icons-react";

interface ControlsProps {
  duration: number;
  video: string;
  paused: boolean;
  muted: boolean;
  volume: number;
  subtitled: boolean;
  currentTime: number;
  disabled?: boolean;
  leaderTime?: number;
  isPauseDisabled?: boolean;
  localTogglePiP?: () => void;
  onOpenAddMedia?: () => void;
  playbackRate: number;
  roomPlaybackRate: number;
  isYouTube: boolean;
  isLiveStream: boolean;
  timeRanges: { start: number; end: number }[];
  loop: boolean;
  roomTogglePlay: () => void;
  roomSeek: (time: number) => void;
  roomSetPlaybackRate: (rate: number) => void;
  roomSetLoop: (loop: boolean) => void;
  localFullScreen: (fs: boolean) => void;
  localToggleMute: () => void;
  localSubtitleModal: () => void;
  localSeek: (time?: number) => void;
  localSetVolume: (volume: number) => void;
  localSetSubtitleMode: (mode: TextTrackMode, lang?: string) => void;
  roomPlaylistPlay: (index: number) => void;
  playlist: PlaylistVideo[];
}

export const Controls = (props: ControlsProps) => {
  const [hoverState, setHoverState] = useState({
    hoverTimestamp: 0,
    hoverPos: 0,
  });
  const [showTimestamp, setShowTimestamp] = useState(false);
  const [synced, setSynced] = useState(false);
  const getEnd = () => props.duration;
  const getStart = () => 0;
  const getLength = () => getEnd() - getStart();
  const getCurrent = () => props.currentTime;
  const getPercent = () => (getCurrent() - getStart()) / getLength();
  const zeroTime = useMemo(
    () => Math.floor(Date.now() / 1000) - props.duration,
    [props.video, Boolean(props.duration)],
  );
  const onMouseOver = () => {
    setShowTimestamp(true);
  };
  const onMouseOut = () => {
    setShowTimestamp(false);
  };
  const onMouseMove = (e: any) => {
    const rect = e.target.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const max = rect.width;
    const pct = x / max;
    // console.log(x, max);
    const target = getStart() + pct * getLength();
    // console.log(pct);
    if (pct >= 0) {
      setHoverState({ hoverTimestamp: target, hoverPos: pct });
    }
  };
  const {
    roomTogglePlay,
    roomSeek,
    localFullScreen,
    localToggleMute,
    localSubtitleModal,
    localSeek,
    currentTime,
    leaderTime,
    isPauseDisabled,
    disabled,
    subtitled,
    paused,
    muted,
    volume,
    isLiveStream,
    playlist,
    roomPlaylistPlay,
    timeRanges,
    roomSetPlaybackRate,
    roomPlaybackRate,
  } = props;
  // console.log(leaderTime, currentTime);
  const behindThreshold = 0.8;
  const isLeaderTimeValid = typeof leaderTime === "number" && isFinite(leaderTime) && leaderTime >= 0;
  const behindTime =
    !isLiveStream && isLeaderTimeValid
      ? leaderTime - currentTime
      : getEnd() - getCurrent();
  const isBehind = isLeaderTimeValid ? behindTime > behindThreshold : false;
  const buffers = timeRanges.map(({ start, end }) => {
    const buffStartPct = (start / getLength()) * 100;
    const buffLengthPct = ((end - start) / getLength()) * 100;
    return (
      <div
        key={start}
        style={{
          position: "absolute",
          height: "8px",
          backgroundColor: "grey",
          left: buffStartPct + "%",
          width: buffLengthPct + "%",
          bottom: "0em",
          zIndex: 0,
          pointerEvents: "none",
        }}
      ></div>
    );
  });
  const playPauseProps = {
    onClick: () => {
      roomTogglePlay();
    },
    className: ` ${styles.action}`,
    disabled: disabled || isPauseDisabled,
  };
  return (
    <div className={styles.controls}>
      {paused ? (
        <IconPlayerPlayFilled {...playPauseProps} />
      ) : (
        <IconPlayerPauseFilled {...playPauseProps} />
      )}
      {playlist.length > 0 && (
        <IconPlayerSkipForwardFilled
          title="Skip to next"
          className={styles.action}
          onClick={() => roomPlaylistPlay(0)}
        />
      )}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          flexDirection: "column",
          position: "relative",
        }}
      >
        <Button
          size="compact-xs"
          color={synced ? "teal" : isBehind ? "blue" : "gray"}
          variant={synced || isBehind ? "filled" : "light"}
          title={!disabled ? "Sync room to current playback time" : "Sync playback with host"}
          onClick={() => {
            setSynced(true);
            setTimeout(() => setSynced(false), 1500);

            if (isLiveStream) {
              roomSeek(props.duration);
              localSeek();
            } else if (!disabled) {
              // User has room control (Host): sync all participants in room to current time
              const target =
                isBehind && isLeaderTimeValid
                  ? (leaderTime as number)
                  : getCurrent();
              roomSeek(target);
              localSeek(target);
            } else {
              // Guest syncing to host / leader
              localSeek();
            }
          }}
        >
          {synced ? "Synced!" : "Sync"}
        </Button>
      </div>
      <div className={` ${styles.text}`}>
        {formatTimestamp(getCurrent(), isLiveStream ? zeroTime : undefined)}
      </div>
      <Progress.Root
        radius="0px"
        onClick={(e: any) => {
          if (!disabled) {
            // Read the time from the click event
            if (e) {
              const rect = e.target.getBoundingClientRect();
              const x = e.clientX - rect.left;
              const max = rect.width;
              const pct = x / max;
              // roomseek operates on actual media element times, not timestamps
              // for DASH we set getStart() value to when stream started, so left side is 0 video time
              // even though it's not all seekable this makes the click to seek simple
              let target = getLength() * pct;
              roomSeek(target);
            }
          }
        }}
        onMouseOver={onMouseOver}
        onMouseOut={onMouseOut}
        onMouseMove={onMouseMove}
        style={{
          flexGrow: 1,
          marginTop: 0,
          marginBottom: 0,
          position: "relative",
          minWidth: "50px",
          overflow: "visible",
          cursor: "pointer",
        }}
      >
        <Progress.Section
          style={{ pointerEvents: "none", zIndex: 1 }}
          value={getPercent() * 100}
        ></Progress.Section>
        {buffers}
        {/* {
            <div
              style={{
                position: 'absolute',
                bottom: '0px',
                left: `calc(${this.getPercent() * 100 + '% - 6px'})`,
                pointerEvents: 'none',
                width: '12px',
                height: '12px',
                transform:
                  this.getLength() < Infinity && showTimestamp
                    ? 'scale(1, 1)'
                    : 'scale(0, 0)',
                transition: '0.25s all',
                borderRadius: '50%',
                backgroundColor: '#54c8ff',
              }}
            ></div>
          } */}
        {getLength() < Infinity && showTimestamp && (
          <Badge
            style={{
              position: "absolute",
              bottom: "10px",
              left: `calc(${hoverState.hoverPos * 100 + "%"})`,
              transform: "translate(-50%)",
              display: "inline-block",
            }}
          >
            {formatTimestamp(
              hoverState.hoverTimestamp,
              isLiveStream ? zeroTime : undefined,
            )}
          </Badge>
        )}
      </Progress.Root>
      <div className={` ${styles.text}`}>{formatTimestamp(getEnd())}</div>
      {isLiveStream && (
        <Badge size="xs" color="red">
          LIVE
        </Badge>
      )}
      {
        <Menu disabled={disabled}>
          <Menu.Target>
            <div
              className={`${styles.text} ${styles.action}`}
              style={{
                backgroundColor: "rgba(100,100,100, 0.6)",
                fontSize: 10,
                borderRadius: "4px",
                padding: "2px",
              }}
            >
              {props.playbackRate?.toFixed(2)}x
            </div>
          </Menu.Target>
          <Menu.Dropdown>
            {[
              { key: "Auto", text: "Auto", value: 0 },
              { key: "0.25", text: "0.25x", value: 0.25 },
              { key: "0.5", text: "0.5x", value: 0.5 },
              // { key: '0.75', text: '0.75x', value: 0.75 },
              { key: "1", text: "1x", value: 1 },
              // { key: '1.25', text: '1.25x', value: 1.25 },
              { key: "1.5", text: "1.5x", value: 1.5 },
              // { key: '1.75', text: '1.75x', value: 1.75 },
              { key: "2", text: "2x", value: 2 },
              { key: "3", text: "3x", value: 3 },
            ].map((item) => (
              <Menu.Item
                key={item.key}
                onClick={() => roomSetPlaybackRate(item.value)}
                rightSection={
                  roomPlaybackRate === item.value ? <IconCheck /> : null
                }
              >
                {item.text}
              </Menu.Item>
            ))}
          </Menu.Dropdown>
        </Menu>
      }
      <IconRepeat
        onClick={() => {
          if (!disabled) {
            props.roomSetLoop(Boolean(!props.loop));
          }
        }}
        className={` ${styles.action}`}
        title="Loop"
        color={props.loop ? "green" : softWhite}
      />
      {props.onOpenAddMedia && (
        <IconMovie
          onClick={() => {
            if (!disabled) {
              props.onOpenAddMedia?.();
            }
          }}
          className={styles.action}
          title={disabled ? "Controls locked" : "Set Movie / Media"}
          color={softWhite}
        />
      )}
      {props.isYouTube ? (
        <Menu>
          <Menu.Target>
            <IconBadgeCc className={styles.action} />
          </Menu.Target>
          <Menu.Dropdown>
            {[
              { key: "hidden", text: "Off", value: "hidden" },
              { key: "en", text: "English", value: "showing" },
              { key: "es", text: "Spanish", value: "showing" },
            ].map((item) => (
              <Menu.Item
                key={item.key}
                onClick={() =>
                  props.localSetSubtitleMode(
                    item.value as TextTrackMode,
                    item.key,
                  )
                }
              >
                {item.text}
              </Menu.Item>
            ))}
          </Menu.Dropdown>
        </Menu>
      ) : (
        <IconBadgeCc
          onClick={() => {
            localSubtitleModal();
          }}
          className={` ${styles.action}`}
          title="Captions"
          color={subtitled ? "green" : softWhite}
        />
      )}
