function formatDurationLabel(minutes: string): string {
  const num = Number(minutes);
  if (num < 60) return `${num}-Minute`;
  if (num === 60) return "1-Hour";
  if (num % 60 === 0) return `${num / 60}-Hour`;
  return `${minutes}-Minute`;
}

