import React, { useState, useEffect, useCallback, useMemo, useContext, useRef } from "react";
import { useHistory } from "react-router-dom";
import { Title, Text, Button, Loader, Center, Group } from "@mantine/core";
import { serverPath, serverCandidates, setServerPath, addAndSavePasscode } from "../../utils/utils";
import { getAccessToken, supabase } from "../../utils/supabaseClient";
import { MetadataContext } from "../../MetadataContext";
import styles from "./MyRooms.module.css";
import { Hero } from "./Hero";
import { RoomStats } from "./RoomStats";
import { RoomsToolbar } from "./RoomsToolbar";
import { RoomCard } from "./RoomCard";
import { RoomPagination } from "./RoomPagination";
import { IconArrowLeft, IconCalendarEvent, IconCirclePlusFilled } from "@tabler/icons-react";
import { Announce } from "../Announce/Announce";

export interface RoomSummary {
  roomId: string;
  isPasscodeProtected: boolean;
  currentPasscode?: string | null;
  creationTime: string;
  roomTitle: string | null;
  roomDescription: string | null;
  coverPhoto: string | null;
  isChatDisabled: boolean;
  isSubRoom: boolean;
  isWaitingLoungeEnabled?: boolean;
  status: "waiting" | "scheduled" | "active" | "inactive" | "expiring" | "expired" | "ended" | "cancelled";
  startedAt: string | null;
  expiresAt: string | null;
  endedAt: string | null;
  isPermanent?: boolean;
  durationMinutes?: number | null;
}

const areRoomsEqual = (a: RoomSummary[], b: RoomSummary[]): boolean => {
  if (a === b) return true;
  if (!Array.isArray(a) || !Array.isArray(b)) return false;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const rA = a[i];
    const rB = b[i];
    if (
      rA.roomId !== rB.roomId ||
      rA.status !== rB.status ||
      rA.roomTitle !== rB.roomTitle ||
      rA.roomDescription !== rB.roomDescription ||
      rA.expiresAt !== rB.expiresAt ||
      rA.coverPhoto !== rB.coverPhoto ||
      rA.isPermanent !== rB.isPermanent ||
      rA.isChatDisabled !== rB.isChatDisabled ||
      rA.isPasscodeProtected !== rB.isPasscodeProtected ||
      rA.currentPasscode !== rB.currentPasscode ||
      rA.isWaitingLoungeEnabled !== rB.isWaitingLoungeEnabled
    ) {
      return false;
    }
  }
  return true;
};

export const useRooms = (user: any) => {
  const [rooms, setRooms] = useState<RoomSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const roomsRef = useRef<RoomSummary[]>([]);
  roomsRef.current = rooms;
  const isInitialLoadRef = useRef(true);

  const fetchRooms = useCallback(async (options?: { silent?: boolean }) => {
    if (!user) {
      setLoading(false);
      return;
    }

    // Always update silently if rooms already exist in memory or silent option is set
    const isSilent = options?.silent ?? (!isInitialLoadRef.current || roomsRef.current.length > 0);
    if (!isSilent && roomsRef.current.length === 0) {
      setLoading(true);
    }

    try {
      const token = await getAccessToken();
      let response: Response | undefined;
      const candidatesToTry = [serverPath, ...serverCandidates.filter((c: string) => c !== serverPath)];

      for (let i = 0; i < candidatesToTry.length; i++) {
        const candidate = candidatesToTry[i];
        try {
          const res = await fetch(`${candidate}/listRooms`, {
            headers: { Authorization: `Bearer ${token}` },
          });
          const contentType = res.headers.get("content-type") || "";
          if (res.ok && contentType.includes("application/json")) {
            response = res;
            if (candidate !== serverPath) {
              setServerPath(candidate);
            }
            break;
          } else {
            response = res;
          }
        } catch (fetchErr) {
          if (i === candidatesToTry.length - 1 && !response) {
            throw fetchErr;
          }
        }
      }

      if (!response || !response.ok) {
        const contentType = response?.headers.get("content-type") || "";
        let errMsg = response ? `Failed to fetch rooms (${response.status})` : "Failed to fetch rooms";
        if (contentType.includes("application/json")) {
          const errData = await response?.json().catch(() => null);
          errMsg = errData?.error?.message || errData?.error || errMsg;
        }
        throw new Error(errMsg);
      }
      const contentType = response.headers.get("content-type") || "";
      if (!contentType.includes("application/json")) {
        throw new Error("Invalid response received from server. Please verify backend connection.");
      }
      const data = await response.json();
      if (Array.isArray(data)) {
        data.forEach((r: RoomSummary) => {
          if (r.currentPasscode) {
            addAndSavePasscode(r.roomId, r.currentPasscode);
          }
        });
      }

      // Reconcile state silently: if data didn't change, preserve array reference to prevent re-render cascades
      setRooms(prev => {
        if (areRoomsEqual(prev, data)) {
          return prev;
        }
        return data;
      });
      setError(null);
    } catch (err: any) {
      // If we already have rooms loaded, do not blow up UI on background refresh failure
      if (roomsRef.current.length === 0) {
        setError(err.message);
      } else {
        console.warn("Silent background room refresh failed:", err.message);
      }
    } finally {
      isInitialLoadRef.current = false;
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    void fetchRooms();
    const interval = setInterval(() => {
      void fetchRooms({ silent: true });
    }, 30000);
    return () => clearInterval(interval);
  }, [fetchRooms]);

  const deleteRoom = async (roomId: string) => {
    try {
      const token = await getAccessToken();

      // Clean up storage bucket files for this room
      try {
        const cleanId = roomId.startsWith("/") ? roomId.substring(1) : roomId;
        const folderPath = `${user.id}/${cleanId}`;
        const { data: files } = await supabase.storage.from("room_covers").list(folderPath);
        if (files && files.length > 0) {
          const filesToRemove = files.map(f => `${folderPath}/${f.name}`);
          await supabase.storage.from("room_covers").remove(filesToRemove);
        }
      } catch (storageErr) {
        console.warn("Storage cleanup error:", storageErr);
      }

      const response = await fetch(`${serverPath}/deleteRoom?roomId=${roomId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (response.ok) {
        setRooms(prev => prev.filter(r => r.roomId !== roomId));
        return true;
      }
      const errData = await response.json().catch(() => null);
      throw new Error(errData?.error?.message || errData?.error || "Failed to delete room");
    } catch (e: any) {
      console.error("deleteRoom error:", e);
      throw e;
    }
  };

  const updateRoomCover = async (roomId: string, coverPhoto: string) => {
    try {
      const token = await getAccessToken();
      const response = await fetch(`${serverPath}/updateRoomCover`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ uid: user?.id, token, roomId, coverPhoto })
      });
      if (response.ok) {
        setRooms(prev => prev.map(r => r.roomId === roomId ? { ...r, coverPhoto } : r));
        return true;
      }
      return false;
    } catch (e) {
      console.error(e);
      return false;
    }
  };

  const silentRefresh = useCallback(() => fetchRooms({ silent: true }), [fetchRooms]);

  return { rooms, loading, error, deleteRoom, updateRoomCover, refresh: silentRefresh };
};

export const MyRooms = () => {
  const { user } = useContext(MetadataContext);
  const { rooms, loading, error, deleteRoom, updateRoomCover, refresh } = useRooms(user);

  const [searchQuery, setSearchQuery] = useState("");
  const [sortOption, setSortOption] = useState("newest");

  const [viewMode, setViewModeState] = useState<'grid' | 'stack'>(() => {
    try {
      const stored = localStorage.getItem('cowatch-room-view-mode');
      if (stored === 'grid' || stored === 'stack') return stored;
    } catch (e) { }
    return 'grid';
  });

  const setViewMode = useCallback((mode: 'grid' | 'stack') => {
    setViewModeState(mode);
    try {
      localStorage.setItem('cowatch-room-view-mode', mode);
    } catch (e) { }
  }, []);

  const [currentPage, setCurrentPage] = useState(1);

  const history = useHistory();
  const PAGE_SIZE = 12;

  // Reset to page 1 when search or sort changes
  useEffect(() => {
    setCurrentPage(1);
  }, [searchQuery, sortOption]);

  const filteredAndSortedRooms = useMemo(() => {
    let result = rooms;
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(r =>
        r.roomTitle?.toLowerCase().includes(q) ||
        r.roomDescription?.toLowerCase().includes(q)
      );
    }

    result = [...result].sort((a, b) => {
      if (sortOption === "newest") {
        return new Date(b.creationTime).getTime() - new Date(a.creationTime).getTime();
      } else if (sortOption === "oldest") {
        return new Date(a.creationTime).getTime() - new Date(b.creationTime).getTime();
      } else if (sortOption === "title-asc") {
        return (a.roomTitle || "").localeCompare(b.roomTitle || "");
      } else if (sortOption === "title-desc") {
        return (b.roomTitle || "").localeCompare(a.roomTitle || "");
      } else if (sortOption === "expiring") {
        const aIsActive = a.status === "active" || a.status === "expiring";
        const bIsActive = b.status === "active" || b.status === "expiring";
        if (aIsActive && !bIsActive) return -1;
        if (!aIsActive && bIsActive) return 1;
        if (aIsActive && bIsActive && a.expiresAt && b.expiresAt) {
          return new Date(a.expiresAt).getTime() - new Date(b.expiresAt).getTime();
        }
        return 0;
      }
      return 0;
    });
    return result;
  }, [rooms, searchQuery, sortOption]);

  const activeRooms = useMemo(() => filteredAndSortedRooms.filter(r => r.status === 'active' || r.status === 'expiring'), [filteredAndSortedRooms]);
  const upcomingRooms = useMemo(() => filteredAndSortedRooms.filter(r => r.status === 'waiting' || r.status === 'scheduled'), [filteredAndSortedRooms]);
  const historyRooms = useMemo(() => filteredAndSortedRooms.filter(r => r.status === 'ended' || r.status === 'expired' || r.status === 'cancelled'), [filteredAndSortedRooms]);

  const paginatedHistory = useMemo(() => {
    const startIndex = (currentPage - 1) * PAGE_SIZE;
    return historyRooms.slice(startIndex, startIndex + PAGE_SIZE);
  }, [historyRooms, currentPage]);

  if (!user && !loading) {
    return (
      <div className={styles.page}>
        <Center style={{ height: '50vh' }}>
          <Text>Please sign in to view your rooms.</Text>
        </Center>
      </div>
    );
  }

  return (
    <>
      <Announce page="myrooms" />
      <div className={styles.page}>
        <div className={styles.container}>
        <div className={styles.topNav}>
          <button
            type="button"
            className={styles.backBtn}
            onClick={() => {
              if (window.history.length > 1) {
                history.goBack();
              } else {
                history.push("/");
              }
            }}
          >
            <IconArrowLeft size={16} />
            <span>Back to Home</span>
          </button>
          <Button
            size="sm"
            variant="default"
            leftSection={<IconCalendarEvent size={15} />}
            onClick={() => history.push("/rooms/schedule")}
            style={{ fontWeight: 600, borderRadius: "10px" }}
          >
            Schedule Room
          </Button>
        </div>

        <Hero>
          <RoomStats rooms={rooms} />
        </Hero>

        {loading && rooms.length === 0 ? (
          <Center style={{ minHeight: "200px" }}><Loader size="lg" color="violet" /></Center>
        ) : error ? (
          <Center style={{ minHeight: "200px" }}><Text c="red">{error}</Text></Center>
        ) : rooms.length === 0 ? (
          <div style={{ textAlign: "center", padding: "64px 0", background: "var(--bg-surface)", borderRadius: "16px", border: "1px solid var(--border-subtle)", marginTop: "32px" }}>
            <Title order={3} mb="sm" style={{ color: "var(--text-primary)" }}>No rooms yet</Title>
            <Text c="dimmed" mb="lg">Create a room now or schedule a watch party for later.</Text>
            <Group justify="center" gap="md">
              <Button
                size="md"
                variant="gradient"
                gradient={{ from: "#8B5CF6", to: "#EC4899", deg: 135 }}
                leftSection={<IconCirclePlusFilled size={18} />}
                onClick={() => history.push("/room/new")}
                style={{ fontWeight: 600, borderRadius: "10px" }}
              >
                Create your first room
              </Button>
              <Button
                size="md"
                variant="default"
                leftSection={<IconCalendarEvent size={18} />}
                onClick={() => history.push("/rooms/schedule")}
                style={{ fontWeight: 600, borderRadius: "10px" }}
              >
                Schedule a room
              </Button>
            </Group>
          </div>
        ) : (
          <>
            <RoomsToolbar
              searchQuery={searchQuery}
              setSearchQuery={setSearchQuery}
              sortOption={sortOption}
              setSortOption={setSortOption}
              viewMode={viewMode}
              setViewMode={setViewMode}
            />

            <div className={styles.roomSection}>
              {activeRooms.length > 0 && (
                <div style={{ marginBottom: "40px" }}>
                  <Title order={4} mb="md" style={{ color: "var(--text-primary)" }}>Active Rooms</Title>
                  <div className={viewMode === 'grid' ? styles.roomGrid : styles.roomList}>
                    {activeRooms.map(room => (
                      <RoomCard key={room.roomId} room={room} onDelete={deleteRoom} onRefresh={refresh} onUpdateCover={updateRoomCover} viewMode={viewMode} />
                    ))}
                  </div>
                </div>
              )}

              {upcomingRooms.length > 0 && (
                <div style={{ marginBottom: "40px" }}>
                  <Title order={4} mb="md" style={{ color: "var(--text-primary)" }}>Upcoming Rooms</Title>
                  <div className={viewMode === 'grid' ? styles.roomGrid : styles.roomList}>
                    {upcomingRooms.map(room => (
                      <RoomCard key={room.roomId} room={room} onDelete={deleteRoom} onRefresh={refresh} onUpdateCover={updateRoomCover} viewMode={viewMode} />
                    ))}
                  </div>
                </div>
              )}

              {historyRooms.length > 0 && (
                <div style={{ marginBottom: "40px" }}>
                  <Title order={4} mb="md" style={{ color: "var(--text-primary)" }}>History</Title>
                  <div className={viewMode === 'grid' ? styles.roomGrid : styles.roomList}>
                    {paginatedHistory.map(room => (
                      <RoomCard key={room.roomId} room={room} onDelete={deleteRoom} onRefresh={refresh} onUpdateCover={updateRoomCover} viewMode={viewMode} />
                    ))}
                  </div>
                  <RoomPagination
                    currentPage={currentPage}
                    pageSize={PAGE_SIZE}
                    totalItems={historyRooms.length}
                    onPageChange={setCurrentPage}
                  />
                </div>
              )}

              {filteredAndSortedRooms.length === 0 && (
                <Center style={{ minHeight: "200px" }}>
                  <Text c="dimmed">No rooms match your search.</Text>
                </Center>
              )}
            </div>
          </>
        )}
      </div>
    </div>
    </>
  );
};

import React, { useState, useRef, useEffect } from "react";
import { useHistory } from "react-router-dom";
import {
  Badge,
  Button,
  ActionIcon,
  Menu,
  Modal,
  TextInput,
  Textarea,
  Switch,
  PasswordInput,
  Divider,
  Group,
  Stack,
  Text,
  Box,
  FileButton,
  Tooltip,
  Alert,
} from "@mantine/core";
import {
  IconTrash,
  IconCopy,
  IconPlayerPlayFilled,
  IconSettings,
  IconLock,
  IconLockOpen,
  IconMessage,
  IconPhotoPlus,
  IconDots,
  IconPlayerStop,
  IconHourglassHigh,
  IconEye,
  IconEyeOff,
  IconCheck,
  IconAlertCircle,
  IconClock,
  IconInfinity,
} from "@tabler/icons-react";
import { type RoomSummary } from "./MyRooms";
import {
  getRoomUrl,
  serverPath,
  addAndSavePasscode,
  getSavedPasscodes,
  removeSavedPasscode,
} from "../../utils/utils";
import { supabase, getAccessToken } from "../../utils/supabaseClient";
import styles from "./MyRooms.module.css";

// --- Pure Helpers ---

const getComputedState = (room: RoomSummary) => {
  if (room.status === "expired") return "Expired";
  if (room.status === "ended") return "Ended";
  if (room.status === "waiting") return "Waiting";
  if (room.isPermanent) return "Permanent";
  if (!room.expiresAt) return "Permanent";
  const now = Date.now();
  const exp = new Date(room.expiresAt).getTime();
  if (exp <= now) return "Expired";
  return "Active";
};

const RoomStatusBadge = ({ status, isPermanent }: { status: string; isPermanent: boolean }) => {
  if (status === "waiting") return <Badge color="yellow" variant="filled" size="sm">● WAITING</Badge>;
  if (status === "active") return <Badge color="teal" variant="filled" size="sm">● ACTIVE</Badge>;
  if (status === "expiring") return <Badge color="orange" variant="filled" size="sm">● EXPIRING SOON</Badge>;
  if (status === "expired" || status === "ended") return <Badge color="gray" variant="filled" size="sm">● ENDED</Badge>;
  if (status === "scheduled") return <Badge color="blue" variant="filled" size="sm">● SCHEDULED</Badge>;
  return <Badge color="yellow" variant="filled" size="sm">● INACTIVE</Badge>;
};

const formatDurationLabel = (minutes: number | null | undefined): string => {
  if (!minutes) return "";
  if (minutes < 60) return `${minutes}m session`;
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (m === 0) return h === 1 ? "1h session" : `${h}h session`;
  return `${h}h ${m}m session`;
};

const formatTimeLeft = (expiresAt: string | null, status: string, isPermanent: boolean, durationMinutes?: number | null) => {
  if (status === "expired" || status === "ended") return <span className={styles.lifecycleText}>Room ended</span>;
  if (status === "waiting") {
    if (isPermanent) {
      return (
        <span className={styles.lifecycleBadge}>
          <IconInfinity size={13} color="var(--color-teal)" />
          <span>Permanent (not started)</span>
        </span>
      );
    }
    const durationLabel = formatDurationLabel(durationMinutes);
    return (
      <span className={styles.lifecycleBadge}>
        <IconClock size={13} color="var(--color-yellow)" />
        <span>{durationLabel ? `${durationLabel} -- not started` : "Not started"}</span>
      </span>
    );
  }
  if (isPermanent) {
    return (
      <span className={styles.lifecycleBadge}>
        <IconInfinity size={13} color="var(--color-teal)" />
        <span>Permanent</span>
      </span>
    );
  }
  if (status !== "active" && status !== "expiring") return <span className={styles.lifecycleText}>Inactive</span>;

  if (!expiresAt) return null;

  const now = Date.now();
  const diff = new Date(expiresAt).getTime() - now;

  if (diff <= 0) return <span className={styles.lifecycleText}>Expired</span>;

  const hours = Math.floor(diff / (1000 * 60 * 60));
  const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));

  if (status === "expiring") {
    return (
      <span className={styles.lifecycleExpiring}>
        <IconHourglassHigh size={13} />
        <span>{minutes}m remaining</span>
      </span>
    );
  }

  return (
    <span className={styles.lifecycleBadge}>
      <IconClock size={13} color="var(--color-violet)" />
      <span>Expires in {hours > 0 ? `${hours}h ` : ''}{minutes}m</span>
    </span>
  );
};

// --- Shared Edit Modal ---
export const EditRoomModal = ({
  room,
  opened,
  onClose,
  onSuccess,
}: {
  room: RoomSummary;
  opened: boolean;
  onClose: () => void;
  onSuccess: () => void;
}) => {
  const computedState = getComputedState(room);
  const isExpired = Boolean(
    computedState === "Expired" ||
    computedState === "Ended" ||
    room.status === "expired" ||
    room.status === "ended" ||
    (!room.isPermanent && room.expiresAt && new Date(room.expiresAt).getTime() <= Date.now())
  );
  const isActiveOrStarted = Boolean(
    computedState === "Active" ||
    room.status === "active" ||
    room.status === "expiring" ||
    Boolean(room.startedAt)
  );
  const isLocked = isExpired || isActiveOrStarted;

  const cleanId = room.roomId.startsWith("/") ? room.roomId.substring(1) : room.roomId;
  const initialPasscode =
    room.currentPasscode ||
    getSavedPasscodes()[room.roomId] ||
    getSavedPasscodes()[cleanId] ||
    getSavedPasscodes()[`/${cleanId}`] ||
    "";

  const [title, setTitle] = useState(room.roomTitle || "");
  const [description, setDescription] = useState(room.roomDescription || "");
  const [isChatDisabled, setIsChatDisabled] = useState(room.isChatDisabled || false);

  // Password management
  const [currentPassword, setCurrentPassword] = useState(initialPasscode);
  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [copiedCurrentPassword, setCopiedCurrentPassword] = useState(false);
  const [removeProtection, setRemoveProtection] = useState(false);

  const [password, setPassword] = useState("");
  const [passwordConfirm, setPasswordConfirm] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");

  const [coverFile, setCoverFile] = useState<File | null>(null);
  const [coverPreview, setCoverPreview] = useState<string | null>(room.coverPhoto || null);
  const [removeCover, setRemoveCover] = useState(false);

  useEffect(() => {
    if (opened) {
      const saved =
        room.currentPasscode ||
        getSavedPasscodes()[room.roomId] ||
        getSavedPasscodes()[cleanId] ||
        getSavedPasscodes()[`/${cleanId}`] ||
        "";
      setCurrentPassword(saved);
      setShowCurrentPassword(false);
      setCopiedCurrentPassword(false);
      setRemoveProtection(false);
      setPassword("");
      setPasswordConfirm("");
      setError("");
      setTitle(room.roomTitle || "");
      setDescription(room.roomDescription || "");
      setIsChatDisabled(room.isChatDisabled || false);
      setCoverPreview(room.coverPhoto || null);
      setCoverFile(null);
      setRemoveCover(false);
    }
  }, [opened, room, cleanId]);

  const handleCopyCurrentPassword = () => {
    if (!currentPassword) return;
    void navigator.clipboard.writeText(currentPassword);
    setCopiedCurrentPassword(true);
    setTimeout(() => setCopiedCurrentPassword(false), 2000);
  };

  const handleFileChange = (payload: File | null) => {
    if (isLocked) return;
    if (payload) {
      if (payload.size > 1 * 1024 * 1024) {
        setError("Cover photo too large (max 1MB).");
        return;
      }
      setCoverFile(payload);
      setCoverPreview(URL.createObjectURL(payload));
      setRemoveCover(false);
    }
  };

  const handleRemoveCover = () => {
    if (isLocked) return;
    setCoverFile(null);
    setCoverPreview(null);
    setRemoveCover(true);
  };

  const handleSave = async () => {
    if (isExpired) {
      setError("This room has expired and can no longer be edited.");
      return;
    }
    if (isActiveOrStarted) {
      setError("Room configurations cannot be modified while the room is active. Room modifications are not allowed once a room is started.");
      return;
    }
    setError("");
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError("Room title is required.");
      return;
    }
    if (trimmedTitle.length > 50) {
      setError("Room title must be under 50 characters.");
      return;
    }
    if (description.length > 500) {
      setError("Description must be under 500 characters.");
      return;
    }
    if (!removeProtection && password && password !== passwordConfirm) {
      setError("Passwords do not match.");
      return;
    }

    setIsSaving(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      const token = await getAccessToken();
      if (!user) throw new Error("Not logged in");

      let finalCoverUrl = room.coverPhoto;

      if (coverFile) {
        const fileExt = coverFile.name.split('.').pop();
        const safeRoomId = room.roomId.startsWith("/") ? room.roomId.substring(1) : room.roomId;
        const folderPath = `${user.id}/${safeRoomId}`;

        // Clean up old cover files in folder to prevent orphans
        try {
          const { data: oldFiles } = await supabase.storage.from('room_covers').list(folderPath);
          if (oldFiles && oldFiles.length > 0) {
            await supabase.storage.from('room_covers').remove(oldFiles.map(f => `${folderPath}/${f.name}`));
          }
        } catch (_) { }

        const filePath = `${folderPath}/cover.${fileExt}`;
        const { error: uploadError } = await supabase.storage
          .from('room_covers')
          .upload(filePath, coverFile, { upsert: true });

        if (uploadError) {
          throw uploadError;
        }

        const { data: publicUrlData } = supabase.storage.from('room_covers').getPublicUrl(filePath);
        finalCoverUrl = `${publicUrlData.publicUrl}?t=${Date.now()}`;
      }

      const payloadPassword = removeProtection ? "" : (password ? password.trim() : undefined);

      const response = await fetch(`${serverPath}/updateRoomSettings`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          uid: user.id,
          token,
          roomId: room.roomId,
          roomTitle: trimmedTitle,
          roomDescription: description,
          isChatDisabled,
          removePassword: removeProtection,
          password: payloadPassword,
        }),
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.error || "Failed to save room settings");

      if (removeProtection) {
        removeSavedPasscode(room.roomId);
        setCurrentPassword("");
      } else if (password) {
        addAndSavePasscode(room.roomId, password.trim());
        setCurrentPassword(password.trim());
      }

      if (removeCover && room.coverPhoto) {
        await fetch(`${serverPath}/updateRoomCover`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ uid: user.id, token, roomId: room.roomId, coverPhoto: null }),
        });
      } else if (coverFile && finalCoverUrl && finalCoverUrl !== room.coverPhoto) {
        await fetch(`${serverPath}/updateRoomCover`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ uid: user.id, token, roomId: room.roomId, coverPhoto: finalCoverUrl }),
        });
      }

      onSuccess();
      onClose();
    } catch (e: any) {
      setError(e.message || "Failed to update room settings.");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      centered
      size="min(560px, calc(100vw - 20px))"
      radius="lg"
      padding={0}
      withCloseButton={true}
      classNames={{
        root: styles.editRoomModalRoot,
        inner: styles.editRoomModalInner,
        content: styles.editRoomModalContent,
        header: styles.editRoomModalHeader,
        body: styles.editRoomModalBody,
      }}
      styles={{
        title: {
          flex: "1 1 auto",
          minWidth: 0,
        },
        close: {
          color: "var(--text-secondary)",
          flexShrink: 0,
          marginLeft: "8px",
        },
      }}
      title={
        <Box style={{ minWidth: 0, paddingRight: "4px" }}>
          <Text
            fw={700}
            size="md"
            c="var(--text-primary)"
            style={{
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            Edit Room
          </Text>
          <Text
            size="xs"
            c="dimmed"
            mt={1}
            style={{
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            Update how your room appears and behaves.
          </Text>
        </Box>
      }
    >
      {/* SCROLLABLE FORM BODY */}
      <Box
        style={{
          padding: "16px 14px",
          overflowY: "auto",
          flex: "1 1 0%",
          minHeight: 0,
          overscrollBehavior: "contain",
          display: "flex",
          flexDirection: "column",
          gap: "20px",
          width: "100%",
          boxSizing: "border-box",
        }}
      >
        {isExpired && (
          <Alert color="red" variant="light" title="Room Closed" icon={<IconAlertCircle size={16} />}>
            This room has expired or ended. Closed rooms can no longer be edited.
          </Alert>
        )}
        {isActiveOrStarted && (
          <Alert
            color="violet"
            variant="light"
            title="Room is Active"
            icon={<IconAlertCircle size={16} />}
            styles={{
              root: {
                backgroundColor: "rgba(139, 92, 246, 0.08)",
                borderColor: "rgba(139, 92, 246, 0.25)",
              },
            }}
          >
            Room configurations cannot be modified while the room is active. Room modifications are not allowed once a room is started.
          </Alert>
        )}
        {error && (
          <Alert color="red" variant="light" title="Error" icon={<IconAlertCircle size={16} />}>
            {error}
          </Alert>
        )}

        {/* ROOM IDENTITY */}
        <Box style={isLocked ? { opacity: 0.6, pointerEvents: "none" } : undefined}>
          <Text size="xs" fw={700} c="dimmed" tt="uppercase" lts={1} mb="sm">
            Room Identity
          </Text>
          <Stack gap="sm">
            <TextInput
              label="Room Title"
              value={title}
              onChange={(e) => setTitle(e.currentTarget.value)}
              maxLength={50}
              required
              disabled={isLocked}
              placeholder="Enter room title..."
            />
            <Textarea
              label="Description"
              value={description}
              onChange={(e) => setDescription(e.currentTarget.value)}
              maxLength={500}
              autosize
              minRows={2}
              maxRows={4}
              disabled={isLocked}
              placeholder="What is this watch party about? (optional)"
            />

            <Box>
              <Text size="sm" fw={500} mb={6}>Cover Photo</Text>
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: "12px",
                  width: "100%",
                }}
              >
                <Box
                  style={{
                    width: 140,
                    height: 80,
                    maxWidth: "100%",
                    borderRadius: 8,
                    overflow: 'hidden',
                    backgroundColor: 'var(--bg-base)',
                    border: '1px solid var(--border-subtle)',
                    position: 'relative',
                    flexShrink: 0,
                  }}
                >
                  {coverPreview ? (
                    <img
                      src={coverPreview}
                      style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      alt="Cover Preview"
                    />
                  ) : (
                    <Text
                      size="xs"
                      c="dimmed"
                      style={{
                        position: 'absolute',
                        top: '50%',
                        left: '50%',
                        transform: 'translate(-50%, -50%)',
                      }}
                    >
                      No cover
                    </Text>
                  )}
                </Box>
                {!isLocked && (
                  <div
                    style={{
                      display: "flex",
                      flexDirection: "column",
                      gap: "6px",
                      flex: "1 1 140px",
                      minWidth: "120px",
                    }}
                  >
                    <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
                      <FileButton onChange={handleFileChange} accept="image/png,image/jpeg,image/webp">
                        {(props) => (
                          <Button variant="default" size="xs" {...props}>
                            Change cover
                          </Button>
                        )}
                      </FileButton>
                      {coverPreview && (
                        <Button
                          variant="subtle"
                          color="red"
                          size="xs"
                          onClick={handleRemoveCover}
                        >
                          Remove
                        </Button>
                      )}
                    </div>
                    <Text size="xs" c="dimmed" style={{ fontSize: "11px", lineHeight: 1.3 }}>
                      16:9 ratio (PNG, JPG, WEBP, max 1MB)
                    </Text>
                  </div>
                )}
              </div>
            </Box>
          </Stack>
        </Box>

        <Divider style={{ borderColor: "var(--border-subtle)" }} />

        {/* ROOM BEHAVIOR */}
        <Box style={isLocked ? { opacity: 0.6, pointerEvents: "none" } : undefined}>
          <Text size="xs" fw={700} c="dimmed" tt="uppercase" lts={1} mb="sm">
            Room Behavior
          </Text>
          <Stack gap="md">
            <Group justify="space-between" align="center" wrap="nowrap" gap="sm" style={{ width: "100%" }}>
              <Box style={{ flex: "1 1 auto", minWidth: 0, paddingRight: "8px" }}>
                <Text fw={500}>Chat Enabled</Text>
                <Text size="sm" c="dimmed">Allow participants to send messages in this room</Text>
              </Box>
              <Switch
                checked={!isChatDisabled}
                onChange={(e) => setIsChatDisabled(!e.currentTarget.checked)}
                color="violet"
                size="md"
                disabled={isLocked}
                style={{ flexShrink: 0 }}
              />
            </Group>
          </Stack>
        </Box>

        <Divider style={{ borderColor: "var(--border-subtle)" }} />

        {/* PASSWORD PROTECTION */}
        <Box style={isLocked ? { opacity: 0.6, pointerEvents: "none" } : undefined}>
          <Group justify="space-between" align="center" mb="sm" wrap="nowrap" gap="xs" style={{ width: "100%" }}>
            <Text size="xs" fw={700} c="dimmed" tt="uppercase" lts={1} style={{ minWidth: 0, flex: "1 1 auto" }}>
              Password Protection
            </Text>
            {room.isPasscodeProtected && !removeProtection ? (
              <Badge color="violet" variant="light" leftSection={<IconLock size={12} />} style={{ flexShrink: 0 }}>
                Protected
              </Badge>
            ) : removeProtection ? (
              <Badge color="red" variant="light" leftSection={<IconLockOpen size={12} />} style={{ flexShrink: 0 }}>
                Removing
              </Badge>
            ) : (
              <Badge color="gray" variant="light" leftSection={<IconLockOpen size={12} />} style={{ flexShrink: 0 }}>
                Unprotected
              </Badge>
            )}
          </Group>

          <Stack gap="md">
            {room.isPasscodeProtected && (
              <Box
                style={{
                  padding: "12px",
                  borderRadius: "8px",
                  border: "1px solid var(--border-subtle)",
                  backgroundColor: "var(--bg-elevated)",
                  width: "100%",
                  boxSizing: "border-box",
                }}
              >
                {currentPassword ? (
                  <Stack gap="xs" style={{ width: "100%" }}>
                    <Group justify="space-between" align="center" wrap="nowrap" gap="xs" style={{ width: "100%" }}>
                      <Text size="xs" fw={600} c="dimmed" tt="uppercase" style={{ flex: "1 1 auto", minWidth: 0 }}>
                        Current Password
                      </Text>
                      <Button
                        variant="subtle"
                        color={removeProtection ? "violet" : "red"}
                        size="compact-xs"
                        disabled={isExpired}
                        style={{ flexShrink: 0 }}
                        onClick={() => {
                          setRemoveProtection(!removeProtection);
                          if (!removeProtection) {
                            setPassword("");
                            setPasswordConfirm("");
                          }
                        }}
                      >
                        {removeProtection ? "Keep Password" : "Remove"}
                      </Button>
                    </Group>
                    <TextInput
                      readOnly
                      type={showCurrentPassword ? "text" : "password"}
                      value={currentPassword}
                      rightSectionWidth={68}
                      rightSection={
                        <div style={{ display: "flex", alignItems: "center", gap: "2px", paddingRight: "4px" }}>
                          <Tooltip label={showCurrentPassword ? "Hide password" : "Show password"} withArrow>
                            <ActionIcon
                              variant="subtle"
                              color="gray"
                              size="sm"
                              onClick={() => setShowCurrentPassword(!showCurrentPassword)}
                              aria-label="Toggle password visibility"
                            >
                              {showCurrentPassword ? <IconEyeOff size={16} /> : <IconEye size={16} />}
                            </ActionIcon>
                          </Tooltip>
                          <Tooltip label={copiedCurrentPassword ? "Copied!" : "Copy password"} withArrow>
                            <ActionIcon
                              variant="subtle"
                              color={copiedCurrentPassword ? "green" : "gray"}
                              size="sm"
                              onClick={handleCopyCurrentPassword}
                              aria-label="Copy current password"
                            >
                              {copiedCurrentPassword ? <IconCheck size={16} /> : <IconCopy size={16} />}
                            </ActionIcon>
                          </Tooltip>
                        </div>
                      }
                      styles={{
                        input: {
                          fontFamily: showCurrentPassword ? "inherit" : "monospace",
                          letterSpacing: showCurrentPassword ? "normal" : "2px",
                        },
                      }}
                    />
                  </Stack>
                ) : (
                  <Stack gap="xs" style={{ width: "100%" }}>
                    <Group justify="space-between" align="center" wrap="nowrap" gap="xs" style={{ width: "100%" }}>
                      <Group gap={6} style={{ minWidth: 0, flex: "1 1 auto" }}>
                        <IconLock size={16} color="var(--mantine-color-violet-6)" style={{ flexShrink: 0 }} />
                        <Text size="sm" fw={500} style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                          Room is password-protected
                        </Text>
                      </Group>
                      <Button
                        variant="subtle"
                        color={removeProtection ? "violet" : "red"}
                        size="compact-xs"
                        disabled={isLocked}
                        style={{ flexShrink: 0 }}
                        onClick={() => {
                          setRemoveProtection(!removeProtection);
                          if (!removeProtection) {
                            setPassword("");
                            setPasswordConfirm("");
                          }
                        }}
                      >
                        {removeProtection ? "Keep Protection" : "Remove"}
                      </Button>
                    </Group>
                    <Text size="xs" c="dimmed">
                      {removeProtection
                        ? "Password protection will be removed when you save changes."
                        : "Passcode is securely encrypted. Enter a new password below to update and view it, or click Remove to disable protection."}
                    </Text>
                  </Stack>
                )}
              </Box>
            )}

            {removeProtection ? (
              <Text size="sm" c="red" fw={500}>
                Password protection will be removed when you click Save Changes.
              </Text>
            ) : (
              <Stack gap="sm">
                <Text size="xs" c="dimmed">
                  {room.isPasscodeProtected
                    ? "Enter a new password to change or update protection. Leave blank to keep current settings."
                    : "Enter a password to require guests to enter a passcode before joining. Leave blank for an open room."}
                </Text>
                <PasswordInput
                  label={room.isPasscodeProtected ? "New password" : "Set password"}
                  placeholder={room.isPasscodeProtected ? "Leave blank to keep current" : "Enter password (optional)"}
                  value={password}
                  onChange={(e) => setPassword(e.currentTarget.value)}
                  disabled={isLocked}
                />
                {password.length > 0 && (
                  <PasswordInput
                    label="Confirm password"
                    placeholder="Confirm new password"
                    value={passwordConfirm}
                    onChange={(e) => setPasswordConfirm(e.currentTarget.value)}
                    disabled={isLocked}
                  />
                )}
              </Stack>
            )}
          </Stack>
        </Box>
      </Box>

      {/* FIXED / STICKY FOOTER */}
      <Box
        style={{
          padding: "12px 16px",
          paddingBottom: "max(12px, env(safe-area-inset-bottom))",
          borderTop: "1px solid var(--border-subtle)",
          background: "var(--bg-elevated)",
          display: "flex",
          justifyContent: "flex-end",
          alignItems: "center",
          gap: "10px",
          flexShrink: 0,
          width: "100%",
          boxSizing: "border-box",
        }}
      >
        <Button variant="default" onClick={onClose} disabled={isSaving} size="sm">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          loading={isSaving}
          disabled={isLocked}
          color="violet"
          size="sm"
        >
          Save Changes
        </Button>
      </Box>
    </Modal>
  );
};

// --- Shared Action Hook ---
const useRoomActions = (room: RoomSummary, onDelete: (id: string) => void, onRefresh?: () => void, onUpdateCover?: (id: string, url: string) => void) => {
  const [isDeleting, setIsDeleting] = useState(false);
  const [deleteModalOpened, setDeleteModalOpened] = useState(false);
  const [endModalOpened, setEndModalOpened] = useState(false);
  const [isEnding, setIsEnding] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [editModalOpened, setEditModalOpened] = useState(false);
  const [startConfirmOpened, setStartConfirmOpened] = useState(false);
  const [isStarting, setIsStarting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const history = useHistory();

  const confirmStartRoom = async () => {
    setIsStarting(true);
    try {
      const token = await getAccessToken();
      const user = (await supabase.auth.getUser()).data.user;
      const response = await fetch(`${serverPath}/startRoom`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          uid: user?.id,
          token,
          roomId: room.roomId,
        }),
      });
      if (!response.ok) {
        const data = await response.json().catch(() => null);
        throw new Error(data?.error || "Failed to start room.");
      }
      history.push(urlPath);
    } catch (e: any) {
      setActionError(e.message || "Failed to start room.");
    } finally {
      setIsStarting(false);
      setStartConfirmOpened(false);
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(getRoomUrl(room.roomId)).catch(console.error);
  };

  const handleDeleteClick = () => {
    setDeleteModalOpened(true);
  };

  const confirmDelete = async () => {
    setIsDeleting(true);
    try {
      await onDelete(room.roomId);
      setDeleteModalOpened(false);
    } catch (err: any) {
      setActionError(err.message || "Failed to delete room");
    } finally {
      setIsDeleting(false);
    }
  };

  const handleEndRoomClick = () => {
    setEndModalOpened(true);
  };

  const confirmEndRoom = async () => {
    setIsEnding(true);
    try {
      const token = await getAccessToken();
      const user = await supabase.auth.getUser();
      if (!user.data.user) throw new Error("Please log in");
      const response = await fetch(`${serverPath}/endRoom`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          uid: user.data.user.id,
          token,
          roomId: room.roomId,
        }),
      });
      const contentType = response.headers.get("content-type") || "";
      if (!contentType.includes("application/json")) {
        throw new Error("Invalid response from server");
      }
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error?.message || data.error || "Failed to end room");
      }
      setEndModalOpened(false);
      if (onRefresh) {
        onRefresh();
      }
    } catch (e: any) {
      setActionError(e.message || "Failed to end room");
    } finally {
      setIsEnding(false);
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !onUpdateCover) return;

    const computedState = getComputedState(room);
    if (computedState === 'Expired' || computedState === 'Ended' || room.status === 'expired' || room.status === 'ended' || (!room.isPermanent && room.expiresAt && new Date(room.expiresAt).getTime() <= Date.now())) {
      setActionError("Expired rooms cannot be edited.");
      if (fileInputRef.current) fileInputRef.current.value = "";
      return;
    }
    const isActiveOrStarted = Boolean(
      computedState === 'Active' ||
      room.status === 'active' ||
      room.status === 'expiring' ||
      Boolean(room.startedAt)
    );
    if (isActiveOrStarted) {
      setActionError("Room configurations cannot be modified while the room is active. Room modifications are not allowed once a room is started.");
      if (fileInputRef.current) fileInputRef.current.value = "";
      return;
    }

    setIsUploading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error("Not logged in");
      if (file.size > 1 * 1024 * 1024) throw new Error("Cover photo too large (max 1MB).");

      const fileExt = file.name.split('.').pop();
      const safeRoomId = room.roomId.startsWith("/") ? room.roomId.substring(1) : room.roomId;
      const folderPath = `${user.id}/${safeRoomId}`;

      // Clean up old cover files in folder to prevent orphans
      try {
        const { data: oldFiles } = await supabase.storage.from('room_covers').list(folderPath);
        if (oldFiles && oldFiles.length > 0) {
          await supabase.storage.from('room_covers').remove(oldFiles.map(f => `${folderPath}/${f.name}`));
        }
      } catch (_) { }

      const filePath = `${folderPath}/cover.${fileExt}`;
      const { error: uploadError } = await supabase.storage.from('room_covers').upload(filePath, file, { upsert: true });
      if (uploadError) throw uploadError;

      const { data: publicUrlData } = supabase.storage.from('room_covers').getPublicUrl(filePath);
      onUpdateCover(room.roomId, `${publicUrlData.publicUrl}?t=${Date.now()}`);
    } catch (e: any) {
      setActionError(e.message || "Failed to upload cover photo.");
    } finally {
      setIsUploading(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  const computedState = getComputedState(room);
  const isPermanent = computedState === 'Permanent';
  const isActiveOrStarted = Boolean(
    computedState === 'Active' ||
    room.status === 'active' ||
    room.status === 'expiring' ||
    Boolean(room.startedAt)
  );
  const urlPath = `/watch/${room.roomId.replace(/^\//, '')}`;
  const detailsPath = `/myrooms/${room.roomId}`;

  const renderPrimary = () => {
    if (computedState === 'Expired' || computedState === 'Ended') {
      return (
        <Button
          variant="default"
          onClick={() => history.push(detailsPath)}
          radius="md"
          className={styles.cardPrimaryBtn}
        >
          Details
        </Button>
      );
    }
    if (computedState === 'Waiting') {
      return (
        <Button
          variant="gradient"
          gradient={{ from: "violet", to: "grape", deg: 135 }}
          onClick={() => setStartConfirmOpened(true)}
          leftSection={<IconPlayerPlayFilled size={14} />}
          radius="md"
          className={styles.cardPrimaryBtn}
        >
          Start Room
        </Button>
      );
    }
    return (
      <Button
        variant="gradient"
        gradient={{ from: "violet", to: "grape", deg: 135 }}
        onClick={() => history.push(urlPath)}
        leftSection={<IconPlayerPlayFilled size={14} />}
        radius="md"
        className={styles.cardPrimaryBtn}
      >
        Open Room
      </Button>
    );
  };

  const renderSecondary = () => {
    if (computedState === 'Expired' || computedState === 'Ended') return null;
    return (
      <Button
        variant="default"
        onClick={() => history.push(detailsPath)}
        radius="md"
        className={styles.cardSecondaryBtn}
      >
        Details
      </Button>
    );
  };

  const renderMenuItems = () => {
    const items = [];
    items.push(
      <Menu.Item key="copy" leftSection={<IconCopy size={14} />} onClick={handleCopy}>
        Copy Room Link
      </Menu.Item>
    );

    if (computedState !== 'Expired' && computedState !== 'Ended') {
      items.push(<Menu.Divider key="div1" />);

      if (!isActiveOrStarted) {
        items.push(
          <Menu.Item key="settings" leftSection={<IconSettings size={14} />} onClick={() => setEditModalOpened(true)}>
            Edit Room
          </Menu.Item>
        );
      }
      items.push(
        <Menu.Item key="end" leftSection={<IconPlayerStop size={14} />} onClick={handleEndRoomClick}>
          End Room
        </Menu.Item>
      );
    }

    items.push(<Menu.Divider key="div2" />);
    items.push(
      <Menu.Item key="delete" color="red" leftSection={<IconTrash size={14} />} onClick={handleDeleteClick}>
        Delete Room
      </Menu.Item>
    );
    return items;
  };

  const renderModals = () => (
    <>
      {/* START ROOM CONFIRMATION MODAL (Before entering room) */}
      <Modal
        opened={startConfirmOpened}
        onClose={() => setStartConfirmOpened(false)}
        title="Start Watch Party"
        centered
      >
        <Stack gap="sm" mb="lg">
          <Text size="sm">
            You are about to launch <strong>{room.roomTitle || room.roomId}</strong>.
          </Text>
          <div
            style={{
              padding: "12px 14px",
              borderRadius: "10px",
              backgroundColor: "rgba(139, 92, 246, 0.08)",
              border: "1px solid rgba(139, 92, 246, 0.25)",
              display: "flex",
              flexDirection: "column",
              gap: "4px",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px", fontWeight: 600, fontSize: "14px", color: "var(--text-primary)" }}>
              <IconClock size={16} color="var(--color-violet)" />
              <span>
                {isPermanent
                  ? "Permanent Room (no expiration)"
                  : `Session Duration: ${formatDurationLabel(room.durationMinutes) || "5h session"}`}
              </span>
            </div>
            {!isPermanent && (
              <Text size="xs" c="dimmed">
                The countdown begins when you start the watch party.
              </Text>
            )}
          </div>
        </Stack>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setStartConfirmOpened(false)}>
            Cancel
          </Button>
          <Button
            color="violet"
            onClick={confirmStartRoom}
            loading={isStarting}
            leftSection={<IconPlayerPlayFilled size={15} />}
          >
            Start Watch Party
          </Button>
        </Group>
      </Modal>

      {/* DELETE CONFIRMATION MODAL */}
      <Modal
        opened={deleteModalOpened}
        onClose={() => setDeleteModalOpened(false)}
        title="Delete Room"
        centered
      >
        <Text size="sm" mb="lg">
          Are you sure you want to delete <strong>{room.roomTitle || room.roomId}</strong> forever? All messages and room settings will be lost.
        </Text>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setDeleteModalOpened(false)}>
            Keep Room
          </Button>
          <Button color="red" onClick={confirmDelete} loading={isDeleting}>
            Delete Room
          </Button>
        </Group>
      </Modal>

      {/* END ROOM CONFIRMATION MODAL */}
      <Modal
        opened={endModalOpened}
        onClose={() => setEndModalOpened(false)}
        title="End Watch Party"
        centered
      >
        <Text size="sm" mb="lg">
          Are you sure you want to end <strong>{room.roomTitle || room.roomId}</strong>? Guests will no longer be able to watch or join this room.
        </Text>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setEndModalOpened(false)}>
            Cancel
          </Button>
          <Button color="orange" onClick={confirmEndRoom} loading={isEnding}>
            End Room
          </Button>
        </Group>
      </Modal>

      {/* ERROR / NOTICE MODAL */}
      <Modal
        opened={Boolean(actionError)}
        onClose={() => setActionError(null)}
        title="Notice"
        centered
      >
        <Text size="sm" mb="lg">
          {actionError}
        </Text>
        <Group justify="flex-end">
          <Button onClick={() => setActionError(null)} color="violet">
            OK
          </Button>
        </Group>
      </Modal>

      {/* EDIT ROOM MODAL */}
      <EditRoomModal
        room={room}
        opened={editModalOpened}
        onClose={() => setEditModalOpened(false)}
        onSuccess={() => {
          if (onRefresh) onRefresh();
          else window.location.reload();
        }}
      />
    </>
  );

  return {
    isUploading,
    fileInputRef,
    isActiveOrStarted,
    handleFileUpload,
    renderPrimary,
    renderSecondary,
    renderMenuItems,
    renderModals,
  };
};

// --- View Components ---

const GridRoomCard = ({
  room,
  onDelete,
  onRefresh,
  onUpdateCover,
}: {
  room: RoomSummary;
  onDelete: (id: string) => void;
  onRefresh?: () => void;
  onUpdateCover?: (id: string, url: string) => void;
}) => {
  const actions = useRoomActions(room, onDelete, onRefresh, onUpdateCover);
  const isPermanent = Boolean(room.isPermanent);
  const isClosed = Boolean(room.status === 'expired' || room.status === 'ended' || (!isPermanent && room.expiresAt && new Date(room.expiresAt).getTime() <= Date.now()));
  const creationDate = new Date(room.creationTime).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });

  return (
    <div className={styles.gridCard}>
      <div className={styles.gridCardCover}>
        {room.coverPhoto ? (
          <img src={room.coverPhoto} alt="Room Cover" className={styles.cover} />
        ) : (
          <div className={styles.coverPlaceholder}>WATCH PARTY</div>
        )}

        <div style={{ position: 'absolute', bottom: 12, right: 12, zIndex: 10 }}>
          <RoomStatusBadge status={room.status} isPermanent={isPermanent} />
        </div>

        {!isClosed && !actions.isActiveOrStarted && onUpdateCover && (
          <>
            <ActionIcon
              variant="filled" color="dark" size="md" radius="md" loading={actions.isUploading}
              style={{ position: 'absolute', top: 12, right: 12, zIndex: 10, backgroundColor: 'rgba(0,0,0,0.6)' }}
              onClick={(e) => { e.stopPropagation(); actions.fileInputRef.current?.click(); }}
            >
              <IconPhotoPlus size={16} color="white" />
            </ActionIcon>
            <input type="file" accept="image/*" ref={actions.fileInputRef} style={{ display: 'none' }} onChange={actions.handleFileUpload} />
          </>
        )}
      </div>

      <div className={styles.gridCardBody}>
        <h3 className={styles.roomTitle} title={room.roomTitle || "Watch Party Room"}>
          {room.roomTitle || "Watch Party Room"}
        </h3>
        <div className={styles.roomDescription}>
          {room.roomDescription || "No description provided."}
        </div>

        <div className={styles.roomMetadata}>
          <div className={styles.metaBadge}>
            {room.isPasscodeProtected ? (
              <>
                <IconLock size={12} color="var(--color-violet)" />
                <span>Protected</span>
              </>
            ) : (
              <>
                <IconLockOpen size={12} color="var(--text-muted)" />
                <span>Public</span>
              </>
            )}
          </div>
          <div className={styles.metaBadge}>
            <IconMessage size={12} color="var(--text-muted)" />
            <span>{room.isChatDisabled ? 'Chat off' : 'Chat on'}</span>
          </div>
          <div className={styles.metaDate}>{creationDate}</div>
        </div>

        <div className={styles.roomLifecycle}>
          {formatTimeLeft(room.expiresAt, room.status, isPermanent, room.durationMinutes)}
        </div>
      </div>

      <div className={styles.roomActionsBar}>
        <div className={styles.actionButtons}>
          {actions.renderPrimary()}
          {actions.renderSecondary()}
        </div>
        <Menu shadow="md" width={220} position="bottom-end">
          <Menu.Target>
            <ActionIcon variant="subtle" color="gray" size="lg" radius="md" className={styles.cardDotsBtn}>
              <IconDots size={18} />
            </ActionIcon>
          </Menu.Target>
          <Menu.Dropdown>
            {actions.renderMenuItems()}
          </Menu.Dropdown>
        </Menu>
      </div>

      {actions.renderModals()}
    </div>
  );
};

const StackRoomCard = ({
  room,
  onDelete,
  onRefresh,
  onUpdateCover,
}: {
  room: RoomSummary;
  onDelete: (id: string) => void;
  onRefresh?: () => void;
  onUpdateCover?: (id: string, url: string) => void;
}) => {
  const actions = useRoomActions(room, onDelete, onRefresh, onUpdateCover);
  const isPermanent = Boolean(room.isPermanent);
  const isClosed = Boolean(room.status === 'expired' || room.status === 'ended' || (!isPermanent && room.expiresAt && new Date(room.expiresAt).getTime() <= Date.now()));
  const creationDate = new Date(room.creationTime).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });

  return (
    <div className={styles.stackCard}>
      <div className={styles.stackCardCover}>
        {room.coverPhoto ? (
          <img src={room.coverPhoto} alt="Room Cover" className={styles.cover} />
        ) : (
          <div className={styles.coverPlaceholder}>WATCH PARTY</div>
        )}

        {!isClosed && !actions.isActiveOrStarted && onUpdateCover && (
          <>
            <ActionIcon
              variant="filled" color="dark" size="sm" radius="md" loading={actions.isUploading}
              style={{ position: 'absolute', top: 8, right: 8, zIndex: 10, backgroundColor: 'rgba(0,0,0,0.6)' }}
              onClick={(e) => { e.stopPropagation(); actions.fileInputRef.current?.click(); }}
            >
              <IconPhotoPlus size={14} color="white" />
            </ActionIcon>
            <input type="file" accept="image/*" ref={actions.fileInputRef} style={{ display: 'none' }} onChange={actions.handleFileUpload} />
          </>
        )}
      </div>

      <div className={styles.stackCardContent}>
        <div className={styles.stackCardHeader}>
          <div className={styles.stackCardTitleBox}>
            <h3 className={styles.roomTitle} title={room.roomTitle || "Watch Party Room"}>
              {room.roomTitle || "Watch Party Room"}
            </h3>
            <div className={styles.roomDescription}>
              {room.roomDescription || "No description provided."}
            </div>
          </div>

          <div className={styles.stackCardLifecycleBox}>
            <RoomStatusBadge status={room.status} isPermanent={isPermanent} />
            {formatTimeLeft(room.expiresAt, room.status, isPermanent, room.durationMinutes)}
          </div>
        </div>

        <div className={styles.stackCardBottom}>
          <div className={styles.roomMetadata} style={{ marginBottom: 0 }}>
            <div className={styles.metaItemValue}>
              {room.isPasscodeProtected ? (
                <>
                  <IconLock size={14} /> Protected
                </>
              ) : (
                <>
                  <IconLockOpen size={14} /> Public
                </>
              )}
            </div>
            <div className={styles.metaItemValue}>
              <IconMessage size={14} /> {room.isChatDisabled ? 'Chat disabled' : 'Chat enabled'}
            </div>
            <div className={styles.metaItemValue}>
              Created {creationDate}
            </div>
          </div>

          <div className={styles.actionButtons}>
            {actions.renderPrimary()}
            {actions.renderSecondary()}
            <Menu shadow="md" width={220} position="bottom-end">
              <Menu.Target>
                <ActionIcon variant="subtle" color="gray" size="lg" radius="md">
                  <IconDots size={18} />
                </ActionIcon>
              </Menu.Target>
              <Menu.Dropdown>
                {actions.renderMenuItems()}
              </Menu.Dropdown>
            </Menu>
          </div>
        </div>
      </div>

      {actions.renderModals()}
    </div>
  );
};

// --- Main Wrapper ---

export const RoomCard = ({
  room,
  onDelete,
  onRefresh,
  onUpdateCover,
  viewMode,
}: {
  room: RoomSummary;
  onDelete: (id: string) => void;
  onRefresh?: () => void;
  onUpdateCover?: (id: string, url: string) => void;
  viewMode: 'grid' | 'stack';
}) => {
  if (viewMode === 'stack') {
    return <StackRoomCard room={room} onDelete={onDelete} onRefresh={onRefresh} onUpdateCover={onUpdateCover} />;
  }
  return <GridRoomCard room={room} onDelete={onDelete} onRefresh={onRefresh} onUpdateCover={onUpdateCover} />;
};

import React, { useState, useEffect } from "react";
import { useParams, useHistory } from "react-router-dom";
import {
  Title,
  Text,
  Badge,
  Button,
  Group,
  Modal,
  Loader,
  Paper,
  ActionIcon,
  Tooltip,
  SegmentedControl,
  Avatar,
  ScrollArea,
  Stack,
} from "@mantine/core";

const formatDuration = (minutes: number | null | undefined): string => {
  if (!minutes) return "";
  if (minutes < 60) return `${minutes}m`;
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  if (m === 0) return h === 1 ? "1 hour" : `${h} hours`;
  return `${h}h ${m}m`;
};
import {
  IconArrowLeft,
  IconPlayerPlay,
  IconPlayerPlayFilled,
  IconCopy,
  IconSettings,
  IconLock,
  IconLockOpen,
  IconEye,
  IconEyeOff,
  IconCheck,
  IconCalendar,
  IconClock,
  IconUsers,
  IconMessage,
  IconShieldCheck,
  IconAlertTriangle,
  IconInfoCircle,
  IconExternalLink,
  IconActivity,
  IconInfinity,
  IconTrash,
  IconPlayerStop,
} from "@tabler/icons-react";
import { serverPath, getRoomUrl, addAndSavePasscode, getSavedPasscodes } from "../../utils/utils";
import { getAccessToken, supabase } from "../../utils/supabaseClient";
import styles from "./RoomDetails.module.css";
import { EditRoomModal } from "./RoomCard";

export interface LifecycleEvent {
  id: string;
  actor: string;
  event: string;
  previousStatus: string | null;
  newStatus: string | null;
  previousExpiresAt: string | null;
  newExpiresAt: string | null;
  reason: string | null;
  timestamp: string;
}

export interface RoomDetailsData {
  roomId: string;
  isPasscodeProtected: boolean;
  currentPasscode?: string | null;
  creationTime: string;
  roomTitle: string;
  roomDescription: string | null;
  coverPhoto: string | null;
  isChatDisabled: boolean;
  isSubRoom: boolean;
  status: "waiting" | "scheduled" | "active" | "inactive" | "expiring" | "expired" | "ended";
  startedAt: string | null;
  expiresAt: string | null;
  endedAt: string | null;
  isPermanent: boolean;
  durationMinutes?: number | null;
  owner_id?: string;
  lifecycleEvents: LifecycleEvent[];
  chatSummary?: {
    messagesCount: number;
    lastMessageAt: string | null;
  };
  chatMessages?: ChatMessageItem[];
}

interface ChatMessageItem {
  id: string;
  roomId: string;
  user_id: string | null;
  message: string;
  message_type: 'user' | 'system';
  event_type?: string | null;
  metadata?: any;
  created_at: string;
  authorName?: string;
  authorAvatar?: string;
}

const getStatusConfig = (status: RoomDetailsData["status"]) => {
  switch (status) {
    case "waiting":
      return {
        label: "Waiting to Start",
        color: "yellow",
        dotClass: styles.inactive,
        description: "Created and ready. The timer begins when the host starts the party.",
        badgeColor: "yellow",
      };
    case "active":
      return {
        label: "Active",
        color: "green",
        dotClass: styles.active,
        description: "People are watching right now.",
        badgeColor: "green",
      };
    case "inactive":
      return {
        label: "Inactive",
        color: "yellow",
        dotClass: styles.inactive,
        description: "Empty right now. Starts when someone joins.",
        badgeColor: "yellow",
      };
    case "expiring":
      return {
        label: "Closing Soon",
        color: "orange",
        dotClass: styles.expiring,
        description: "This room will close soon.",
        badgeColor: "orange",
      };
    case "scheduled":
      return {
        label: "Scheduled",
        color: "blue",
        dotClass: styles.scheduled,
        description: "Set up for an upcoming watch party.",
        badgeColor: "blue",
      };
    case "ended":
      return {
        label: "Ended",
        color: "gray",
        dotClass: styles.ended,
        description: "This watch party has finished.",
        badgeColor: "gray",
      };
    case "expired":
      return {
        label: "Expired",
        color: "red",
        dotClass: styles.expired,
        description: "This temporary room has expired and is closed.",
        badgeColor: "red",
      };
    default:
      return {
        label: status || "Unknown",
        color: "gray",
        dotClass: styles.inactive,
        description: "Room status.",
        badgeColor: "gray",
      };
  }
};

export const RoomDetails = () => {
  const { roomId } = useParams<{ roomId: string }>();
  const history = useHistory();
  const [room, setRoom] = useState<RoomDetailsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [copiedPassword, setCopiedPassword] = useState(false);
  const [copiedUrl, setCopiedUrl] = useState(false);
  const [copiedRoomId, setCopiedRoomId] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [editModalOpened, setEditModalOpened] = useState(false);
  const [activeHistoryTab, setActiveHistoryTab] = useState<"chat" | "activity">("chat");

  const fetchRoomDetails = async () => {
    setLoading(true);
    try {
      const token = await getAccessToken();
      const user = await supabase.auth.getUser();
      if (!user.data.user) throw new Error("Not authenticated");

      const response = await fetch(`${serverPath}/roomDetails?roomId=${roomId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!response.ok) {
        if (response.status === 404) throw new Error("Room not found or unauthorized");
        throw new Error("Failed to fetch room details");
      }
      const contentType = response.headers.get("content-type") || "";
      if (!contentType.includes("application/json")) {
        throw new Error("Received invalid response from server");
      }
      const data = await response.json();
      if (data && data.currentPasscode) {
        addAndSavePasscode(data.roomId, data.currentPasscode);
      }
      setRoom(data);
      setError(null);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const currentPasscode =
    room?.currentPasscode ||
    (room?.roomId && getSavedPasscodes()[room.roomId]) ||
    (room?.roomId && getSavedPasscodes()[room.roomId.startsWith("/") ? room.roomId.substring(1) : room.roomId]) ||
    "";

  useEffect(() => {
    void fetchRoomDetails();
  }, [roomId]);

  const handleCopyUrl = () => {
    if (!room) return;
    const url = getRoomUrl(room.roomId);
    navigator.clipboard.writeText(url).then(() => {
      setCopiedUrl(true);
      setTimeout(() => setCopiedUrl(false), 2000);
    }).catch(console.error);
  };

  const handleCopyRoomId = () => {
    if (!room) return;
    navigator.clipboard.writeText(room.roomId).then(() => {
      setCopiedRoomId(true);
      setTimeout(() => setCopiedRoomId(false), 2000);
    }).catch(console.error);
  };

  const handleCopyPassword = () => {
    if (!currentPasscode) return;
    navigator.clipboard.writeText(currentPasscode).then(() => {
      setCopiedPassword(true);
      setTimeout(() => setCopiedPassword(false), 2000);
    }).catch(console.error);
  };

  const handleDelete = async () => {
    if (!room) return;
    setIsDeleting(true);
    try {
      const token = await getAccessToken();
      const user = await supabase.auth.getUser();
      const uid = user.data.user?.id;

      // Clean up storage bucket files for this room
      if (uid) {
        try {
          const cleanId = room.roomId.startsWith("/") ? room.roomId.substring(1) : room.roomId;
          const folderPath = `${uid}/${cleanId}`;
          const { data: files } = await supabase.storage.from("room_covers").list(folderPath);
          if (files && files.length > 0) {
            const filesToRemove = files.map(f => `${folderPath}/${f.name}`);
            await supabase.storage.from("room_covers").remove(filesToRemove);
          }
        } catch (storageErr) {
          console.warn("Storage cleanup error:", storageErr);
        }
      }

      const response = await fetch(`${serverPath}/deleteRoom?roomId=${room.roomId}`, {
        method: "DELETE",
        headers: { Authorization: `Bearer ${token}` },
      });
      if (response.ok) {
        history.push("/myrooms");
      } else {
        const errData = await response.json().catch(() => null);
        throw new Error(errData?.error?.message || errData?.error || "Failed to delete room");
      }
    } catch (e: any) {
      console.error(e);
      setActionError(e.message || "Failed to delete room");
      setIsDeleting(false);
      setDeleteConfirm(false);
    }
  };

  const [nowTime, setNowTime] = useState(Date.now());
  const [actionError, setActionError] = useState<string | null>(null);
  const [isStarting, setIsStarting] = useState(false);
  const [startConfirm, setStartConfirm] = useState(false);

  const handleStartRoom = async () => {
    if (!room) return;
    setIsStarting(true);
    setActionError(null);
    try {
      const token = await getAccessToken();
      const user = await supabase.auth.getUser();
      const response = await fetch(`${serverPath}/startRoom`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ uid: user.data.user?.id, token, roomId: room.roomId }),
      });
      if (response.ok) {
        history.push(urlPath);
      } else {
        const errData = await response.json().catch(() => null);
        throw new Error(errData?.error?.message || errData?.error || "Failed to start room");
      }
    } catch (e: any) {
      console.error(e);
      setActionError(e.message || "Failed to start room");
    } finally {
      setIsStarting(false);
      setStartConfirm(false);
    }
  };

  const [isCancelling, setIsCancelling] = useState(false);
  const [cancelConfirm, setCancelConfirm] = useState(false);

  const confirmCancelRoom = async () => {
    if (!room) return;
    setIsCancelling(true);
    try {
      const token = await getAccessToken();
      const user = await supabase.auth.getUser();
      const response = await fetch(`${serverPath}/cancelRoom`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ uid: user.data.user?.id, token, roomId: room.roomId }),
      });
      if (response.ok) {
        setCancelConfirm(false);
        await fetchRoomDetails();
      } else {
        const errData = await response.json().catch(() => null);
        throw new Error(errData?.error?.message || errData?.error || "Failed to cancel room");
      }
    } catch (e: any) {
      console.error(e);
      setActionError(e.message || "Failed to cancel room");
    } finally {
      setIsCancelling(false);
    }
  };

  useEffect(() => {
    const timer = setInterval(() => {
      setNowTime(Date.now());
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  const [endConfirm, setEndConfirm] = useState(false);
  const [isEnding, setIsEnding] = useState(false);

  const confirmEndRoom = async () => {
    if (!room) return;
    setIsEnding(true);
    try {
      const token = await getAccessToken();
      const user = await supabase.auth.getUser();
      const response = await fetch(`${serverPath}/endRoom`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ uid: user.data.user?.id, token, roomId: room.roomId }),
      });
      if (response.ok) {
        setEndConfirm(false);
        await fetchRoomDetails();
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsEnding(false);
    }
  };

  if (loading) {
    return (
      <div style={{ display: "flex", justifyContent: "center", alignItems: "center", minHeight: "60vh" }}>
        <Loader size="lg" color="violet" />
      </div>
    );
  }

  if (error || !room) {
    return (
      <div className={styles.container}>
        <Button variant="subtle" leftSection={<IconArrowLeft size={16} />} onClick={() => history.push("/myrooms")} mb="xl">
          Back to My Rooms
        </Button>
        <Paper withBorder p="xl" radius="md" style={{ textAlign: "center" }}>
          <Title order={3} c="red" mb="sm">Something went wrong</Title>
          <Text>{error || "Could not load this room."}</Text>
        </Paper>
      </div>
    );
  }

  const statusStr = room.status as string;
  const isClosed = statusStr === "expired" || statusStr === "ended" || statusStr === "cancelled";
  const isActiveOrStarted = Boolean(
    statusStr === "active" ||
    statusStr === "expiring" ||
    room.startedAt
  );
  const isWaiting = room.status === "waiting";
  const isScheduled = room.status === "scheduled";
  const isOpenable = !isClosed && (room.status === "active" || room.status === "expiring" || room.status === "scheduled" || room.status === "inactive");
  const urlPath = `/watch/${room.roomId.replace(/^\//, "")}`;
  const statusConfig = getStatusConfig(room.status);

  // Time remaining calculator
  const getExpiresIn = () => {
    if (!room.expiresAt) return null;
    if (room.status === "expired" || room.status === "ended") return "Expired";
    const diff = new Date(room.expiresAt).getTime() - nowTime;
    if (diff <= 0) return "Expired";
    const hours = Math.floor(diff / (1000 * 60 * 60));
    const mins = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    if (hours > 0) return `${hours}h ${mins}m left`;
    return `${mins}m left`;
  };

  const expiresInText = getExpiresIn();

  return (
    <div className={styles.container}>
      {/* BREADCRUMBS */}
      <div className={styles.breadcrumb}>
        <span className={styles.breadcrumbLink} onClick={() => history.push("/myrooms")}>
          <IconArrowLeft size={15} /> My Rooms
        </span>
        <span className={styles.breadcrumbSeparator}>/</span>
        <span className={styles.breadcrumbCurrent}>{room.roomTitle || room.roomId}</span>
      </div>

      {actionError && (
        <Paper withBorder p="md" radius="md" mb="md" style={{ backgroundColor: "rgba(239, 68, 68, 0.1)", borderColor: "rgba(239, 68, 68, 0.3)" }}>
          <Group justify="space-between">
            <Text c="red" size="sm" fw={600}>{actionError}</Text>
            <ActionIcon size="xs" variant="subtle" color="red" onClick={() => setActionError(null)}>
              <IconCheck size={12} />
            </ActionIcon>
          </Group>
        </Paper>
      )}

      {/* HERO SECTION */}
      <div className={styles.hero}>
        {room.coverPhoto ? (
          <>
            <img src={room.coverPhoto} alt="Room Cover" className={styles.heroCover} />
            <div className={styles.heroScrim} />
          </>
        ) : (
          <>
            <div className={styles.heroFallbackBg} />
            <div className={styles.heroScrim} />
          </>
        )}

        <div className={styles.heroContent}>
          {/* Top Bar inside Hero */}
          <div className={styles.heroTopRow}>
            <div className={styles.statusPill}>
              <div className={`${styles.pulseDot} ${statusConfig.dotClass}`} />
              <span style={{ color: "rgba(255,255,255,0.9)" }}>{statusConfig.label}</span>
            </div>
          </div>

          {/* Bottom Row inside Hero */}
          <div className={styles.heroBottomRow}>
            <div className={styles.heroMeta}>
              <h1 className={styles.heroTitle}>
                {room.roomTitle || "Watch Party Room"}
              </h1>

              {room.roomDescription && (
                <p className={styles.heroDescription}>
                  {room.roomDescription}
                </p>
              )}

              <Tooltip label={isClosed ? "Room is expired — link disabled" : (copiedUrl ? "Copied to clipboard!" : "Click to copy invite link")} withArrow>
                <div
                  className={styles.heroUrlBadge}
                  onClick={isClosed ? undefined : handleCopyUrl}
                  style={isClosed ? { opacity: 0.5, cursor: "not-allowed", textDecoration: "line-through" } : undefined}
                >
                  {copiedUrl && !isClosed ? <IconCheck size={14} color="#10B981" /> : <IconCopy size={14} />}
                  <span>/watch/{room.roomId.replace(/^\//, "")}</span>
                </div>
              </Tooltip>
            </div>

            <div className={styles.heroActions}>
              {isOpenable && (
                <Button
                  size="md"
                  className={styles.primaryOpenBtn}
                  onClick={() => history.push(urlPath)}
                  leftSection={<IconPlayerPlayFilled size={16} />}
                >
                  Join Room
                </Button>
              )}
              {isWaiting && (
                <>
                  <Button
                    size="md"
                    className={styles.primaryOpenBtn}
                    onClick={() => setStartConfirm(true)}
                    loading={isStarting}
                    leftSection={!isStarting ? <IconPlayerPlayFilled size={16} /> : undefined}
                  >
                    Start Watch Party
                  </Button>
                  <Button
                    size="md"
                    className={styles.glassBtn}
                    onClick={() => history.push(`/join/${room.roomId.replace(/^\//, "")}`)}
                    leftSection={<IconPlayerPlay size={16} />}
                  >
                    Pre-Flight Lobby
                  </Button>
                </>
              )}
              {isScheduled && (
                <>
                  <Button
                    size="md"
                    className={styles.primaryOpenBtn}
                    onClick={() => history.push(urlPath)}
                    leftSection={<IconPlayerPlay size={16} />}
                  >
                    Join Waiting Room
                  </Button>
                  <Button
                    size="sm"
                    variant="subtle"
                    color="violet"
                    onClick={handleStartRoom}
                    loading={isStarting}
                  >
                    Start Early
                  </Button>
                  <Button
                    size="sm"
                    variant="subtle"
                    color="red"
                    onClick={() => setCancelConfirm(true)}
                  >
                    Cancel
                  </Button>
                </>
              )}
              {!isClosed && !isActiveOrStarted && (
                <Button
                  size="md"
                  className={styles.glassBtn}
                  onClick={() => setEditModalOpened(true)}
                  leftSection={<IconSettings size={16} />}
                >
                  Edit
                </Button>
              )}
              {!isClosed && (
                <Button
                  size="md"
                  className={styles.glassBtn}
                  onClick={handleCopyUrl}
                  leftSection={copiedUrl ? <IconCheck size={16} color="#10B981" /> : <IconCopy size={16} />}
                >
                  {copiedUrl ? "Copied!" : "Copy Link"}
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* QUICK STATS ROW */}
      <div className={styles.statsRow}>
        <div className={styles.statCard}>
          <div className={styles.statIconWrap} style={{ backgroundColor: "rgba(16, 185, 129, 0.12)" }}>
            <IconActivity size={22} color="#10B981" />
          </div>
          <div className={styles.statInfo}>
            <span className={styles.statLabel}>Room Status</span>
            <span className={styles.statValue}>{statusConfig.label}</span>
            <span className={styles.statSubtitle}>{statusConfig.description}</span>
          </div>
        </div>

        <div className={styles.statCard}>
          <div className={styles.statIconWrap} style={{ backgroundColor: "rgba(139, 92, 246, 0.12)" }}>
            <IconUsers size={22} color="#8B5CF6" />
          </div>
          <div className={styles.statInfo}>
            <span className={styles.statLabel}>Viewers</span>
            <span className={styles.statValue}>{room.status === "active" ? "Watching Now" : "0"}</span>
            <span className={styles.statSubtitle}>
              {room.status === "active" ? "People in the room" : "No one watching yet"}
            </span>
          </div>
        </div>

        <div className={styles.statCard}>
          <div
            className={styles.statIconWrap}
            style={{
              backgroundColor: room.isPermanent ? "rgba(20, 184, 166, 0.12)" : "rgba(245, 158, 11, 0.12)",
            }}
          >
            {room.isPermanent ? <IconInfinity size={22} color="#14B8A6" /> : <IconClock size={22} color="#F59E0B" />}
          </div>
          <div className={styles.statInfo}>
            <span className={styles.statLabel}>Room Expiry</span>
            <span className={styles.statValue}>
              {room.isPermanent
                ? "Never Expires"
                : room.status === "waiting"
                  ? (room.durationMinutes ? `${room.durationMinutes}m session` : "Not started")
                  : room.status === "expired" || expiresInText === "Expired"
                    ? "Expired"
                    : room.status === "ended"
                      ? "Ended"
                      : expiresInText || "Temporary"}
            </span>
            <span className={styles.statSubtitle}>
              {room.isPermanent
                ? "Saved forever"
                : room.status === "waiting"
                  ? "Timer begins on start"
                  : room.status === "expired" || expiresInText === "Expired" || room.status === "ended"
                    ? "Room is closed"
                    : "Temporary room"}
            </span>
          </div>
        </div>

        <div className={styles.statCard}>
          <div className={styles.statIconWrap} style={{ backgroundColor: "rgba(236, 72, 153, 0.12)" }}>
            <IconMessage size={22} color="#EC4899" />
          </div>
          <div className={styles.statInfo}>
            <span className={styles.statLabel}>Chat</span>
            <span className={styles.statValue}>{room.chatSummary ? room.chatSummary.messagesCount : 0} Messages</span>
            <span className={styles.statSubtitle}>
              {room.chatSummary?.lastMessageAt
                ? `Last message: ${new Date(room.chatSummary.lastMessageAt).toLocaleDateString()}`
                : "No messages yet"}
            </span>
          </div>
        </div>
      </div>

      {/* BENTO CONTENT GRID */}
      <div className={styles.bentoGrid}>
        {/* LEFT COLUMN: DETAILS & SETTINGS */}
        <div>
          {/* Card 1: Room Details */}
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <div className={styles.cardTitle}>
                <div className={styles.cardTitleIconWrap}>
                  <IconInfoCircle size={18} />
                </div>
                <span>Room Details</span>
              </div>
            </div>

            <div className={styles.tileGrid}>
              <div className={styles.tile}>
                <span className={styles.tileLabel}>Room ID</span>
                <div className={styles.tileValue}>
                  <span className={styles.codeBadge}>{room.roomId}</span>
                  {!isClosed && (
                    <Tooltip label={copiedRoomId ? "Copied!" : "Copy room ID"} withArrow>
                      <ActionIcon
                        size="xs"
                        variant="subtle"
                        color={copiedRoomId ? "green" : "gray"}
                        onClick={handleCopyRoomId}
                        aria-label="Copy Room ID"
                      >
                        {copiedRoomId ? <IconCheck size={14} /> : <IconCopy size={14} />}
                      </ActionIcon>
                    </Tooltip>
                  )}
                </div>
              </div>

              <div className={styles.tile}>
                <span className={styles.tileLabel}>
                  <IconCalendar size={13} />
                  Created
                </span>
                <span className={styles.tileValue}>
                  {new Date(room.creationTime).toLocaleString(undefined, {
                    month: "short",
                    day: "numeric",
                    year: "numeric",
                    hour: "numeric",
                    minute: "2-digit",
                  })}
                </span>
              </div>

              <div className={styles.tile}>
                <span className={styles.tileLabel}>
                  <IconLock size={13} />
                  Password
                </span>
                <div className={styles.tileValue}>
                  {isClosed ? (
                    <Badge
                      color="gray"
                      variant="light"
                      size="md"
                      radius="md"
                      leftSection={<IconLock size={13} />}
                      style={{ fontWeight: 600 }}
                    >
                      Room Closed
                    </Badge>
                  ) : room.isPasscodeProtected ? (
                    currentPasscode ? (
                      <Group gap={6} align="center">
                        <span
                          style={{
                            fontFamily: showPassword ? "inherit" : "monospace",
                            letterSpacing: showPassword ? "normal" : "2px",
                            fontWeight: 700,
                          }}
                        >
                          {showPassword ? currentPasscode : "••••••••"}
                        </span>
                        <Tooltip label={showPassword ? "Hide password" : "Show password"} withArrow>
                          <ActionIcon
                            size="xs"
                            variant="subtle"
                            color="gray"
                            onClick={() => setShowPassword(!showPassword)}
                            aria-label="Toggle password visibility"
                          >
                            {showPassword ? <IconEyeOff size={14} /> : <IconEye size={14} />}
                          </ActionIcon>
                        </Tooltip>
                        <Tooltip label={copiedPassword ? "Copied!" : "Copy password"} withArrow>
                          <ActionIcon
                            size="xs"
                            variant="subtle"
                            color={copiedPassword ? "green" : "gray"}
                            onClick={handleCopyPassword}
                            aria-label="Copy password"
                          >
                            {copiedPassword ? <IconCheck size={14} /> : <IconCopy size={14} />}
                          </ActionIcon>
                        </Tooltip>
                        <Badge
                          color="violet"
                          variant="light"
                          size="md"
                          radius="md"
                          style={{ fontWeight: 600, border: "1px solid rgba(139, 92, 246, 0.25)" }}
                        >
                          Password Protected
                        </Badge>
                      </Group>
                    ) : (
                      <Badge
                        color="violet"
                        variant="light"
                        size="md"
                        radius="md"
                        leftSection={<IconLock size={13} />}
                        style={{ fontWeight: 600, border: "1px solid rgba(139, 92, 246, 0.25)" }}
                      >
                        Password Protected
                      </Badge>
                    )
                  ) : (
                    <Badge
                      color="gray"
                      variant="light"
                      size="md"
                      radius="md"
                      leftSection={<IconLockOpen size={13} />}
                      style={{ fontWeight: 600 }}
                    >
                      No Password Needed
                    </Badge>
                  )}
                </div>
              </div>

              <div className={styles.tile}>
                <span className={styles.tileLabel}>Room Type</span>
                <div className={styles.tileValue}>
                  <Badge
                    color={room.isPermanent ? "teal" : "blue"}
                    variant="light"
                    size="md"
                    radius="md"
                    style={{
                      fontWeight: 600,
                      border: room.isPermanent
                        ? "1px solid rgba(20, 184, 166, 0.25)"
                        : "1px solid rgba(59, 130, 246, 0.25)",
                    }}
                  >
                    {room.isPermanent ? "Permanent Room" : "Temporary Room"}
                  </Badge>
                  {room.isSubRoom && (
                    <Badge color="gray" variant="outline" size="md" radius="md" style={{ fontWeight: 600 }}>
                      Sub-Room
                    </Badge>
                  )}
                </div>
              </div>

              <div className={styles.tile} style={{ gridColumn: "1 / -1" }}>
                <span className={styles.tileLabel}>Invite Link</span>
                <div className={styles.tileValue}>
                  {isClosed ? (
                    <Group gap="xs" align="center">
                      <span style={{ color: "var(--text-muted)", textDecoration: "line-through", fontSize: 13 }}>
                        {window.location.origin}{urlPath}
                      </span>
                      <Badge color="red" variant="light" size="sm">
                        Link Inactive (Expired)
                      </Badge>
                    </Group>
                  ) : (
                    <a
                      href={urlPath}
                      onClick={(e) => {
                        e.preventDefault();
                        history.push(urlPath);
                      }}
                      style={{
                        color: "var(--color-violet)",
                        display: "inline-flex",
                        alignItems: "center",
                        gap: "6px",
                        textDecoration: "underline",
                        fontWeight: 600,
                      }}
                    >
                      {window.location.origin}{urlPath}
                      <IconExternalLink size={14} />
                    </a>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Card 2: Settings */}
          <div className={styles.card} style={isClosed ? { opacity: 0.75 } : undefined}>
            <div className={styles.cardHeader}>
              <div className={styles.cardTitle}>
                <div className={styles.cardTitleIconWrap}>
                  <IconSettings size={18} />
                </div>
                <span>Room Settings</span>
              </div>
              {!isClosed && !isActiveOrStarted && (
                <Button
                  variant="subtle"
                  size="xs"
                  color="violet"
                  onClick={() => setEditModalOpened(true)}
                  leftSection={<IconSettings size={14} />}
                >
                  Edit
                </Button>
              )}
              {isActiveOrStarted && !isClosed && (
                <Badge color="violet" variant="light" size="sm">
                  Locked (Active Session)
                </Badge>
              )}
            </div>

            <div className={styles.tileGrid}>
              <div className={styles.tile}>
                <span className={styles.tileLabel}>Live Chat</span>
                <div className={styles.tileValue}>
                  <Badge
                    color={isClosed ? "gray" : room.isChatDisabled ? "gray" : "green"}
                    variant="light"
                    size="md"
                    radius="md"
                    style={{
                      fontWeight: 600,
                      border: isClosed
                        ? "1px solid rgba(156, 163, 175, 0.25)"
                        : room.isChatDisabled
                          ? "1px solid rgba(156, 163, 175, 0.25)"
                          : "1px solid rgba(16, 185, 129, 0.25)",
                    }}
                  >
                    {isClosed ? "Disabled" : room.isChatDisabled ? "Turned Off" : "Turned On"}
                  </Badge>
                </div>
              </div>

              <div className={styles.tile}>
                <span className={styles.tileLabel}>Video Controls</span>
                <div className={styles.tileValue}>
                  <Badge
                    color={isClosed ? "gray" : "violet"}
                    variant="light"
                    size="md"
                    radius="md"
                    leftSection={<IconShieldCheck size={13} />}
                    style={{ fontWeight: 600, border: isClosed ? "1px solid rgba(156, 163, 175, 0.25)" : "1px solid rgba(139, 92, 246, 0.25)" }}
                  >
                    {isClosed ? "Disabled" : "Host Only"}
                  </Badge>
                </div>
              </div>

              <div className={styles.tile} style={{ gridColumn: "1 / -1" }}>
                <span className={styles.tileLabel}>Description</span>
                <div className={styles.tileValue}>
                  {room.roomDescription ? (
                    <Text size="sm" c="var(--text-secondary)" style={{ fontStyle: "italic" }}>
                      "{room.roomDescription}"
                    </Text>
                  ) : (
                    <Text size="sm" c="dimmed">
                      {isActiveOrStarted ? "No description provided." : 'No description added yet. Click "Edit" to add one.'}
                    </Text>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* Card 3: Danger Zone */}
          <div className={styles.dangerCard}>
            <div className={styles.dangerInfo}>
              <div className={styles.dangerTitle}>
                <IconAlertTriangle size={16} />
                <span>Room Management</span>
              </div>
              <div className={styles.dangerDesc}>
                End the room now or permanently delete it.
              </div>
            </div>
            <Group gap="xs">
              {room.status !== "ended" && room.status !== "expired" && (
                <Button
                  color="orange"
                  variant="light"
                  onClick={() => setEndConfirm(true)}
                  loading={isEnding}
                  leftSection={<IconPlayerStop size={15} />}
                >
                  End Room
                </Button>
              )}
              <Button
                color="red"
                variant="outline"
                onClick={() => setDeleteConfirm(true)}
                leftSection={<IconTrash size={15} />}
              >
                Delete Room
              </Button>
            </Group>
          </div>
        </div>

        {/* RIGHT COLUMN: STATUS & RECENT ACTIVITY */}
        <div>
          {/* Card 4: Status & Timing */}
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <div className={styles.cardTitle}>
                <div className={styles.cardTitleIconWrap}>
                  <IconClock size={18} />
                </div>
                <span>Status & Timing</span>
              </div>
              <Badge color={statusConfig.badgeColor} variant="light" size="sm">
                {statusConfig.label}
              </Badge>
            </div>

            <div
              className={`${styles.lifecycleBanner} ${room.isPermanent
                  ? styles.permanent
                  : room.status === "active"
                    ? styles.active
                    : room.status === "expired" || room.status === "ended"
                      ? styles.ended
                      : styles.inactive
                }`}
            >
              <div>
                <Text fw={700} size="sm" c="var(--text-primary)">
                  {room.isPermanent
                    ? "Permanent Room"
                    : room.status === "waiting"
                      ? "Waiting to Start"
                      : room.status === "active"
                        ? "Party in Progress"
                        : room.status === "expired"
                          ? "Room Expired"
                          : room.status === "ended"
                            ? "Room Ended"
                            : "Room is Paused"}
                </Text>
                <Text size="xs" c="var(--text-secondary)" mt={4} style={{ lineHeight: 1.5 }}>
                  {room.isPermanent
                    ? "This room is saved forever. You and your friends can come back and watch together anytime."
                    : room.status === "waiting"
                      ? "This watch party is ready. The countdown timer starts as soon as the host begins."
                      : room.status === "active"
                        ? "People are currently in this room watching together."
                        : room.status === "expired"
                          ? "This temporary room has reached its end of life and is now closed."
                          : room.status === "ended"
                            ? "This watch party has been ended by the host."
                            : "Nobody is in the room right now. It automatically wakes up as soon as someone joins."}
                </Text>
              </div>
            </div>

            {(room.status === "active" || room.status === "expiring") && !room.isPermanent && room.expiresAt && expiresInText !== "Expired" && (
              <div style={{ marginBottom: "20px" }}>
                <div className={styles.countdownBig}>
                  {expiresInText || "—"}
                </div>
                <div className={styles.countdownLabel}>Time left until room closes</div>
              </div>
            )}

            <div className={styles.tileGrid} style={{ gridTemplateColumns: "1fr" }}>
              <div className={styles.tile}>
                <span className={styles.tileLabel}>Last Used</span>
                <span className={styles.tileValue}>
                  {room.lifecycleEvents && room.lifecycleEvents.length > 0
                    ? new Date(room.lifecycleEvents[0].timestamp).toLocaleString(undefined, {
                      month: "short",
                      day: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    })
                    : "Never used yet"}
                </span>
              </div>

              <div className={styles.tile}>
                <span className={styles.tileLabel}>Auto-Start</span>
                <span className={styles.tileValue}>
                  {isClosed ? "Disabled (Room closed)" : "Starts when someone joins"}
                </span>
              </div>
            </div>
          </div>

          {/* Card 5: Room Chat & Activity History */}
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <div className={styles.cardTitle}>
                <div className={styles.cardTitleIconWrap}>
                  {activeHistoryTab === "chat" ? <IconMessage size={18} /> : <IconActivity size={18} />}
                </div>
                <span>{activeHistoryTab === "chat" ? "Room Chat" : "Activity History"}</span>
              </div>
              <SegmentedControl
                value={activeHistoryTab}
                onChange={(val) => setActiveHistoryTab(val as "chat" | "activity")}
                size="xs"
                radius="md"
                data={[
                  {
                    label: `Chat (${room.chatMessages?.length ?? room.chatSummary?.messagesCount ?? 0})`,
                    value: "chat",
                  },
                  {
                    label: `Activity (${room.lifecycleEvents?.length ?? 0})`,
                    value: "activity",
                  },
                ]}
              />
            </div>

            {activeHistoryTab === "chat" ? (
              room.chatMessages && room.chatMessages.length > 0 ? (
                <ScrollArea.Autosize mah={360} type="auto">
                  <div className={styles.chatList}>
                    {room.chatMessages.map((msg) => (
                      <div key={msg.id} className={styles.chatItem}>
                        <Avatar
                          src={msg.authorAvatar}
                          alt={msg.authorName || "Guest"}
                          radius="xl"
                          size="sm"
                          color="violet"
                        >
                          {(msg.authorName || "G").charAt(0).toUpperCase()}
                        </Avatar>
                        <div className={styles.chatContent}>
                          <div className={styles.chatHeaderRow}>
                            <span className={styles.chatAuthor}>{msg.authorName || "Guest"}</span>
                            <span className={styles.chatTime}>
                              {new Date(msg.created_at).toLocaleTimeString(undefined, {
                                hour: "2-digit",
                                minute: "2-digit",
                              })}
                            </span>
                          </div>
                          <div className={styles.chatMessageText}>{msg.message}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea.Autosize>
              ) : (
                <div className={styles.emptyStateContainer}>
                  <div className={styles.emptyStateIconWrap}>
                    <IconMessage size={22} color="var(--color-violet)" />
                  </div>
                  <Text fw={600} size="sm" c="var(--text-primary)">
                    No Messages Yet
                  </Text>
                  <Text size="xs" c="dimmed" ta="center" style={{ maxWidth: 260 }}>
                    Chats sent during watch parties in this room will appear here.
                  </Text>
                </div>
              )
            ) : (
              room.lifecycleEvents && room.lifecycleEvents.length > 0 ? (
                <div className={styles.timeline}>
                  {room.lifecycleEvents.slice(0, 10).map((event, index) => (
                    <div key={event.id || index} className={styles.timelineItem}>
                      {index < Math.min(room.lifecycleEvents.length, 10) - 1 && (
                        <div className={styles.timelineLine} />
                      )}
                      <div className={styles.timelineNode}>
                        <div
                          style={{
                            width: 8,
                            height: 8,
                            borderRadius: "50%",
                            backgroundColor: "var(--color-violet)",
                          }}
                        />
                      </div>
                      <div className={styles.timelineBody}>
                        <div className={styles.timelineTitle}>{event.event}</div>
                        <div className={styles.timelineTime}>
                          {new Date(event.timestamp).toLocaleString(undefined, {
                            month: "short",
                            day: "numeric",
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className={styles.emptyStateContainer}>
                  <div className={styles.emptyStateIconWrap}>
                    <IconActivity size={22} color="var(--color-violet)" />
                  </div>
                  <Text fw={600} size="sm" c="var(--text-primary)">
                    No Activity Recorded
                  </Text>
                  <Text size="xs" c="dimmed" ta="center" style={{ maxWidth: 260 }}>
                    Room events, status changes, and participant activity will appear here.
                  </Text>
                </div>
              )
            )}
          </div>
        </div>
      </div>

      {/* CANCEL CONFIRMATION MODAL */}
      <Modal opened={cancelConfirm} onClose={() => setCancelConfirm(false)} title="Cancel Watch Party" centered>
        <Text size="sm" mb="lg">
          Are you sure you want to cancel this scheduled room? This cannot be undone, and the room will become inaccessible.
        </Text>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setCancelConfirm(false)}>Keep Room</Button>
          <Button color="red" onClick={confirmCancelRoom} loading={isCancelling}>Cancel Room</Button>
        </Group>
      </Modal>

      {/* DELETE CONFIRMATION MODAL */}
      <Modal opened={deleteConfirm} onClose={() => setDeleteConfirm(false)} title="Delete Room" centered>
        <Text size="sm" mb="lg">
          Are you sure you want to delete <strong>{room.roomTitle || room.roomId}</strong> forever? You will not be able to get it back.
        </Text>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setDeleteConfirm(false)}>
            Keep Room
          </Button>
          <Button color="red" onClick={handleDelete} loading={isDeleting}>
            Delete Room
          </Button>
        </Group>
      </Modal>

      {/* END CONFIRMATION MODAL */}
      <Modal opened={endConfirm} onClose={() => setEndConfirm(false)} title="End Watch Party" centered>
        <Text size="sm" mb="lg">
          Are you sure you want to end <strong>{room.roomTitle || room.roomId}</strong>? Guests will no longer be able to watch or join this room.
        </Text>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setEndConfirm(false)}>
            Cancel
          </Button>
          <Button color="orange" onClick={confirmEndRoom} loading={isEnding}>
            End Room
          </Button>
        </Group>
      </Modal>

      {/* START ROOM CONFIRMATION MODAL (Before entering room) */}
      <Modal
        opened={startConfirm}
        onClose={() => setStartConfirm(false)}
        title="Start Watch Party"
        centered
      >
        <Stack gap="sm" mb="lg">
          <Text size="sm">
            You are about to start <strong>{room.roomTitle || room.roomId}</strong>.
          </Text>
          <div
            style={{
              padding: "12px 14px",
              borderRadius: "10px",
              backgroundColor: "rgba(139, 92, 246, 0.08)",
              border: "1px solid rgba(139, 92, 246, 0.25)",
              display: "flex",
              flexDirection: "column",
              gap: "4px",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: "8px", fontWeight: 600, fontSize: "14px", color: "var(--text-primary)" }}>
              <IconClock size={16} color="var(--color-violet)" />
              <span>
                {room.isPermanent
                  ? "Permanent Room (no expiration)"
                  : `Session Duration: ${formatDuration(room.durationMinutes) || "5 hours"}`}
              </span>
            </div>
            {!room.isPermanent && (
              <Text size="xs" c="dimmed">
                The countdown begins when you start the watch party.
              </Text>
            )}
          </div>
        </Stack>
        <Group justify="flex-end">
          <Button variant="default" onClick={() => setStartConfirm(false)}>
            Cancel
          </Button>
          <Button
            color="violet"
            onClick={handleStartRoom}
            loading={isStarting}
            leftSection={<IconPlayerPlayFilled size={15} />}
          >
            Start Watch Party
          </Button>
        </Group>
      </Modal>

      {/* NOTICE / ERROR MODAL */}
      <Modal opened={Boolean(actionError)} onClose={() => setActionError(null)} title="Notice" centered>
        <Text size="sm" mb="lg">
          {actionError}
        </Text>
        <Group justify="flex-end">
          <Button onClick={() => setActionError(null)} color="violet">
            OK
          </Button>
        </Group>
      </Modal>

      {/* EDIT ROOM MODAL */}
      <EditRoomModal
        room={{
          roomId: room.roomId,
          creationTime: room.creationTime,
          roomTitle: room.roomTitle,
          roomDescription: room.roomDescription,
          coverPhoto: room.coverPhoto,
          isChatDisabled: room.isChatDisabled,
          isPasscodeProtected: room.isPasscodeProtected,
          currentPasscode: room.currentPasscode,
          isSubRoom: room.isSubRoom,
          status: room.status,
          startedAt: room.startedAt,
          endedAt: room.endedAt,
          expiresAt: room.expiresAt,
          isPermanent: room.isPermanent,
        }}
        opened={editModalOpened}
        onClose={() => setEditModalOpened(false)}
        onSuccess={fetchRoomDetails}
      />
    </div>
  );
};

import React from "react";
import { ActionIcon } from "@mantine/core";
import { IconChevronLeft, IconChevronRight } from "@tabler/icons-react";
import styles from "./MyRooms.module.css";

export const RoomPagination = ({
  currentPage,
  pageSize,
  totalItems,
  onPageChange
}: {
  currentPage: number;
  pageSize: number;
  totalItems: number;
  onPageChange: (page: number) => void;
}) => {
  if (totalItems <= pageSize) {
    return null;
  }

  const totalPages = Math.ceil(totalItems / pageSize);
  const startItem = (currentPage - 1) * pageSize + 1;
  const endItem = Math.min(currentPage * pageSize, totalItems);

  return (
    <div className={styles.pagination}>
      <div style={{ display: 'flex', gap: '8px', background: 'var(--bg-surface)', padding: '4px', borderRadius: '8px', border: '1px solid var(--border-subtle)' }}>
        <ActionIcon 
          variant="subtle" 
          disabled={currentPage === 1}
          onClick={() => onPageChange(currentPage - 1)}
        >
          <IconChevronLeft size={16} />
        </ActionIcon>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minWidth: '32px', background: 'var(--color-violet)', color: 'white', borderRadius: '4px', fontSize: '14px', fontWeight: 600 }}>
          {currentPage}
        </div>
        <ActionIcon 
          variant="subtle" 
          disabled={currentPage === totalPages}
          onClick={() => onPageChange(currentPage + 1)}
        >
          <IconChevronRight size={16} />
        </ActionIcon>
      </div>
      <div className={styles.paginationText}>
        Showing {startItem} of {totalItems} rooms
      </div>
    </div>
  );
};

import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import { Button, Text, Loader, ActionIcon } from "@mantine/core";
import { IconCopy, IconPlayerStop, IconHistory, IconSettings, IconMessage, IconUsers } from "@tabler/icons-react";
import { calculateRoomDuration, serverPath } from "../../utils/utils";
import styles from "./RoomPostMortem.module.css";
import { RoomDetailsData } from "./RoomDetails";

interface RoomPostMortemProps {
  room: RoomDetailsData;
}

export function RoomPostMortem({ room }: RoomPostMortemProps) {
  const history = useHistory();
  const [duplicating, setDuplicating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleDuplicate = async () => {
    setDuplicating(true);
    setError(null);
    try {
      const res = await fetch(`${serverPath}/api/room/duplicate`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sourceRoomId: room.roomId }),
      });
      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || "Failed to duplicate room");
      }
      history.push(`/myrooms/${data.roomId}`);
    } catch (err: any) {
      console.error(err);
      setError(err.message);
    } finally {
      setDuplicating(false);
    }
  };

  const getVisibilityText = () => {
    if (room.isPasscodeProtected) return "Private (Passcode Protected)";
    return "Public";
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <div className={styles.label}>Room History</div>
        <div className={styles.title}>{room.roomTitle}</div>
        <div className={styles.hostedOn}>
          Hosted on {new Date(room.creationTime).toLocaleDateString([], { month: "long", day: "numeric", year: "numeric" })}
        </div>

        <div className={styles.statusEnded}>
          ● {room.status.toUpperCase()}
        </div>
      </div>

      <div className={styles.statsGrid}>
        <div className={styles.statCard}>
          <span className={styles.statLabel}>Started</span>
          <span className={styles.statValue}>
            {room.startedAt ? new Date(room.startedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "—"}
          </span>
        </div>
        <div className={styles.statCard}>
          <span className={styles.statLabel}>Ended</span>
          <span className={styles.statValue}>
            {(room.endedAt || room.expiresAt) ? new Date((room.endedAt || room.expiresAt)!).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : "—"}
          </span>
        </div>
        <div className={styles.statCard}>
          <span className={styles.statLabel}>Duration</span>
          <span className={styles.statValue}>
            {calculateRoomDuration(room.startedAt, room.endedAt, room.expiresAt)}
          </span>
        </div>
        <div className={styles.statCard}>
          <span className={styles.statLabel}>Chat Messages</span>
          <span className={styles.statValue}>
            {room.chatSummary?.messagesCount ?? 0}
          </span>
        </div>
      </div>

      <div className={styles.settingsSection}>
        <div className={styles.settingsHeader}>
          <IconSettings size={18} /> Historical Settings
        </div>

        <div className={styles.settingsRow}>
          <span className={styles.settingsRowLabel}>Description</span>
          <span className={styles.settingsRowValue}>{room.roomDescription || "—"}</span>
        </div>

        <div className={styles.settingsRow}>
          <span className={styles.settingsRowLabel}>Visibility</span>
          <span className={styles.settingsRowValue}>{getVisibilityText()}</span>
        </div>

        <div className={styles.settingsRow}>
          <span className={styles.settingsRowLabel}>Chat</span>
          <span className={styles.settingsRowValue}>{room.isChatDisabled ? "Disabled" : "Enabled"}</span>
        </div>
      </div>

      <div className={styles.primaryAction}>
        {error && <Text c="red" size="sm" mb="sm" ta="center">{error}</Text>}
        <Button 
          onClick={handleDuplicate} 
          loading={duplicating}
          size="lg" 
          fullWidth 
          color="violet"
          leftSection={<IconCopy size={20} />}
        >
          Host Again
        </Button>
      </div>
    </div>
  );
}

import React, { useContext, useEffect, useState } from "react";
import { Modal, Button, Avatar, Switch, Text, TextInput, SegmentedControl } from "@mantine/core";
