interface SettingsModalProps {
  modalOpen: boolean;
  setModalOpen: (open: boolean) => void;
  isRoomActive?: boolean;
  roomLock: string;
  setRoomLock: (lock: boolean) => Promise<void>;
  socket: Socket;
  roomId: string;
  owner: string | undefined;
  setOwner: (owner: string) => void;
  inviteLink: string;
  passcode: string | undefined;
  setPasscode: (passcode: string) => void;
  isChatDisabled: boolean;
  setIsChatDisabled: (disabled: boolean) => void;
  clearChat: () => void;
  roomTitle: string;
  setRoomTitle: (title: string) => void;
  roomDescription: string | undefined;
  setRoomDescription: (desc: string) => void;
  mediaPath: string | undefined;
  setMediaPath: (path: string) => void;
  isWaitingLoungeEnabled?: boolean;
  setIsWaitingLoungeEnabled?: (enabled: boolean) => void;
}

export const SettingsModal = ({
  modalOpen,
  setModalOpen,
  isRoomActive = false,
  roomLock,
  setRoomLock,
  socket,
  owner,
  roomId,
  passcode,
  setPasscode,
  isChatDisabled,
  setIsChatDisabled,
  clearChat,
  roomTitle,
  setRoomTitle,
  roomDescription,
  setRoomDescription,
  isWaitingLoungeEnabled,
  setIsWaitingLoungeEnabled,
}: SettingsModalProps) => {
  const { user, profile } = useContext(MetadataContext);
  
  // -- DRAFT STATE --
  const [draftTitle, setDraftTitle] = useState(roomTitle || "");
  const [draftDescription, setDraftDescription] = useState(roomDescription || "");
  const [draftLock, setDraftLock] = useState(Boolean(roomLock));
  const [draftPermanent, setDraftPermanent] = useState(false);
  const [draftChatEnabled, setDraftChatEnabled] = useState(!isChatDisabled);
  const [draftWaitingLounge, setDraftWaitingLounge] = useState(Boolean(isWaitingLoungeEnabled));
  
  // Local settings draft
  const [draftNotif, setDraftNotif] = useState(Boolean(getCurrentSettings().disableChatSound));
  const [draftCamera, setDraftCamera] = useState(profile?.pref_camera_on ?? false);
  const [draftMic, setDraftMic] = useState(profile?.pref_mic_on ?? false);
  
  // Password draft
  const [passwordAction, setPasswordAction] = useState<"keep" | "change" | "clear">("keep");
  const [draftPassword, setDraftPassword] = useState("");
  const [draftPasswordConfirm, setDraftPasswordConfirm] = useState("");

  // Cover draft
  const [originalCoverUrl, setOriginalCoverUrl] = useState<string | null>(null);
  const [coverFile, setCoverFile] = useState<File | null>(null);
  const [coverPreview, setCoverPreview] = useState<string | null>(null);
  const [clearCover, setClearCover] = useState(false);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  // Sync draft from props/DB when modal opens
  useEffect(() => {
    if (modalOpen) {
      setDraftTitle(roomTitle || "");
      setDraftDescription(roomDescription || "");
      setDraftLock(Boolean(roomLock));
      setDraftChatEnabled(!isChatDisabled);
      setDraftWaitingLounge(Boolean(isWaitingLoungeEnabled));
      
      setDraftNotif(Boolean(getCurrentSettings().disableChatSound));
      setDraftCamera(profile?.pref_camera_on ?? false);
      setDraftMic(profile?.pref_mic_on ?? false);

      setPasswordAction("keep");
      setDraftPassword("");
      setDraftPasswordConfirm("");
      setShowCurrentPassword(false);
      setCopiedCurrentPassword(false);
      
      setCoverFile(null);
      setClearCover(false);
      setError("");

      // Fetch current permanent status & cover
      const fetchRoomData = async () => {
        const { data } = await supabase
          .from("rooms")
          .select("isPermanent, isSubRoom, expiresAt, coverPhoto")
          .eq("roomId", roomId)
          .single();
        if (data) {
          const isPerm = Boolean(data.isPermanent);
          setDraftPermanent(isPerm);
          setOriginalCoverUrl(data.coverPhoto);
          setCoverPreview(data.coverPhoto);
        }
      };
      void fetchRoomData();
    }
  }, [modalOpen, roomTitle, roomDescription, roomLock, isChatDisabled, isWaitingLoungeEnabled, profile, roomId]);

  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [copiedCurrentPassword, setCopiedCurrentPassword] = useState(false);

  const cleanRoomId = roomId.startsWith("/") ? roomId.substring(1) : roomId;
  const currentSavedPasscode =
    (passcode && passcode !== "true" ? passcode : "") ||
    getSavedPasscodes()[roomId] ||
    getSavedPasscodes()[cleanRoomId] ||
    getSavedPasscodes()[`/${cleanRoomId}`] ||
    "";

  const handleFileChange = (payload: File | null) => {
    if (payload) {
      if (payload.size > 1 * 1024 * 1024) {
        setError("Cover photo too large (max 1MB).");
        return;
      }
      setCoverFile(payload);
      setCoverPreview(URL.createObjectURL(payload));
    }
  };

  const handleSave = async () => {
    setIsLoading(true);
    setError("");

    try {
      const token = await getAccessToken();
      if (!user) throw new Error("Not logged in");

      if (!isRoomActive) {
        const trimmedTitle = draftTitle.trim();
        if (!trimmedTitle) throw new Error("Room title is required.");
        if (trimmedTitle.length > 50) throw new Error("Room title must be under 50 characters.");
        if (draftDescription.length > 500) throw new Error("Description must be under 500 characters.");
        if (passwordAction === "change" && draftPassword !== draftPasswordConfirm) throw new Error("Passwords do not match.");
        if (passwordAction === "change" && draftPassword.trim().length === 0) throw new Error("Password cannot be empty.");

        // 1. Upload new cover if selected
        let finalCoverUrl = originalCoverUrl;
        const safeRoomId = roomId.startsWith("/") ? roomId.substring(1) : roomId;
        const folderPath = `${user.id}/${safeRoomId}`;

        if (coverFile) {
          const fileExt = coverFile.name.split('.').pop();

          // Clean up old cover files in folder to prevent orphans
          try {
            const { data: oldFiles } = await supabase.storage.from('room_covers').list(folderPath);
            if (oldFiles && oldFiles.length > 0) {
              await supabase.storage.from('room_covers').remove(oldFiles.map(f => `${folderPath}/${f.name}`));
            }
          } catch (_) {}

          const filePath = `${folderPath}/cover.${fileExt}`;
          
          const { error: uploadError } = await supabase.storage
            .from('room_covers')
            .upload(filePath, coverFile, { upsert: true });
          
          if (uploadError) throw uploadError;
          
          const { data: publicUrlData } = supabase.storage.from('room_covers').getPublicUrl(filePath);
          finalCoverUrl = `${publicUrlData.publicUrl}?t=${Date.now()}`;
        } else if (clearCover) {
          finalCoverUrl = null;
          try {
            const { data: oldFiles } = await supabase.storage.from('room_covers').list(folderPath);
            if (oldFiles && oldFiles.length > 0) {
              await supabase.storage.from('room_covers').remove(oldFiles.map(f => `${folderPath}/${f.name}`));
            }
          } catch (_) {}
        }

        if (finalCoverUrl !== originalCoverUrl) {
          await fetch(`${serverPath}/updateRoomCover`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ uid: user.id, token, roomId, coverPhoto: finalCoverUrl }),
          });
          
          const { error: coverUpdateError } = await supabase
            .from("rooms")
            .update({ coverPhoto: finalCoverUrl })
            .eq("roomId", roomId);
          if (coverUpdateError) throw coverUpdateError;
        }

        // 2. Save Room Settings (only if owner)
        if (owner === user.id) {
          const isClearing = passwordAction === "clear";
          const payloadPassword = passwordAction === "change" ? draftPassword.trim() : (isClearing ? "" : undefined);
          const response = await fetch(`${serverPath}/updateRoomSettings`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              uid: user.id,
              token,
              roomId,
              roomTitle: trimmedTitle,
              roomDescription: draftDescription,
              isPermanent: draftPermanent,
              isChatDisabled: !draftChatEnabled,
              removePassword: isClearing,
              password: payloadPassword,
            }),
          });

          const result = await response.json();
          if (!response.ok) throw new Error(result.error || "Failed to save room settings");

          // Inform server/socket of title and chat changes instantly
          if (trimmedTitle !== roomTitle) setRoomTitle(trimmedTitle);
          if (draftDescription !== roomDescription) setRoomDescription(draftDescription);
          if (!draftChatEnabled !== isChatDisabled) setIsChatDisabled(!draftChatEnabled);
          
          if (isClearing) {
            removeSavedPasscode(roomId);
            setPasscode("");
          } else if (passwordAction === "change") {
            addAndSavePasscode(roomId, draftPassword.trim());
            setPasscode(draftPassword.trim());
          }

          if (draftLock !== Boolean(roomLock)) {
            void setRoomLock(draftLock);
          }

          if (draftWaitingLounge !== Boolean(isWaitingLoungeEnabled)) {
            socket?.emit("CMD:setWaitingLounge", { enabled: draftWaitingLounge });
            if (setIsWaitingLoungeEnabled) {
              setIsWaitingLoungeEnabled(draftWaitingLounge);
            }
          }
        }
      }

      // 3. Save Local Settings
      updateSettings(
        JSON.stringify({
          ...getCurrentSettings(),
          disableChatSound: !draftNotif,
        })
      );
      
      const { error: prefError } = await supabase
        .from("profiles")
        .update({
          pref_camera_on: draftCamera,
          pref_mic_on: draftMic,
        })
        .eq("id", user.id);
      
      if (prefError) throw prefError;

      setModalOpen(false);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to save settings");
    } finally {
      setIsLoading(false);
    }
  };

  const hasPasscodeCurrently = Boolean(passcode);
  const willHavePasscode = passwordAction === "keep" ? hasPasscodeCurrently : passwordAction === "change";

  return (
    <Modal
      opened={modalOpen}
      onClose={() => setModalOpen(false)}
      centered
      title={isRoomActive ? "Personal Preferences" : "Settings"}
      radius="md"
      size={isRoomActive ? 520 : 850}
      styles={{
        content: {
          background: "var(--bg-surface)",
          border: "1px solid var(--border-subtle)",
          color: "var(--text-primary)",
          boxShadow: "var(--shadow-md)",
        },
        header: {
          background: "var(--bg-surface)",
          color: "var(--text-primary)",
          borderBottom: "1px solid var(--border-subtle)",
          padding: "20px 24px",
        },
        body: { padding: "0" },
        title: {
          fontWeight: 700,
          fontSize: "22px",
        }
      }}
    >
      <div style={{ padding: "24px 24px" }}>
        <Text size="sm" c="dimmed" mb="xl">
          {isRoomActive
            ? "Manage your personal preferences for this session"
            : "Manage your room and personal preferences"}
        </Text>

        {error && <Text color="red" size="sm" mb="md" fw={500}>{error}</Text>}

        {isRoomActive ? (
          <div>
            <Alert
              icon={<IconAlertCircle size={16} />}
              title="Room is Active"
              color="violet"
              variant="light"
              mb="xl"
              styles={{
                root: {
                  backgroundColor: "rgba(139, 92, 246, 0.08)",
                  borderColor: "rgba(139, 92, 246, 0.25)",
                },
              }}
            >
              Room configurations cannot be modified while the room is active. Room modifications are not allowed once a room is started.
            </Alert>

            <Text fw={700} size="sm" mb="md" c="dimmed" style={{ letterSpacing: "1px" }}>LOCAL PREFERENCES</Text>
            <Stack gap="xl">
              <Switch
                label="Chat Notifications"
                description="Play a sound for new messages."
                checked={draftNotif}
                onChange={(e) => setDraftNotif(e.currentTarget.checked)}
                size="md"
              />
              <Switch
                label="Camera Default"
                description="Join rooms with camera on."
                checked={draftCamera}
                onChange={(e) => setDraftCamera(e.currentTarget.checked)}
                size="md"
              />
              <Switch
                label="Microphone Default"
                description="Join rooms with microphone on."
                checked={draftMic}
                onChange={(e) => setDraftMic(e.currentTarget.checked)}
                size="md"
              />
            </Stack>
          </div>
        ) : (
          <SimpleGrid cols={{ base: 1, md: 2 }} spacing={40}>
            {/* LEFT COLUMN */}
            <div>
              <Text fw={700} size="sm" mb="md" c="dimmed" style={{ letterSpacing: "1px" }}>ROOM SETTINGS</Text>
              <Stack gap="xl">
                <Switch
                  label="Lock Room"
                  description="Only the person who locked the room can control playback."
                  checked={draftLock}
                  onChange={(e) => setDraftLock(e.currentTarget.checked)}
                  disabled={owner !== user?.id}
                  size="md"
                />
                <Switch
                  label="Permanent Room"
                  description="Room does not automatically expire."
                  checked={draftPermanent}
                  onChange={(e) => setDraftPermanent(e.currentTarget.checked)}
                  disabled={owner !== user?.id}
                  size="md"
                />
                <Switch
                  label="Chat Enabled"
                  description="Allow participants to send messages."
                  checked={draftChatEnabled}
                  onChange={(e) => setDraftChatEnabled(e.currentTarget.checked)}
                  disabled={owner !== user?.id}
                  size="md"
                />
                <Switch
                  label="Waiting Lounge"
                  description="Require host approval before guests can enter the room."
                  checked={draftWaitingLounge}
                  onChange={(e) => setDraftWaitingLounge(e.currentTarget.checked)}
                  disabled={owner !== user?.id}
                  size="md"
                />
              </Stack>

              <Divider my="xl" />

              <Text fw={700} size="sm" mb="md" c="dimmed" style={{ letterSpacing: "1px" }}>LOCAL SETTINGS</Text>
              <Stack gap="xl">
                <Switch
                  label="Chat Notifications"
                  description="Play a sound for new messages."
                  checked={draftNotif}
                  onChange={(e) => setDraftNotif(e.currentTarget.checked)}
                  size="md"
                />
                <Switch
                  label="Camera Default"
                  description="Join rooms with camera on."
                  checked={draftCamera}
                  onChange={(e) => setDraftCamera(e.currentTarget.checked)}
                  size="md"
                />
                <Switch
                  label="Microphone Default"
                  description="Join rooms with microphone on."
                  checked={draftMic}
                  onChange={(e) => setDraftMic(e.currentTarget.checked)}
                  size="md"
                />
              </Stack>
            </div>

            {/* RIGHT COLUMN */}
            <div>
              <Text fw={700} size="sm" mb="md" c="dimmed" style={{ letterSpacing: "1px" }}>ROOM DETAILS</Text>
              <Stack gap="md">
                <TextInput
                  label="Room Title"
                  value={draftTitle}
                  onChange={(e) => setDraftTitle(e.currentTarget.value)}
                  disabled={owner !== user?.id}
                />
                <TextInput
                  label="Description"
                  value={draftDescription}
                  onChange={(e) => setDraftDescription(e.currentTarget.value)}
                  placeholder="No description set"
                  disabled={owner !== user?.id}
                />

                <div>
                  <Text size="sm" fw={500} mb={4}>Password Protection</Text>
                  {passwordAction !== "change" ? (
                    <Stack gap="xs">
                      <Group justify="space-between" align="center">
                        <Group gap={6}>
                          <Badge
                            color={willHavePasscode ? "violet" : "gray"}
                            variant="light"
                            size="sm"
                            leftSection={willHavePasscode ? <IconLock size={12} /> : <IconLockOpen size={12} />}
                          >
                            {willHavePasscode ? "Protected" : "Unprotected"}
                          </Badge>
                        </Group>
                        <Group>
                          {willHavePasscode && (
                            <Button variant="subtle" color="red" size="xs" onClick={() => setPasswordAction("clear")} disabled={owner !== user?.id}>
                              Clear Password
                            </Button>
                          )}
                          <Button variant="light" size="xs" onClick={() => setPasswordAction("change")} disabled={owner !== user?.id}>
                            {willHavePasscode ? "Change Password" : "Set Password"}
                          </Button>
                        </Group>
                      </Group>

                      {willHavePasscode && currentSavedPasscode && (
                        <TextInput
                          readOnly
                          size="xs"
                          label="Current Password"
                          type={showCurrentPassword ? "text" : "password"}
                          value={currentSavedPasscode}
                          rightSection={
                            <Group gap={4} pr={4}>
                              <Tooltip label={showCurrentPassword ? "Hide password" : "Show password"} withArrow>
                                <ActionIcon
                                  size="xs"
                                  variant="subtle"
                                  color="gray"
                                  onClick={() => setShowCurrentPassword(!showCurrentPassword)}
                                  aria-label="Toggle password visibility"
                                >
                                  {showCurrentPassword ? <IconEyeOff size={14} /> : <IconEye size={14} />}
                                </ActionIcon>
                              </Tooltip>
                              <Tooltip label={copiedCurrentPassword ? "Copied!" : "Copy password"} withArrow>
                                <ActionIcon
                                  size="xs"
                                  variant="subtle"
                                  color={copiedCurrentPassword ? "green" : "gray"}
                                  onClick={() => {
                                    void navigator.clipboard.writeText(currentSavedPasscode);
                                    setCopiedCurrentPassword(true);
                                    setTimeout(() => setCopiedCurrentPassword(false), 2000);
                                  }}
                                  aria-label="Copy password"
                                >
                                  {copiedCurrentPassword ? <IconCheck size={14} /> : <IconCopy size={14} />}
                                </ActionIcon>
                              </Tooltip>
                            </Group>
                          }
                          styles={{
                            input: {
                              fontFamily: showCurrentPassword ? "inherit" : "monospace",
                              letterSpacing: showCurrentPassword ? "normal" : "2px",
                            },
                          }}
                        />
                      )}
                    </Stack>
                  ) : (
                    <Stack gap="xs">
                      <PasswordInput
                        placeholder="New Password"
                        value={draftPassword}
                        onChange={(e) => setDraftPassword(e.currentTarget.value)}
                      />
                      <PasswordInput
                        placeholder="Confirm Password"
                        value={draftPasswordConfirm}
                        onChange={(e) => setDraftPasswordConfirm(e.currentTarget.value)}
                      />
                      <Group justify="flex-end">
                        <Button variant="subtle" size="xs" onClick={() => setPasswordAction("keep")}>Cancel Password Change</Button>
                      </Group>
                    </Stack>
                  )}
                </div>
              </Stack>

              <Divider my="xl" />

              <Text fw={700} size="sm" mb="md" c="dimmed" style={{ letterSpacing: "1px" }}>COVER</Text>
              <Stack gap="md">
                <div style={{
                  height: "140px",
                  width: "100%",
                  borderRadius: "8px",
                  border: "1px solid var(--border-subtle)",
                  overflow: "hidden",
                  background: "var(--bg-elevated)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center"
                }}>
                  {coverPreview ? (
                    <Image src={coverPreview} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  ) : (
                    <Text c="dimmed" size="sm">No cover photo</Text>
                  )}
                </div>
                
                <Group>
                  <FileButton onChange={handleFileChange} accept="image/png,image/jpeg,image/webp">
                    {(props) => <Button {...props} variant="light" size="xs" disabled={owner !== user?.id}>Change Cover</Button>}
                  </FileButton>
                  {coverPreview && (
                    <Button variant="subtle" color="red" size="xs" onClick={() => { setCoverFile(null); setCoverPreview(null); setClearCover(true); }} disabled={owner !== user?.id}>
                      Remove
                    </Button>
                  )}
                </Group>
              </Stack>
            </div>
          </SimpleGrid>
        )}
      </div>
      
      {/* FOOTER */}
      <div style={{
        padding: "16px 24px",
        borderTop: "1px solid var(--border-subtle)",
        background: "var(--bg-elevated)",
        display: "flex",
        justifyContent: "flex-end",
        gap: "12px",
        borderBottomLeftRadius: "8px",
        borderBottomRightRadius: "8px"
      }}>
        <Button variant="default" onClick={() => setModalOpen(false)}>Cancel</Button>
        <Button onClick={handleSave} loading={isLoading}>Save Changes</Button>
      </div>
    </Modal>
  );
};

import React, { useState } from "react";
import { Link } from "react-router-dom";
import { IconAdjustments, IconCheck, IconChevronDown, IconCopy, IconCrown, IconLock, IconLockOpen, IconSettings, IconUsers, IconX } from "@tabler/icons-react";
import { Menu, Tooltip } from "@mantine/core";
import { SignInButton } from "./TopBar";
import { HeaderSearchBar } from "./HeaderSearchBar";
import { WaitingParticipantsPopover } from "../WaitingLounge/WaitingParticipantsPopover";
import styles from "./RoomHeader.module.css";

interface RoomHeaderProps {
  roomTitle: string;
  roomStatus?: string;
  participantCount?: number;
  currentTab?: string;
  onSelectTab?: (tab: "people" | "chat") => void;
  onOpenSettings: () => void;
  onExit: () => void;
  isLocked?: boolean;
  onToggleLock?: () => void;
  haveLock?: boolean;
  currentMedia?: string;
  mediaDisplayName?: string;
  onOpenQuickAdd?: () => void;
  roomSetMedia?: (value: string) => void;
  playlistAdd?: (value: string) => void;
  mediaPath?: string;
  waitingList?: WaitingGuest[];
  onAdmitAll?: () => void;
  onAdmitUser?: (clientId: string) => void;
  onDeclineUser?: (clientId: string) => void;
  isOwner?: boolean;
  onLogoClick?: () => void;
}

export const RoomHeader: React.FC<RoomHeaderProps> = ({
  roomTitle,
  roomStatus,
  participantCount,
  currentTab,
  onSelectTab,
  onOpenSettings,
  onExit,
  isLocked,
  onToggleLock,
  haveLock,
  currentMedia,
  mediaDisplayName,
  onOpenQuickAdd,
  roomSetMedia,
  playlistAdd,
  mediaPath,
  waitingList,
  onAdmitAll,
  onAdmitUser,
  onDeclineUser,
  isOwner,
  onLogoClick,
}) => {
  const [copied, setCopied] = useState(false);
  const isRoomActive = roomStatus === "active" || roomStatus === "expiring";

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    } catch {
      setCopied(false);
    }
  };

  const renderStatusBadge = () => {
    if (!roomStatus) return null;
    const status = roomStatus;
    if (status === "active") return <div className={`${styles.roomStatusBadge} ${styles.statusLive}`}><div className={styles.dot} /> LIVE</div>;
    if (status === "waiting" || status === "scheduled") return <div className={`${styles.roomStatusBadge} ${styles.statusWaiting}`}>WAITING</div>;
    if (status === "ended" || status === "expired") return <div className={`${styles.roomStatusBadge} ${styles.statusEnded}`}>{status.toUpperCase()}</div>;
    if (status === "cancelled") return <div className={`${styles.roomStatusBadge} ${styles.statusCancelled}`}>CANCELLED</div>;
    return null;
  };

  const roomIdentity = (
    <div className={styles.roomIdentity}>
      <div className={styles.roomTitleRow}>
        {renderStatusBadge()}
        {isOwner && (
          <span className={styles.hostBadge}>
            <IconCrown size={12} stroke={2.5} />
            <span>Host</span>
          </span>
        )}
        <span className={styles.roomTitle} title={roomTitle || "Watch Party Room"}>
          {roomTitle || "Watch Party Room"}
        </span>
      </div>
      <Tooltip
        label={currentMedia ? `Now Playing: ${mediaDisplayName || currentMedia} (Click to change)` : "Nothing playing (Click to add media)"}
        position="bottom"
        openDelay={300}
      >
        <button
          type="button"
          className={styles.nowPlayingSubtitle}
          onClick={onOpenQuickAdd}
          title={currentMedia ? `Playing: ${mediaDisplayName || currentMedia}` : "Add something to play"}
        >
          <span className={currentMedia ? styles.playingDot : styles.idleDot} />
          <span className={styles.nowPlayingSubtitleLabel}>{currentMedia ? "Playing" : "Nothing playing"}</span>
          {currentMedia && <span className={styles.nowPlayingSubtitleTitle}>{mediaDisplayName || currentMedia}</span>}
        </button>
      </Tooltip>
    </div>
  );

  return (
    <header className={styles.header}>
      <div className={styles.leftSection}>
        {onLogoClick ? (
          <button type="button" className={styles.logoLink} onClick={onLogoClick} title="Exit to Home">
            <img src="/logo192.png" alt="CoWatch" className={styles.logoImg} />
            <span className={styles.logoText}>CoWatch</span>
          </button>
        ) : (
          <Link to="/" className={styles.logoLink} title="Exit to Home">
            <img src="/logo192.png" alt="CoWatch" className={styles.logoImg} />
            <span className={styles.logoText}>CoWatch</span>
          </Link>
        )}

        <div className={styles.divider} aria-hidden="true" />

        {roomIdentity}
      </div>

      <div className={styles.centerSection}>
        {roomSetMedia && playlistAdd && (
          <div className={styles.searchSection}>
            <HeaderSearchBar roomSetMedia={roomSetMedia} playlistAdd={playlistAdd} mediaPath={mediaPath} disabled={!haveLock} />
          </div>
        )}
      </div>

      <div className={styles.rightSection}>
        <button
          type="button"
          className={`${styles.actionBtn} ${copied ? styles.actionBtnCopied : ""}`}
          onClick={handleCopyLink}
          title={copied ? "Invite link copied to clipboard!" : "Copy room invite link"}
          aria-label="Copy room invite link"
        >
          {copied ? <IconCheck size={15} stroke={2.5} /> : <IconCopy size={15} stroke={1.8} />}
          <span className={styles.actionBtnLabel}>{copied ? "Copied" : "Invite"}</span>
        </button>

        {isOwner && waitingList && waitingList.length > 0 && (
          <WaitingParticipantsPopover waitingList={waitingList} onAdmitUser={onAdmitUser} onDeclineUser={onDeclineUser} onAdmitAll={onAdmitAll} position="bottom-end">
            <button type="button" className={styles.waitingHeaderBtn} title={`${waitingList.length} guest(s) waiting in lounge - Click to review`}>
              <div className={styles.waitingHeaderDot} />
              <IconUsers size={15} stroke={2} />
              <span className={styles.waitingHeaderCount}>{waitingList.length}</span>
            </button>
          </WaitingParticipantsPopover>
        )}

        <Menu shadow="xl" width={220} position="bottom-end" offset={8}>
          <Menu.Target>
            <button
              type="button"
              className={styles.iconOnlyBtn}
              onClick={onOpenSettings}
              aria-label={isRoomActive ? "Preferences" : "Room settings"}
              title={isRoomActive ? "Preferences" : "Room settings"}
            >
              <IconSettings size={17} stroke={1.6} />
            </button>
          </Menu.Target>
          <Menu.Dropdown>
            <Menu.Label>{isOwner ? "Host Controls" : "Room"}</Menu.Label>
            <Menu.Item leftSection={<IconSettings size={16} />} onClick={onOpenSettings}>
              {isRoomActive ? "Preferences" : "Room settings"}
            </Menu.Item>
            {isOwner && (
              <Menu.Item leftSection={<IconAdjustments size={16} />} onClick={() => {
                const cleanId = window.location.pathname.replace(/^\/watch\//, "");
                window.open(`/myrooms/${cleanId}`, "_blank");
              }}>
                {isRoomActive ? "View in Dashboard" : "Manage in Dashboard"}
              </Menu.Item>
            )}
            <Menu.Item leftSection={copied ? <IconCheck size={16} color="var(--color-live)" /> : <IconCopy size={16} />} onClick={handleCopyLink}>
              {copied ? "Link Copied!" : "Copy invite link"}
            </Menu.Item>
            {onToggleLock && (
              <Menu.Item disabled={!haveLock} leftSection={isLocked ? <IconLock size={16} color="var(--color-warning)" /> : <IconLockOpen size={16} />} onClick={onToggleLock}>
                {isLocked ? "Unlock room controls" : "Lock room controls"}
              </Menu.Item>
            )}
            <Menu.Divider />
            <Menu.Item color="red" leftSection={<IconX size={16} />} onClick={onExit}>{isOwner ? "Exit Room Session" : "Leave room"}</Menu.Item>
          </Menu.Dropdown>
        </Menu>

        <SignInButton />
      </div>
    </header>
  );
};

import React, { useContext, useState } from "react";
import { Menu } from "@mantine/core";
import { Socket } from "socket.io-client";
// import styles from './UserMenu.module.css';
import { MetadataContext } from "../../MetadataContext";
import { IconBan, IconTrashFilled, IconX } from "@tabler/icons-react";
import { getOrCreateClientId } from "../../utils/utils";

const clientId = getOrCreateClientId();

export const UserMenu = ({
  socket,
  userToManage,
  trigger,
  displayName,
  disabled,
  timestamp,
  isChatMessage,
}: {
  socket: Socket;
  userToManage: string;
  trigger: React.ReactNode;
  icon?: string;
  displayName?: string;
  disabled: boolean;
  timestamp?: string;
  isChatMessage?: boolean;
}) => {
  const { user } = useContext(MetadataContext);
  const isSelf =
    userToManage === clientId ||
    (Boolean(user?.id) && userToManage === user?.id);

  return (
    <Menu
      closeOnItemClick
      closeOnClickOutside
      disabled={disabled}
      trigger="click"
    >
      <Menu.Target>{trigger}</Menu.Target>
      <Menu.Dropdown>
        <Menu.Label>{displayName}</Menu.Label>

        {isChatMessage && (
          <Menu.Item
            leftSection={<IconX />}
            onClick={async () => {
              socket.emit("CMD:deleteChatMessages", {
                author: userToManage,
                timestamp: timestamp,
              });
            }}
          >
            Delete Message
          </Menu.Item>
        )}
        {!isSelf && (
          <>
            <Menu.Item
              leftSection={<IconTrashFilled />}
              onClick={async () => {
                socket.emit("CMD:deleteChatMessages", {
                  author: userToManage,
                });
              }}
            >
              Delete User's Messages
            </Menu.Item>
            <Menu.Item
              leftSection={<IconBan />}
              onClick={async () => {
                socket.emit("CMD:kickUser", {
                  userToBeKicked: userToManage,
                });
              }}
            >
              Kick User
            </Menu.Item>
          </>
        )}
      </Menu.Dropdown>
    </Menu>
  );
};

import React from "react";

import { EVENT } from "./events";
import { NekoClient } from "./client";
import GuacamoleKeyboard from "./keyboard";
import config from "../../config";
import { VIDEO_MAX_HEIGHT_CSS } from "../../utils/utils";
import { Button } from "@mantine/core";
import { IconClipboard, IconKeyboardFilled } from "@tabler/icons-react";

export class VBrowser extends React.Component<{
  username: string;
  password: string;
  hostname: string;
  controlling: boolean;
  resolution: string;
  setResolution: (resolution: string) => void;
  quality: string;
  setQuality: (quality: string) => void;
  doPlay: () => Promise<void>;
  isMobile: boolean;
}> {
  state = { dummyValue: "" };
  // private observer = new ResizeObserver(this.onResize);
  private keyboard = GuacamoleKeyboard();
  private focused = false;
  private fullscreen = false;
  private activeKeys: Set<number> = new Set();
  private controlling = false;
  private scroll = 1; // 1 to 10
  private scroll_invert = true;
  private width = 1280;
  private height = 720;
  private rate = 30;
  private keepAliveInterval = 0;
  // private _component = React.createRef<HTMLDivElement>();
  private _container = React.createRef<HTMLDivElement>();
  private _overlay = React.createRef<HTMLDivElement>();
  // private _aspect = React.createRef<HTMLDivElement>();
  // private _player = React.createRef<HTMLDivElement>();
  private _video = React.createRef<HTMLVideoElement>();
  // private _resolution = React.createRef<HTMLDivElement>();
  private $client: NekoClient = new NekoClient();

  componentDidMount() {
    this.controlling = this.props.controlling;
    this.keepAliveInterval = window.setInterval(
      () => this.$client.sendMessage("chat/message"),
      30000,
    );

    this.$client.on(EVENT.CONNECTED, () => {
      if (this.props.controlling) {
        this.takeControl();
      }
    });
    this.$client.on(EVENT.DISCONNECTED, () => {
      this.$client.login(url, this.props.password, this.props.username);
    });
    this.$client.on(EVENT.SCREEN.RESOLUTION, (data) => {
      this.width = data.width;
      this.height = data.height;
      this.rate = data.rate;
      // Update our state with the resolution sent from server
      this.props.setResolution(`${this.width}x${this.height}@${this.rate}`);
      this.props.setQuality(String(data.quality));
    });
    this.$client.on(EVENT.TRACK, async (track: MediaStreamTrack, stream) => {
      // console.log(track, streams);
      const video = document.getElementById("leftVideo") as HTMLVideoElement;
      video.src = "";
      video.srcObject = stream;
      // Manually play audio for iPhone Safari since this seems to create two separate streams
      if (stream.getTracks().length === 1 && track.kind === "audio") {
        const audio = document.getElementById(
          "iPhoneAudio",
        ) as HTMLAudioElement;
        audio.srcObject = new MediaStream([track]);
        void audio.play();
      }
      await this.props.doPlay();
    });
    this.$client.on(EVENT.CONTROL.CLIPBOARD, this.onClipboardChanged);

    if (config.NODE_ENV === "development") {
      this.$client.on("debug", (e, data) => console.log(e, data));
    }

    const url =
      location.protocol.replace("http", "ws") +
      "//" +
      this.props.hostname +
      "/ws";
    this.$client.login(url, this.props.password, this.props.username);

    // this._container.current?.addEventListener('resize', this.onResize);
    // this.onResize();

    // document.addEventListener('fullscreenchange', () => {
    //   this.onResize();
    // });

    // document.addEventListener('focusin', this.onFocus.bind(this));
    // document.addEventListener('focusout', this.onBlur.bind(this));

    document
      .getElementById("leftOverlay")
      ?.addEventListener("wheel", this.onWheel, { passive: false });

    /* Initialize Guacamole Keyboard */
    this.keyboard.onkeydown = (key: number) => {
      if (!this.focused || !this.controlling) {
        return true;
      }
      const keyToSend = this.keyMap(key);
      this.$client.sendData("keydown", { key: keyToSend });
      return false;
    };
    this.keyboard.onkeyup = (key: number) => {
      if (!this.focused || !this.controlling) {
        return;
      }
      this.$client.sendData("keyup", { key: this.keyMap(key) });
    };
    this.keyboard.listenTo(document.getElementById("leftOverlay")!);
  }

  componentDidUpdate(prevProps: any) {
    // console.log(this.props.controlling, prevProps.controlling);
    this.controlling = this.props.controlling;
    if (this.props.controlling && !prevProps.controlling) {
      this.takeControl();
    }
    if (
      this.props.resolution !== prevProps.resolution ||
      (this.props.quality && this.props.quality !== prevProps.quality)
    ) {
      this.changeResolution(this.props.resolution, this.props.quality);
    }
  }

  componentWillUnmount() {
    window.clearInterval(this.keepAliveInterval);
    this.$client.removeAllListeners();
    this.$client.logout();
  }

  takeControl = () => {
    if (this.$client.connected) {
      this.$client.sendMessage(EVENT.ADMIN.CONTROL);
      this.$client.sendMessage(EVENT.CONTROL.CLIPBOARD, { text: "" });
    } else {
      this.$client.once(EVENT.CONNECTED, () => {
        this.$client.sendMessage(EVENT.ADMIN.CONTROL);
        this.$client.sendMessage(EVENT.CONTROL.CLIPBOARD, { text: "" });
      });
    }
  };

  changeResolution = (resString: string, quality: string) => {
    const split = resString.split(/x|@/);
    const width = Number(split[0]);
    const height = Number(split[1]);
    const rate = Number(split[2]);
    this.$client.sendMessage(EVENT.SCREEN.SET, {
      width,
      height,
      rate,
      quality: Number(quality),
    });
  };

  onClipboardChanged(clipboard: string) {
    if (
      navigator.clipboard &&
      typeof navigator.clipboard.writeText === "function"
    ) {
      // Received clipboard contents from vbrowser
      void navigator.clipboard.writeText(clipboard);
    }
  }
  onFocus = async (e: React.MouseEvent) => {
    if (this.props.controlling) {
      if (
        navigator.clipboard &&
        typeof navigator.clipboard.readText === "function"
      ) {
        try {
          const text = await navigator.clipboard.readText();
          // send clipboard contents to vbrowser
          this.$client.sendMessage(EVENT.CONTROL.CLIPBOARD, { text });
        } catch (e) {
          console.warn(e);
        }
      }
      this.$client.sendMessage(EVENT.CONTROL.KEYBOARD, {
        capsLock: e.getModifierState("CapsLock"),
        numLock: e.getModifierState("NumLock"),
        scrollLock: e.getModifierState("ScrollLock"),
      });
    }
  };

  onBlur = () => {
    if (!this.focused || !this.controlling) {
      return;
    }

    // Reset the vbrowser clipboard (it will be repopulated the next time the controller focuses)
    this.$client.sendMessage(EVENT.CONTROL.CLIPBOARD, { text: "" });
    this.activeKeys.forEach((key) => {
      this.$client.sendData("keyup", { key });
      this.activeKeys.delete(key);
    });
  };

  onClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
  };

  onContextMenu = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
  };

  onMousePos = (e: MouseEvent | React.MouseEvent) => {
    const { w, h } = { w: this.width, h: this.height };
    const rect = this._overlay.current!.getBoundingClientRect();
    this.$client.sendData("mousemove", {
      x: Math.round((w / rect.width) * (e.clientX - rect.left)),
      y: Math.round((h / rect.height) * (e.clientY - rect.top)),
    });
  };

  onWheel = (e: WheelEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (!this.controlling) {
      return;
    }
    this.onMousePos(e);

    let x = e.deltaX;
    let y = e.deltaY;

    if (this.scroll_invert) {
      x = x * -1;
      y = y * -1;
    }

    x = Math.min(Math.max(x, -this.scroll), this.scroll);
    y = Math.min(Math.max(y, -this.scroll), this.scroll);

    this.$client.sendData("wheel", { x, y });
  };

  onMouseDown = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (!this.controlling) {
      return;
    }
    this.onMousePos(e);
    this.$client.sendData("mousedown", { key: e.button + 1 });
  };

  onMouseUp = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if (!this.controlling) {
      return;
    }
    this.onMousePos(e);
    this.$client.sendData("mouseup", { key: e.button + 1 });
  };

  onMouseMove = (e: React.MouseEvent) => {
    if (!this.controlling) {
      return;
    }
    this.onMousePos(e);
  };

  onMouseEnter = (e: React.MouseEvent) => {
    if (!this.controlling) {
      return;
    }
    this._overlay.current!.focus();
    void this.onFocus(e);
    this.focused = true;
  };

  onMouseLeave = (e: React.MouseEvent) => {
    if (!this.controlling) {
      return;
    }
    this._overlay.current!.blur();
    this.focused = false;
    this.keyboard.reset();
  };

  KeyTable = {
    XK_ISO_Level3_Shift: 0xfe03, // AltGr
    XK_Mode_switch: 0xff7e, // Character set switch
    XK_Control_L: 0xffe3, // Left control
    XK_Control_R: 0xffe4, // Right control
    XK_Meta_L: 0xffe7, // Left meta
    XK_Meta_R: 0xffe8, // Right meta
    XK_Alt_L: 0xffe9, // Left alt
    XK_Alt_R: 0xffea, // Right alt
    XK_Super_L: 0xffeb, // Left super
    XK_Super_R: 0xffec, // Right super
  };

  get hasMacOSKbd() {
    return /(Mac|iPhone|iPod|iPad)/i.test(navigator.platform);
  }

  keyMap(key: number): number {
    // Alt behaves more like AltGraph on macOS, so shuffle the
    // keys around a bit to make things more sane for the remote
    // server. This method is used by noVNC, RealVNC and TigerVNC
    // (and possibly others).
    if (this.hasMacOSKbd) {
      switch (key) {
        case this.KeyTable.XK_Meta_L:
          key = this.KeyTable.XK_Control_L;
          break;
        case this.KeyTable.XK_Super_L:
          key = this.KeyTable.XK_Alt_L;
          break;
        case this.KeyTable.XK_Super_R:
          key = this.KeyTable.XK_Super_L;
          break;
        case this.KeyTable.XK_Alt_L:
          key = this.KeyTable.XK_Mode_switch;
          break;
        case this.KeyTable.XK_Alt_R:
          key = this.KeyTable.XK_ISO_Level3_Shift;
          break;
      }
    }
    return key;
  }

  onResize = () => {
    // let height = 0;
    // if (!this.fullscreen) {
    //   const offsetWidth = this._component.current?.offsetWidth;
    //   const offsetHeight = this._component.current?.offsetHeight;
    //   this._player.current!.style.width = `${offsetWidth}px`;
    //   this._player.current!.style.height = `${offsetHeight}px`;
    //   height = offsetHeight;
    // } else {
    //   const offsetHeight = this._player.current?.offsetHeight;
    //   height = offsetHeight;
    // }
    // this._container.current!.style.maxWidth = `${
    //   (this.horizontal / this.vertical) * height
    // }px`;
    // this._aspect.current!.style.paddingBottom = `${
    //   (this.vertical / this.horizontal) * 100
    // }%`;
  };

  render() {
    // leftVideoParent is the target for fullscreen, which loses its style when set to fullscreenElement
    // extra container layer is to be able to keep styling for overlay/video
    return (
      <>
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            display: "flex",
            gap: "4px",
          }}
        >
          {this.props.isMobile && this.props.controlling && (
            <Button
              onClick={() => {
                const dummy = document.getElementById("dummy");
                dummy?.focus();
              }}
              leftSection={<IconKeyboardFilled />}
            >
              Open Keyboard
            </Button>
          )}
          {this.props.isMobile && this.props.controlling && (
            <Button
              onClick={async () => {
                // Guacamole ctrl v codes
                this.$client.sendData("keydown", { key: 65507 });
                this.$client.sendData("keydown", { key: 118 });
                this.$client.sendData("keyup", { key: 65507 });
                this.$client.sendData("keyup", { key: 118 });
              }}
              leftSection={<IconClipboard />}
            >
              Paste
            </Button>
          )}
        </div>
        <div
          id="leftVideoParent"
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            width: "100%",
            height: "100%",
          }}
        >
          <div
            ref={this._container}
            style={{
              position: "relative",
              width: "100%",
              height: document.getElementById("leftVideo")?.clientHeight,
            }}
          >
            <video
              playsInline
              ref={this._video}
              id="leftVideo"
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                // maxHeight: document.fullscreenElement ? undefined : VIDEO_MAX_HEIGHT_CSS,
              }}
            />
            <div
              ref={this._overlay}
              id={"leftOverlay"}
              tabIndex={0}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: document.getElementById("leftVideo")?.clientWidth,
                height: document.getElementById("leftVideo")?.clientHeight,
                // disable firefox scrollbars?
                scrollbarWidth: "none",
              }}
              onClick={this.onClick}
              onContextMenu={this.onContextMenu}
              // onWheel={this.onWheel}
              onMouseMove={this.onMouseMove}
              onMouseDown={this.onMouseDown}
              onMouseUp={this.onMouseUp}
              onMouseEnter={this.onMouseEnter}
              onMouseLeave={this.onMouseLeave}
            />
            <audio id="iPhoneAudio" />
            {/* <div id="debug" style={{ position: 'fixed', top: 0, fontSize: 24 }} /> */}
            <input
              type="text"
              id="dummy"
              value={this.state.dummyValue}
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                height: 0,
                opacity: 0,
              }}
              onFocus={() => {
                this.focused = true;
                this.setState({ dummyValue: "" });
              }}
              onBlur={() => {
                this.focused = false;
                this.setState({ dummyValue: "" });
              }}
              onKeyDown={(e) => {
                e.nativeEvent.preventDefault();
                // document.getElementById('debug')!.innerHTML = e.key;
                // On mobile this is "unidentified" for content chars, so this is meant for backspace/enter
                if (e.key !== "Unidentified") {
                  document
                    .getElementById("leftOverlay")
                    ?.dispatchEvent(
                      new KeyboardEvent("keydown", { key: e.key }),
                    );
                  document
                    .getElementById("leftOverlay")
                    ?.dispatchEvent(new KeyboardEvent("keyup", { key: e.key }));
                }
              }}
              onBeforeInputCapture={(
                e: React.SyntheticEvent<HTMLInputElement, Event>,
              ) => {
                e.nativeEvent.preventDefault();
                // document.getElementById('debug')!.innerHTML = e.type + ' ' + e.data;
                if (e.type === "beforeinput") {
                  document.getElementById("leftOverlay")?.dispatchEvent(
                    new KeyboardEvent("keydown", {
                      key: (e as any).data,
                      shiftKey:
                        (e as any).data ===
                        (e as any).data.toUpperCase(),
                    }),
                  );
                  document.getElementById("leftOverlay")?.dispatchEvent(
                    new KeyboardEvent("keyup", {
                      key: (e as any).data,
                    }),
                  );
                }
              }}
            />
          </div>
        </div>
      </>
    );
  }
}

import EventEmitter from "eventemitter3";
import { OPCODE } from "./data";
import { EVENT, WebSocketEvents } from "./events";

import {
  WebSocketMessages,
  WebSocketPayloads,
  SignalProvidePayload,
  SignalCandidatePayload,
  SignalOfferPayload,
  SignalAnswerMessage,
} from "./messages";

// export interface BaseEvents {
//   info: (...message: any[]) => void;
//   warn: (...message: any[]) => void;
//   debug: (...message: any[]) => void;
//   error: (error: Error) => void;
// }

export abstract class BaseClient extends EventEmitter<any> {
  protected _ws?: WebSocket;
  protected _peer?: RTCPeerConnection;
  protected _channel?: RTCDataChannel;
  protected _timeout?: number;
  protected _displayname?: string;
  protected _state: RTCIceConnectionState = "disconnected";
  protected _id = "";
  protected _candidates: RTCIceCandidate[] = [];

  get id() {
    return this._id;
  }

  get supported() {
    return (
      typeof RTCPeerConnection !== "undefined" &&
      typeof RTCPeerConnection.prototype.addTransceiver !== "undefined"
    );
  }

  get socketOpen() {
    return (
      typeof this._ws !== "undefined" && this._ws.readyState === WebSocket.OPEN
    );
  }

  get peerConnected() {
    return (
      typeof this._peer !== "undefined" &&
      ["connected", "checking", "completed"].includes(this._state)
    );
  }

  get connected() {
    return this.peerConnected && this.socketOpen;
  }

  public connect(url: string, password: string, displayname: string) {
    if (this.socketOpen) {
      this.emit("warn", `attempting to create websocket while connection open`);
      return;
    }

    if (!this.supported) {
      this.onDisconnected(
        new Error(
          "browser does not support webrtc (RTCPeerConnection missing)",
        ),
      );
      return;
    }

    this._displayname = displayname;
    this[EVENT.CONNECTING]();

    try {
      this._ws = new WebSocket(
        `${url}?password=${encodeURIComponent(password)}`,
      );
      this.emit("debug", `connecting to ${this._ws.url}`);
      this._ws.onmessage = this.onMessage.bind(this);
      this._ws.onerror = () => this.onError.bind(this);
      this._ws.onclose = () =>
        this.onDisconnected.bind(this, new Error("websocket closed"));
      this._timeout = window.setTimeout(this.onTimeout.bind(this), 15000);
    } catch (err: any) {
      this.onDisconnected(err);
    }
  }

  protected disconnect() {
    if (this._timeout) {
      clearTimeout(this._timeout);
      this._timeout = undefined;
    }

    if (this._ws) {
      // reset all events
      this._ws.onmessage = () => {};
      this._ws.onerror = () => {};
      this._ws.onclose = () => {};

      try {
        this._ws.close();
      } catch (err) {}

      this._ws = undefined;
    }

    if (this._channel) {
      // reset all events
      this._channel.onmessage = () => {};
      this._channel.onerror = () => {};
      this._channel.onclose = () => {};

      try {
        this._channel.close();
      } catch (err) {}

      this._channel = undefined;
    }

    if (this._peer) {
      // reset all events
      this._peer.onconnectionstatechange = () => {};
      this._peer.onsignalingstatechange = () => {};
      this._peer.oniceconnectionstatechange = () => {};
      this._peer.ontrack = () => {};

      try {
        this._peer.close();
      } catch (err) {}

      this._peer = undefined;
    }

    this._state = "disconnected";
    this._displayname = undefined;
    this._id = "";
  }

  public sendData(
    event: "wheel" | "mousemove",
    data: { x: number; y: number },
  ): void;
  public sendData(
    event: "mousedown" | "mouseup" | "keydown" | "keyup",
    data: { key: number },
  ): void;
  public sendData(event: string, data: any) {
    if (!this.connected) {
      this.emit("warn", `attempting to send data while disconnected`);
      return;
    }

    let buffer: ArrayBuffer;
    let payload: DataView;
    switch (event) {
      case "mousemove":
        buffer = new ArrayBuffer(7);
        payload = new DataView(buffer);
        payload.setUint8(0, OPCODE.MOVE);
        payload.setUint16(1, 4, true);
        payload.setUint16(3, data.x, true);
        payload.setUint16(5, data.y, true);
        break;
      case "wheel":
        buffer = new ArrayBuffer(7);
        payload = new DataView(buffer);
        payload.setUint8(0, OPCODE.SCROLL);
        payload.setUint16(1, 4, true);
        payload.setInt16(3, data.x, true);
        payload.setInt16(5, data.y, true);
        break;
      case "keydown":
      case "mousedown":
        buffer = new ArrayBuffer(11);
        payload = new DataView(buffer);
        payload.setUint8(0, OPCODE.KEY_DOWN);
        payload.setUint16(1, 8, true);
        payload.setBigUint64(3, BigInt(data.key), true);
        break;
      case "keyup":
      case "mouseup":
        buffer = new ArrayBuffer(11);
        payload = new DataView(buffer);
        payload.setUint8(0, OPCODE.KEY_UP);
        payload.setUint16(1, 8, true);
        payload.setBigUint64(3, BigInt(data.key), true);
        break;
      default:
        this.emit("warn", `unknown data event: ${event}`);
    }

    // @ts-expect-error
    if (typeof buffer !== "undefined") {
      this._channel!.send(buffer);
    }
  }

  public sendMessage(event: WebSocketEvents, payload?: WebSocketPayloads) {
    if (!this.connected) {
      this.emit("warn", `attempting to send message while disconnected`);
      return;
    }
    this.emit(
      "debug",
      `sending event '${event}' ${payload ? `with payload: ` : ""}`,
      payload,
    );
    this._ws!.send(JSON.stringify({ event, ...payload }));
  }

  public async createPeer(lite: boolean, servers: RTCIceServer[]) {
    this.emit("debug", `creating peer`);
    if (!this.socketOpen) {
      this.emit(
        "warn",
        `attempting to create peer with no websocket: `,
        this._ws ? `state: ${this._ws.readyState}` : "no socket",
      );
      return;
    }

    if (this.peerConnected) {
      this.emit("warn", `attempting to create peer while connected`);
      return;
    }

    if (lite !== true) {
      this._peer = new RTCPeerConnection({
        iceServers: servers,
      });
    } else {
      this._peer = new RTCPeerConnection();
    }

    this._peer.onconnectionstatechange = () => {
      this.emit(
        "debug",
        `peer connection state changed`,
        this._peer ? this._peer.connectionState : undefined,
      );
    };

    this._peer.onsignalingstatechange = () => {
      this.emit(
        "debug",
        `peer signaling state changed`,
        this._peer ? this._peer.signalingState : undefined,
      );
    };

    this._peer.oniceconnectionstatechange = () => {
      this._state = this._peer!.iceConnectionState;

      this.emit(
        "debug",
        `peer ice connection state changed: ${this._peer!.iceConnectionState}`,
      );

      switch (this._state) {
        case "checking":
          if (this._timeout) {
            clearTimeout(this._timeout);
            this._timeout = undefined;
          }
          break;
        case "connected":
          this.onConnected();
          break;
        case "disconnected":
          this[EVENT.RECONNECTING]();
          break;
        // https://developer.mozilla.org/en-US/docs/Web/API/WebRTC_API/Signaling_and_video_calling#ice_connection_state
        // We don't watch the disconnected signaling state here as it can indicate temporary issues and may
        // go back to a connected state after some time. Watching it would close the video call on any temporary
        // network issue.
        case "failed":
          this.onDisconnected(new Error("peer failed"));
          break;
        case "closed":
          this.onDisconnected(new Error("peer closed"));
          break;
      }
    };

    this._peer.ontrack = this.onTrack.bind(this);

    this._peer.onicecandidate = (event: RTCPeerConnectionIceEvent) => {
      if (!event.candidate) {
        this.emit("debug", `sent all local ICE candidates`);
        return;
      }

      const init = event.candidate.toJSON();
      this.emit("debug", `sending local ICE candidate`, init);

      this._ws!.send(
        JSON.stringify({
          event: EVENT.SIGNAL.CANDIDATE,
          data: JSON.stringify(init),
        }),
      );
    };

    this._peer.onnegotiationneeded = async () => {
      this.emit("warn", `negotiation is needed`);

      const d = await this._peer!.createOffer();
      await this._peer!.setLocalDescription(d);

      this._ws!.send(
        JSON.stringify({
          event: EVENT.SIGNAL.OFFER,
          sdp: d.sdp,
        }),
      );
    };

    this._channel = this._peer.createDataChannel("data");
    this._channel.onerror = this.onError.bind(this);
    this._channel.onmessage = this.onData.bind(this);
    this._channel.onclose = this.onDisconnected.bind(
      this,
      new Error("peer data channel closed"),
    );
  }

  public async setRemoteOffer(sdp: string) {
    if (!this._peer) {
      this.emit("warn", `attempting to set remote offer while disconnected`);
      return;
    }

    await this._peer.setRemoteDescription({ type: "offer", sdp });

    for (const candidate of this._candidates) {
      await this._peer.addIceCandidate(candidate);
    }
    this._candidates = [];

    try {
      const d = await this._peer.createAnswer();

      // add stereo=1 to answer sdp to enable stereo audio for chromium
      d.sdp = d.sdp?.replace(
        /(stereo=1;)?useinbandfec=1/,
        "useinbandfec=1;stereo=1",
      );

      void this._peer!.setLocalDescription(d);

      this._ws!.send(
        JSON.stringify({
          event: EVENT.SIGNAL.ANSWER,
          sdp: d.sdp,
          displayname: this._displayname,
        }),
      );
    } catch (err: any) {
      this.emit("error", err);
    }
  }

  public async setRemoteAnswer(sdp: string) {
    if (!this._peer) {
      this.emit("warn", `attempting to set remote answer while disconnected`);
      return;
    }

    await this._peer.setRemoteDescription({ type: "answer", sdp });
  }

  private async onMessage(e: MessageEvent) {
    const { event, ...payload } = JSON.parse(e.data) as WebSocketMessages;

    this.emit(
      "debug",
      `received websocket event ${event} ${payload ? `with payload: ` : ""}`,
      payload,
    );

    if (event === EVENT.SIGNAL.PROVIDE) {
      const { sdp, lite, ice, id } = payload as SignalProvidePayload;
      this._id = id;
      await this.createPeer(lite, ice);
      await this.setRemoteOffer(sdp);
      return;
    }

    if (event === EVENT.SIGNAL.OFFER) {
      const { sdp } = payload as SignalOfferPayload;
      await this.setRemoteOffer(sdp);
      return;
    }

    if (event === EVENT.SIGNAL.ANSWER) {
      const { sdp } = payload as SignalAnswerMessage;
      await this.setRemoteAnswer(sdp);
      return;
    }

    if (event === EVENT.SIGNAL.CANDIDATE) {
      const { data } = payload as SignalCandidatePayload;
      const candidate: RTCIceCandidate = JSON.parse(data);
      if (this._peer) {
        void this._peer.addIceCandidate(candidate);
      } else {
        this._candidates.push(candidate);
      }
      return;
    }

    // @ts-expect-error
    if (typeof this[event] === "function") {
      // @ts-expect-error
      this[event](payload);
    } else {
      this[EVENT.MESSAGE](event, payload);
    }
  }

  private onData(e: MessageEvent) {
    this[EVENT.DATA](e.data);
  }

  private onTrack(event: RTCTrackEvent) {
    this.emit(
      "debug",
      `received ${event.track.kind} track from peer: ${event.track.id}`,
      event,
    );
    const stream = event.streams[0];
    if (!stream) {
      this.emit(
        "warn",
        `no stream provided for track ${event.track.id}(${event.track.label})`,
      );
      return;
    }
    this[EVENT.TRACK](event);
  }

  private onError(event: Event) {
    this.emit("error", (event as ErrorEvent).error);
  }

  private onConnected() {
    if (this._timeout) {
      clearTimeout(this._timeout);
      this._timeout = undefined;
    }

    if (!this.connected) {
      this.emit("warn", `onConnected called while being disconnected`);
      return;
    }

    this.emit("debug", `connected`);
    this[EVENT.CONNECTED]();
  }

  private onTimeout() {
    this.emit("debug", `connection timeout`);
    if (this._timeout) {
      clearTimeout(this._timeout);
      this._timeout = undefined;
    }
    this.onDisconnected(new Error("connection timeout"));
  }

  protected onDisconnected(reason?: Error) {
    this.disconnect();
    this.emit("debug", `disconnected:`, reason);
    this[EVENT.DISCONNECTED](reason);
  }

  protected [EVENT.MESSAGE](event: string, payload: any) {
    this.emit("warn", `unhandled websocket event '${event}':`, payload);
  }

  protected abstract [EVENT.RECONNECTING](): void;
  protected abstract [EVENT.CONNECTING](): void;
  protected abstract [EVENT.CONNECTED](): void;
  protected abstract [EVENT.DISCONNECTED](reason?: Error): void;
  protected abstract [EVENT.TRACK](event: RTCTrackEvent): void;
  protected abstract [EVENT.DATA](data: any): void;
}

