import React, { createContext, useContext, useEffect, useState } from "react";
import { AppearanceMode, AppearanceContextValue } from "./types";

const AppearanceContext = createContext<AppearanceContextValue | undefined>(undefined);

export const useAppearance = () => {
  const context = useContext(AppearanceContext);
  if (!context) {
    throw new Error("useAppearance must be used within an AppearanceProvider");
  }
  return context;
};

interface ThemeProviderProps {
  children: React.ReactNode;
  userAppearance?: AppearanceMode;
  onAppearanceChange?: (appearance: AppearanceMode) => void;
}

const resolveInitialScheme = (mode: AppearanceMode): "light" | "dark" => {
  if (mode === "light") return "light";
  if (mode === "mantine") return "dark";
  if (typeof window !== "undefined" && window.matchMedia) {
    return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  }
  return "dark";
};

export const ThemeProvider = ({
  children,
  userAppearance,
  onAppearanceChange,
}: ThemeProviderProps) => {
  // LocalStorage is authoritative for this browser session
  const [appearance, setAppearanceInternal] = useState<AppearanceMode>(() => {
    if (typeof window !== "undefined") {
      const local = localStorage.getItem("cowatch-appearance");
      if (local === "light" || local === "mantine" || local === "system") {
        return local as AppearanceMode;
      }
    }
    if (userAppearance && (userAppearance === "light" || userAppearance === "mantine" || userAppearance === "system")) {
      return userAppearance;
    }
    return "system";
  });

  const [resolvedColorScheme, setResolvedColorScheme] = useState<"light" | "dark">(() => {
    return resolveInitialScheme(appearance);
  });

  // Sync with userAppearance prop from DB ONLY if user has not explicitly set a local preference
  useEffect(() => {
    if (userAppearance) {
      const local = typeof window !== "undefined" ? localStorage.getItem("cowatch-appearance") : null;
      if (!local && (userAppearance === "light" || userAppearance === "mantine" || userAppearance === "system")) {
        setAppearanceInternal(userAppearance);
        try {
          localStorage.setItem("cowatch-appearance", userAppearance);
        } catch (e) {}
      }
    }
  }, [userAppearance]);

  // Resolve color scheme and update HTML data attribute
  useEffect(() => {
    const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)");
    
    const resolveAndApply = () => {
      let scheme: "light" | "dark" = "dark";
      if (appearance === "light") {
        scheme = "light";
      } else if (appearance === "mantine") {
        scheme = "dark";
      } else {
        scheme = mediaQuery.matches ? "dark" : "light";
      }
      
      setResolvedColorScheme(scheme);
      document.documentElement.setAttribute("data-color-scheme", scheme);
    };

    resolveAndApply();

    // Listen for system preference changes
    const listener = () => {
      if (appearance === "system") {
        resolveAndApply();
      }
    };

    mediaQuery.addEventListener("change", listener);
    return () => mediaQuery.removeEventListener("change", listener);
  }, [appearance]);

  const setAppearance = (mode: AppearanceMode) => {
    setAppearanceInternal(mode);
    try {
      localStorage.setItem("cowatch-appearance", mode);
    } catch (e) {}
    if (onAppearanceChange) {
      onAppearanceChange(mode);
    }
  };

  return (
    <AppearanceContext.Provider value={{ appearance, resolvedColorScheme, setAppearance }}>
      {children}
    </AppearanceContext.Provider>
  );
};

/**
 * Real Picture-in-Picture Manager for CoWatch Cinema
 * Provides true OS-level Picture-in-Picture floating windows (like WhatsApp / YouTube)
 * supporting both YouTube embedded media and HTML5 video streams with active playback,
 * participant controls, and instant room restoration.
 */

export interface PiPOptions {
  roomTitle: string;
  mediaUrl?: string;
  isYouTube: boolean;
  isNative: boolean;
  videoElement: HTMLVideoElement | null;
  currentTime: number;
  duration: number;
  isMuted: boolean;
  isMicEnabled: boolean;
  isVideoEnabled: boolean;
  onReturnToRoom: () => void;
  onToggleMic: () => void;
  onToggleVideo: () => void;
  onSyncTime?: (time: number) => void;
  onClose?: () => void;
}

export function extractYouTubeId(url: string): string | null {
  if (!url) return null;
  try {
    const trimmed = url.trim();
    const parsed = new URL(trimmed.startsWith("http") ? trimmed : `https://${trimmed}`);
    if (parsed.hostname.includes("youtube.com")) {
      const v = parsed.searchParams.get("v");
      if (v) return v;
      const pathParts = parsed.pathname.split("/").filter(Boolean);
      if (pathParts[0] === "embed" || pathParts[0] === "v") {
        return pathParts[1] || null;
      }
    }
    if (parsed.hostname.includes("youtu.be")) {
      const pathParts = parsed.pathname.split("/").filter(Boolean);
      return pathParts[0]?.split("?")[0] || null;
    }
  } catch {
    // Fallback regex if URL parsing fails
    const match = url.match(/(?:youtu\.be\/|youtube\.com\/(?:embed\/|v\/|watch\?v=|watch\?.+&v=))([\w-]{11})/);
    return match ? match[1] : null;
  }
  return null;
}

export function isDocumentPiPSupported(): boolean {
  return typeof window !== "undefined" && Boolean(window.documentPictureInPicture?.requestWindow);
}

export function isPiPActive(): boolean {
  if (typeof window === "undefined") return false;
  const docPipActive = Boolean(
    window.documentPictureInPicture?.window && !window.documentPictureInPicture.window.closed
  );
  const nativePipActive = Boolean(document.pictureInPictureElement);
  return docPipActive || nativePipActive;
}

export async function closeRealPiP(): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    if (window.documentPictureInPicture?.window && !window.documentPictureInPicture.window.closed) {
      window.documentPictureInPicture.window.close();
    }
  } catch (e) {
    console.warn("[PiPManager] Error closing Document PiP:", e);
  }

  try {
    if (document.pictureInPictureElement) {
      await document.exitPictureInPicture();
    }
  } catch (e) {
    console.warn("[PiPManager] Error closing native video PiP:", e);
  }
}

export async function openRealPiP(options: PiPOptions): Promise<boolean> {
  if (typeof window === "undefined") return false;

  // If already open, focus the active PiP window
  if (window.documentPictureInPicture?.window && !window.documentPictureInPicture.window.closed) {
