    } else if (pathname.startsWith("/watch/")) {
      updatePageSEO({
        title: "Watch Party | CoWatch",
        description: "Join this live watch party on CoWatch.",
        noindex: true,
      });
    }
  }, [location.pathname]);

  return null;
};

import { createClient, type SupabaseClient, type User } from "@supabase/supabase-js";
